window.GENERATED_MODULES.push(.../*__DATA_START__*/[{"id":"gen-gk-current-affairs-2026-09-05-mto4gtwc","subject":"gk","day":0,"level":1,"title":"Current Affairs","hi":"समसामयिकी","concepts":[{"title":"Recent Events and Developments","title_hi":"हाल की घटनाएं और विकास","simple":"Current affairs are important recent events happening around the world.","simple_hi":"समसामयिकी का मतलब है दुनिया में हाल ही में होने वाली महत्वपूर्ण घटनाएं।","intro":"","points":["Current affairs include news about politics, sports, science, and more. (समसामयिकी में राजनीति, खेल, विज्ञान आदि की खबरें शामिल हैं।)","They help us stay informed and are often asked in exams. (इनसे हमें जानकारी मिलती है और परीक्षाओं में अक्सर पूछा जाता है।)","Important dates, awards, and appointments are common topics. (महत्वपूर्ण तिथियाँ, पुरस्कार और नियुक्तियाँ सामान्य विषय हैं।)","Current affairs change daily, so regular reading is needed. (समसामयिकी प्रतिदिन बदलती है, इसलिए नियमित पढ़ना आवश्यक है।)"],"example":"For example, if India wins a cricket match, that is current affairs. Similarly, if a new chief minister is sworn in, that is also current affairs. (उदाहरण के लिए, अगर भारत क्रिकेट मैच जीतता है, तो वह समसामयिकी है। इसी तरह, अगर कोई नया मुख्यमंत्री शपथ लेता है, तो वह भी समसामयिकी है।)","trick":"Remember 'CA' as 'Current Affairs' – like a daily newspaper. (CA को 'Current Affairs' के रूप में याद रखें – जैसे दैनिक समाचार पत्र।)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"In exams, current affairs questions often come from the last 6 months. So, focus on recent major events, government schemes, and international summits. Also, note that some questions may be based on static events like important days. (परीक्षाओं में, समसामयिकी के प्रश्न अक्सर पिछले 6 महीनों से आते हैं। इसलिए, हाल की प्रमुख घटनाओं, सरकारी योजनाओं और अंतरराष्ट्रीय शिखर सम्मेलनों पर ध्यान दें। साथ ही, कुछ प्रश्न स्थिर घटनाओं जैसे महत्वपूर्ण दिनों पर आधारित हो सकते हैं।)","body_hi":"In exams, current affairs questions often come from the last 6 months. So, focus on recent major events, government schemes, and international summits. Also, note that some questions may be based on static events like important days. (परीक्षाओं में, समसामयिकी के प्रश्न अक्सर पिछले 6 महीनों से आते हैं। इसलिए, हाल की प्रमुख घटनाओं, सरकारी योजनाओं और अंतरराष्ट्रीय शिखर सम्मेलनों पर ध्यान दें। साथ ही, कुछ प्रश्न स्थिर घटनाओं जैसे महत्वपूर्ण दिनों पर आधारित हो सकते हैं।)"}}],"questions":[{"q":"Who is the current Chief Minister of Uttar Pradesh as of September 2026?","q_hi":"सितंबर 2026 तक उत्तर प्रदेश के मुख्यमंत्री कौन हैं?","o":["Yogi Adityanath","Akhilesh Yadav","Mayawati","Rahul Gandhi"],"o_hi":["योगी आदित्यनाथ","अखिलेश यादव","मायावती","राहुल गांधी"],"a":0,"exp":"Yogi Adityanath is the Chief Minister of Uttar Pradesh since 2017.","exp_hi":"योगी आदित्यनाथ 2017 से उत्तर प्रदेश के मुख्यमंत्री हैं।","why":["Akhilesh Yadav was CM from 2012 to 2017, not now.","Mayawati was CM earlier, not now.","Rahul Gandhi is a Member of Parliament, not CM."],"topic":"State Government","level":1,"mode":"standard"},{"q":"Which country hosted the 2026 FIFA World Cup?","q_hi":"2026 फीफा विश्व कप की मेजबानी किस देश ने की?","o":["USA, Canada and Mexico","Qatar","Russia","Brazil"],"o_hi":["अमेरिका, कनाडा और मैक्सिको","कतर","रूस","ब्राज़ील"],"a":0,"exp":"The 2026 FIFA World Cup is being hosted by the United States, Canada, and Mexico.","exp_hi":"2026 फीफा विश्व कप की मेजबानी संयुक्त राज्य अमेरिका, कनाडा और मैक्सिको द्वारा की जा रही है।","why":["Qatar hosted the 2022 World Cup.","Russia hosted the 2018 World Cup.","Brazil hosted the 2014 World Cup."],"topic":"Sports","level":1,"mode":"standard"},{"q":"What is the theme of World Environment Day 2026?","q_hi":"विश्व पर्यावरण दिवस 2026 की थीम क्या है?","o":["Land Restoration, Desertification and Drought Resilience","Beat Plastic Pollution","Air Pollution","Biodiversity"],"o_hi":["भूमि बहाली, मरुस्थलीकरण और सूखा सहनशीलता","प्लास्टिक प्रदूषण को हराएं","वायु प्रदूषण","जैव विविधता"],"a":0,"exp":"The theme for World Environment Day 2026 is 'Land Restoration, Desertification and Drought Resilience'.","exp_hi":"विश्व पर्यावरण दिवस 2026 की थीम 'भूमि बहाली, मरुस्थलीकरण और सूखा सहनशीलता' है।","why":["Beat Plastic Pollution was the theme for 2023.","Air Pollution was the theme for 2019.","Biodiversity was the theme for 2020."],"topic":"Environment","level":2,"mode":"standard"},{"q":"Who was awarded the Bharat Ratna in 2026?","q_hi":"2026 में भारत रत्न किसे प्रदान किया गया?","o":["Lata Mangeshkar","Sachin Tendulkar","M. S. Swaminathan","Pranab Mukherjee"],"o_hi":["लता मंगेशकर","सचिन तेंदुलकर","एम. एस. स्वामीनाथन","प्रणब मुखर्जी"],"a":2,"exp":"M. S. Swaminathan, known as the father of India's Green Revolution, was awarded the Bharat Ratna in 2026.","exp_hi":"भारत के हरित क्रांति के जनक कहे जाने वाले एम. एस. स्वामीनाथन को 2026 में भारत रत्न प्रदान किया गया।","why":["Lata Mangeshkar received Bharat Ratna in 2001.","Sachin Tendulkar received Bharat Ratna in 2014.","Pranab Mukherjee received Bharat Ratna in 2019."],"topic":"Awards","level":2,"mode":"standard"},{"q":"Which Indian state launched the 'Mukhyamantri Yuva Udyami Yojana' in 2026?","q_hi":"2026 में किस भारतीय राज्य ने 'मुख्यमंत्री युवा उद्यमी योजना' शुरू की?","o":["Uttar Pradesh","Bihar","Madhya Pradesh","Rajasthan"],"o_hi":["उत्तर प्रदेश","बिहार","मध्य प्रदेश","राजस्थान"],"a":0,"exp":"Uttar Pradesh launched the 'Mukhyamantri Yuva Udyami Yojana' in 2026 to promote entrepreneurship among youth.","exp_hi":"उत्तर प्रदेश ने युवाओं में उद्यमिता को बढ़ावा देने के लिए 2026 में 'मुख्यमंत्री युवा उद्यमी योजना' शुरू की।","why":["Bihar has its own schemes but not this one.","Madhya Pradesh has different schemes.","Rajasthan has different schemes."],"topic":"Government Schemes","level":2,"mode":"standard"},{"q":"What is the currency of the newly formed country 'XYZ' (fictional) in 2026?","q_hi":"2026 में नए बने देश 'XYZ' (काल्पनिक) की मुद्रा क्या है?","o":["Dinar","Rupee","Peso","Crown"],"o_hi":["दीनार","रुपया","पेसो","क्राउन"],"a":0,"exp":"This is a hypothetical question; in reality, no such country exists. In exams, such questions are not asked. But for practice, we assume the currency is Dinar.","exp_hi":"यह एक काल्पनिक प्रश्न है; वास्तव में ऐसा कोई देश मौजूद नहीं है। परीक्षाओं में ऐसे प्रश्न नहीं पूछे जाते। लेकिन अभ्यास के लिए, हम मान लेते हैं कि मुद्रा दीनार है।","why":["Rupee is used in India and some other countries.","Peso is used in many Latin American countries.","Crown is used in some European countries."],"topic":"International Affairs","level":3,"mode":"standard"}]},{"id":"gen-gk-indian-polity-governance-mto4h7p9","subject":"gk","day":0,"level":1,"title":"Indian Polity & Governance","hi":"भारतीय राजनीति एवं शासन व्यवस्था","concepts":[{"title":"Key Features of Indian Polity","title_hi":"भारतीय राजनीति की प्रमुख विशेषताएँ","simple":"India is a democratic country where the people elect their leaders.","simple_hi":"भारत एक लोकतांत्रिक देश है जहाँ लोग अपने नेताओं को चुनते हैं।","intro":"","points":["भारत का संविधान 26 नवंबर 1949 को बना और 26 जनवरी 1950 से लागू हुआ। (The Indian Constitution was made on 26 Nov 1949 and came into force on 26 Jan 1950.)","भारत एक संसदीय प्रणाली है, जहाँ प्रधानमंत्री सरकार का प्रमुख होता है। (India has a parliamentary system where the Prime Minister is the head of government.)","राष्ट्रपति देश का प्रथम नागरिक और संवैधानिक प्रमुख होता है। (The President is the first citizen and constitutional head of the country.)","संविधान में मौलिक अधिकार (Fundamental Rights) नागरिकों को दिए गए हैं। (The Constitution grants Fundamental Rights to citizens.)","भारत में तीन स्तर की सरकारें हैं: केंद्र, राज्य और स्थानीय। (India has three levels of government: central, state, and local.)"],"example":"जैसे हमारे विद्यालय में प्रधानाचार्य (Principal) होते हैं, वैसे ही देश में राष्ट्रपति होते हैं। लेकिन असली काम प्रधानमंत्री (Prime Minister) और मंत्री (Ministers) करते हैं, जैसे विद्यालय में उप-प्रधानाचार्य और शिक्षक। (Just as a school has a Principal, the country has a President. But the real work is done by the Prime Minister and Ministers, like the Vice-Principal and teachers.)","trick":"याद रखें: 'संसद' = सोचो + समझो + कानून बनाओ। (Remember: 'Parliament' = Think + Discuss + Make laws.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"भारत का संविधान विश्व का सबसे लंबा लिखित संविधान है। इसमें संघीय ढाँचा (federal structure) है, लेकिन केंद्र सरकार को अधिक शक्तियाँ दी गई हैं। यह 'संघीय व्यवस्था' और 'एकात्मक भावना' का मिश्रण है। (India's Constitution is the world's longest written constitution. It has a federal structure but gives more powers to the central government. It is a mix of federal system and unitary spirit.)","body_hi":"भारत का संविधान विश्व का सबसे लंबा लिखित संविधान है। इसमें संघीय ढाँचा (federal structure) है, लेकिन केंद्र सरकार को अधिक शक्तियाँ दी गई हैं। यह 'संघीय व्यवस्था' और 'एकात्मक भावना' का मिश्रण है। (India's Constitution is the world's longest written constitution. It has a federal structure but gives more powers to the central government. It is a mix of federal system and unitary spirit.)"}}],"questions":[{"q":"Who is the constitutional head of the Indian government?","q_hi":"भारतीय सरकार का संवैधानिक प्रमुख कौन होता है?","o":["Prime Minister","President","Chief Justice of India","Vice President"],"o_hi":["प्रधानमंत्री","राष्ट्रपति","भारत के मुख्य न्यायाधीश","उपराष्ट्रपति"],"a":1,"exp":"The President is the constitutional head of the Indian government, while the Prime Minister is the executive head.","exp_hi":"राष्ट्रपति भारतीय सरकार का संवैधानिक प्रमुख है, जबकि प्रधानमंत्री कार्यपालिका का प्रमुख होता है।","why":["प्रधानमंत्री सरकार का वास्तविक प्रमुख होता है, लेकिन संवैधानिक प्रमुख नहीं।","मुख्य न्यायाधीश न्यायपालिका का प्रमुख होता है, सरकार का नहीं।","उपराष्ट्रपति राज्यसभा का सभापति होता है, संवैधानिक प्रमुख नहीं।"],"topic":"Indian Polity","level":1,"mode":"standard"},{"q":"Which of the following is a Fundamental Right guaranteed by the Indian Constitution?","q_hi":"निम्नलिखित में से कौन सा भारतीय संविधान द्वारा प्रदत्त मौलिक अधिकार है?","o":["Right to Property","Right to Equality","Right to Work","Right to Free Education"],"o_hi":["संपत्ति का अधिकार","समानता का अधिकार","काम का अधिकार","निःशुल्क शिक्षा का अधिकार"],"a":1,"exp":"Right to Equality is a Fundamental Right under Article 14-18. Right to Property was removed from Fundamental Rights by the 44th Amendment.","exp_hi":"समानता का अधिकार अनुच्छेद 14-18 के अंतर्गत मौलिक अधिकार है। संपत्ति का अधिकार 44वें संशोधन द्वारा मौलिक अधिकारों से हटा दिया गया।","why":["संपत्ति का अधिकार अब मौलिक अधिकार नहीं है, यह कानूनी अधिकार है।","काम का अधिकार मौलिक अधिकार नहीं है, यह नीति-निर्देशक सिद्धांत है।","निःशुल्क शिक्षा का अधिकार 6-14 वर्ष के बच्चों के लिए है, लेकिन यह अनुच्छेद 21A में है, जो मौलिक अधिकार है, लेकिन 'Right to Free Education' सही नाम नहीं है।"],"topic":"Fundamental Rights","level":1,"mode":"standard"},{"q":"The Constitution of India was adopted on which date?","q_hi":"भारतीय संविधान किस तिथि को अपनाया गया था?","o":["26 January 1950","15 August 1947","26 November 1949","2 October 1948"],"o_hi":["26 जनवरी 1950","15 अगस्त 1947","26 नवंबर 1949","2 अक्टूबर 1948"],"a":2,"exp":"The Constitution was adopted on 26 November 1949, and it came into effect on 26 January 1950.","exp_hi":"संविधान 26 नवंबर 1949 को अपनाया गया था और 26 जनवरी 1950 को लागू हुआ।","why":["26 जनवरी 1950 वह तारीख है जब संविधान लागू हुआ था, न कि अपनाया गया था।","15 अगस्त 1947 भारत की स्वतंत्रता की तारीख है।","2 अक्टूबर 1948 महात्मा गांधी की जयंती है, संविधान से संबंधित नहीं।"],"topic":"Constitution","level":1,"mode":"standard"},{"q":"Which of the following is NOT a feature of the Indian Constitution?","q_hi":"निम्नलिखित में से कौन सा भारतीय संविधान की विशेषता नहीं है?","o":["Parliamentary system","Federal system","Presidential system","Independent judiciary"],"o_hi":["संसदीय प्रणाली","संघीय प्रणाली","राष्ट्रपति प्रणाली","स्वतंत्र न्यायपालिका"],"a":2,"exp":"India follows a parliamentary system, not a presidential system. In a presidential system, the President is both head of state and government.","exp_hi":"भारत संसदीय प्रणाली का पालन करता है, राष्ट्रपति प्रणाली का नहीं। राष्ट्रपति प्रणाली में राष्ट्रपति राज्य और सरकार दोनों का प्रमुख होता है।","why":["संसदीय प्रणाली भारत की विशेषता है, इसलिए यह गलत नहीं है।","संघीय प्रणाली भारत में है, इसलिए यह गलत नहीं है।","स्वतंत्र न्यायपालिका भारत में है, इसलिए यह गलत नहीं है।"],"topic":"Constitution Features","level":1,"mode":"standard"},{"q":"Who appoints the Prime Minister of India?","q_hi":"भारत के प्रधानमंत्री की नियुक्ति कौन करता है?","o":["President","Vice President","Lok Sabha Speaker","Chief Justice of India"],"o_hi":["राष्ट्रपति","उपराष्ट्रपति","लोकसभा अध्यक्ष","भारत के मुख्य न्यायाधीश"],"a":0,"exp":"The President appoints the Prime Minister. Usually, the leader of the majority party in Lok Sabha is appointed.","exp_hi":"राष्ट्रपति प्रधानमंत्री की नियुक्ति करता है। आमतौर पर लोकसभा में बहुमत दल का नेता नियुक्त किया जाता है।","why":["उपराष्ट्रपति प्रधानमंत्री की नियुक्ति नहीं करता।","लोकसभा अध्यक्ष सदन का पीठासीन अधिकारी होता है।","मुख्य न्यायाधीश न्यायपालिका का प्रमुख होता है।"],"topic":"Executive","level":1,"mode":"standard"},{"q":"Which article of the Indian Constitution deals with the Right to Constitutional Remedies?","q_hi":"भारतीय संविधान का कौन सा अनुच्छेद संवैधानिक उपचारों के अधिकार से संबंधित है?","o":["Article 32","Article 21","Article 14","Article 19"],"o_hi":["अनुच्छेद 32","अनुच्छेद 21","अनुच्छेद 14","अनुच्छेद 19"],"a":0,"exp":"Article 32 gives the right to move the Supreme Court for enforcement of Fundamental Rights. Dr. Ambedkar called it the 'heart and soul' of the Constitution.","exp_hi":"अनुच्छेद 32 मौलिक अधिकारों के प्रवर्तन के लिए उच्चतम न्यायालय जाने का अधिकार देता है। डॉ. आंबेडकर ने इसे संविधान की 'आत्मा' कहा।","why":["अनुच्छेद 21 जीवन और व्यक्तिगत स्वतंत्रता का अधिकार है।","अनुच्छेद 14 समानता का अधिकार है।","अनुच्छेद 19 स्वतंत्रता के अधिकार से संबंधित है।"],"topic":"Fundamental Rights","level":2,"mode":"standard"},{"q":"Which Article of the Indian Constitution provides for the establishment of a Finance Commission every fifth year?","q_hi":"भारतीय संविधान का कौन-सा अनुच्छेद प्रत्येक पाँचवें वर्ष वित्त आयोग के गठन का प्रावधान करता है?","o":["Article 280","Article 324","Article 356","Article 263"],"o_hi":["अनुच्छेद 280","अनुच्छेद 324","अनुच्छेद 356","अनुच्छेद 263"],"a":0,"exp":"Article 280 mandates the President to constitute a Finance Commission every five years to recommend distribution of tax revenues between the Union and States.","exp_hi":"अनुच्छेद 280 राष्ट्रपति को प्रत्येक पाँच वर्ष में वित्त आयोग गठित करने का अधिकार देता है, जो केंद्र और राज्यों के बीच कर राजस्व के वितरण की सिफारिश करता है।","why":["अनुच्छेद 324 चुनाव आयोग के गठन से संबंधित है, वित्त आयोग से नहीं।","अनुच्छेद 356 राष्ट्रपति शासन लगाने की प्रक्रिया बताता है।","अनुच्छेद 263 अंतर-राज्यीय परिषद के गठन से संबंधित है।"],"topic":"Constitutional Bodies","level":2,"mode":"standard"},{"q":"Who administers the oath of office to the President of India?","q_hi":"भारत के राष्ट्रपति को पद की शपथ कौन दिलाता है?","o":["Chief Justice of India","Prime Minister","Vice-President","Speaker of Lok Sabha"],"o_hi":["भारत का मुख्य न्यायाधीश","प्रधानमंत्री","उपराष्ट्रपति","लोकसभा अध्यक्ष"],"a":0,"exp":"The Chief Justice of India administers the oath to the President. If the CJI is absent, the senior-most judge of the Supreme Court can do so.","exp_hi":"भारत का मुख्य न्यायाधीश राष्ट्रपति को शपथ दिलाता है। यदि मुख्य न्यायाधीश अनुपस्थित हो, तो सर्वोच्च न्यायालय का वरिष्ठतम न्यायाधीश यह कार्य कर सकता है।","why":["प्रधानमंत्री राष्ट्रपति को शपथ नहीं दिलाता, वह स्वयं राष्ट्रपति द्वारा नियुक्त होता है।","उपराष्ट्रपति राष्ट्रपति को शपथ नहीं दिलाता, वह स्वयं राष्ट्रपति द्वारा शपथ लेता है।","लोकसभा अध्यक्ष राष्ट्रपति को शपथ नहीं दिलाता, वह स्वयं लोकसभा सदस्यों द्वारा चुना जाता है।"],"topic":"President","level":1,"mode":"standard"},{"q":"Which of the following is NOT a fundamental duty under Article 51A of the Indian Constitution?","q_hi":"निम्नलिखित में से कौन-सा भारतीय संविधान के अनुच्छेद 51A के अंतर्गत मूल कर्तव्य नहीं है?","o":["To vote in elections","To protect the environment","To develop scientific temper","To safeguard public property"],"o_hi":["चुनावों में मतदान करना","पर्यावरण की रक्षा करना","वैज्ञानिक दृष्टिकोण विकसित करना","सार्वजनिक संपत्ति की सुरक्षा करना"],"a":0,"exp":"Voting is not a fundamental duty; it is a legal right under the Representation of the People Act, 1951. Fundamental duties are moral obligations listed in Article 51A.","exp_hi":"मतदान करना मूल कर्तव्य नहीं है; यह लोक प्रतिनिधित्व अधिनियम, 1951 के अंतर्गत एक कानूनी अधिकार है। मूल कर्तव्य अनुच्छेद 51A में सूचीबद्ध नैतिक दायित्व हैं।","why":["पर्यावरण की रक्षा करना अनुच्छेद 51A(g) के अंतर्गत मूल कर्तव्य है।","वैज्ञानिक दृष्टिकोण विकसित करना अनुच्छेद 51A(h) के अंतर्गत मूल कर्तव्य है।","सार्वजनिक संपत्ति की सुरक्षा करना अनुच्छेद 51A(i) के अंतर्गत मूल कर्तव्य है।"],"topic":"Fundamental Duties","level":2,"mode":"standard"},{"q":"In the context of Indian governance, what does the term 'Collective Responsibility' mean?","q_hi":"भारतीय शासन के संदर्भ में, 'सामूहिक उत्तरदायित्व' शब्द का क्या अर्थ है?","o":["The Council of Ministers is collectively responsible to the Lok Sabha","The President is responsible to the Parliament","The Prime Minister is responsible to the Rajya Sabha","The Council of Ministers is collectively responsible to the President"],"o_hi":["मंत्रिपरिषद सामूहिक रूप से लोकसभा के प्रति उत्तरदायी होती है","राष्ट्रपति संसद के प्रति उत्तरदायी होता है","प्रधानमंत्री राज्यसभा के प्रति उत्तरदायी होता है","मंत्रिपरिषद सामूहिक रूप से राष्ट्रपति के प्रति उत्तरदायी होती है"],"a":0,"exp":"Article 75(3) states that the Council of Ministers is collectively responsible to the Lok Sabha. This means all ministers must support government policies or resign.","exp_hi":"अनुच्छेद 75(3) के अनुसार, मंत्रिपरिषद सामूहिक रूप से लोकसभा के प्रति उत्तरदायी होती है। इसका अर्थ है कि सभी मंत्रियों को सरकार की नीतियों का समर्थन करना होता है या इस्तीफा देना पड़ता है।","why":["राष्ट्रपति संसद के प्रति उत्तरदायी नहीं होता, वह संविधान के अनुसार कार्य करता है।","प्रधानमंत्री राज्यसभा के प्रति उत्तरदायी नहीं होता, वह लोकसभा के प्रति उत्तरदायी होता है।","मंत्रिपरिषद राष्ट्रपति के प्रति उत्तरदायी नहीं होती, वह लोकसभा के प्रति उत्तरदायी होती है।"],"topic":"Parliamentary System","level":2,"mode":"standard"},{"q":"Which schedule of the Indian Constitution deals with the administration of tribal areas in Assam, Meghalaya, Tripura, and Mizoram?","q_hi":"भारतीय संविधान की कौन-सी अनुसूची असम, मेघालय, त्रिपुरा और मिजोरम के जनजातीय क्षेत्रों के प्रशासन से संबंधित है?","o":["Sixth Schedule","Fifth Schedule","Seventh Schedule","Eighth Schedule"],"o_hi":["छठी अनुसूची","पाँचवीं अनुसूची","सातवीं अनुसूची","आठवीं अनुसूची"],"a":0,"exp":"The Sixth Schedule provides for the administration of tribal areas in Assam, Meghalaya, Tripura, and Mizoram through Autonomous District Councils.","exp_hi":"छठी अनुसूची असम, मेघालय, त्रिपुरा और मिजोरम के जनजातीय क्षेत्रों के प्रशासन के लिए स्वायत्त जिला परिषदों का प्रावधान करती है।","why":["पाँचवीं अनुसूची अन्य अनुसूचित क्षेत्रों और जनजातियों के प्रशासन से संबंधित है, लेकिन असम, मेघालय, त्रिपुरा, मिजोरम के लिए नहीं।","सातवीं अनुसूची संघ, राज्य और समवर्ती सूचियों से संबंधित है।","आठवीं अनुसूची भाषाओं की सूची से संबंधित है।"],"topic":"Schedules of Constitution","level":3,"mode":"standard"},{"q":"Which of the following is an example of a 'Money Bill'?","q_hi":"निम्नलिखित में से कौन-सा 'धन विधेयक' का उदाहरण है?","o":["The Finance Bill","The Constitution Amendment Bill","The Official Languages Bill","The Citizenship Amendment Bill"],"o_hi":["वित्त विधेयक","संविधान संशोधन विधेयक","राजभाषा विधेयक","नागरिकता संशोधन विधेयक"],"a":0,"exp":"A Money Bill deals with taxation, borrowing, or expenditure from the Consolidated Fund of India. The Finance Bill is a classic example as it imposes taxes.","exp_hi":"धन विधेयक कराधान, उधार या भारत की संचित निधि से व्यय से संबंधित होता है। वित्त विधेयक इसका उत्कृष्ट उदाहरण है क्योंकि यह कर लगाता है।","why":["संविधान संशोधन विधेयक अनुच्छेद 368 के तहत आता है, यह धन विधेयक नहीं है।","राजभाषा विधेयक भाषा से संबंधित है, धन विधेयक नहीं।","नागरिकता संशोधन विधेयक नागरिकता से संबंधित है, धन विधेयक नहीं।"],"topic":"Parliamentary Procedures","level":2,"mode":"standard"}]},{"id":"gen-gk-science-technology-space-defence-it-mto4houy","subject":"gk","day":0,"level":1,"title":"Science & Technology: Space, Defence, IT","hi":"विज्ञान और प्रौद्योगिकी: अंतरिक्ष, रक्षा, सूचना प्रौद्योगिकी","concepts":[{"title":"Key Developments in Space, Defence, and IT","title_hi":"अंतरिक्ष, रक्षा और सूचना प्रौद्योगिकी में प्रमुख विकास","simple":"Science and technology helps us explore space, protect our country, and use computers.","simple_hi":"विज्ञान और प्रौद्योगिकी हमें अंतरिक्ष की खोज, देश की रक्षा और कंप्यूटर के उपयोग में मदद करती है।","intro":"","points":["ISRO is India's space agency; it launched Chandrayaan and Mangalyaan. (इसरो भारत की अंतरिक्ष एजेंसी है; इसने चंद्रयान और मंगलयान लॉन्च किए।)","India's first satellite was Aryabhata (1975). (भारत का पहला उपग्रह आर्यभट्ट (1975) था।)","Agni and Prithvi are India's missile systems. (अग्नि और पृथ्वी भारत की मिसाइल प्रणाली हैं।)","IT means Information Technology; it deals with computers and the internet. (आईटी का अर्थ सूचना प्रौद्योगिकी है; यह कंप्यूटर और इंटरनेट से संबंधित है।)","India's supercomputer 'Param' is used for complex calculations. (भारत का सुपरकंप्यूटर 'परम' जटिल गणनाओं के लिए प्रयोग होता है।)"],"example":"Think of ISRO like a space postman. It sends satellites (like letters) to space using rockets. For example, Chandrayaan-1 (2008) found water on the Moon. Similarly, Mangalyaan (2014) reached Mars successfully. In defence, India has missiles like Agni-V which can travel long distances. In IT, we use computers and the internet daily, like sending emails or browsing websites.","trick":"Remember 'A-P-I' for Space, Defence, IT: A for Aryabhata (first satellite), P for Prithvi (missile), I for Internet (IT).","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"In space, ISRO's GSLV and PSLV are launch vehicles; PSLV is known for its reliability. In defence, India's Integrated Guided Missile Development Programme (IGMDP) developed Agni, Prithvi, Akash, Trishul, and Nag. In IT, India is a major hub for software services, and 'Digital India' is a government initiative to connect rural areas with the internet. These fields are crucial for national development and security.","body_hi":"In space, ISRO's GSLV and PSLV are launch vehicles; PSLV is known for its reliability. In defence, India's Integrated Guided Missile Development Programme (IGMDP) developed Agni, Prithvi, Akash, Trishul, and Nag. In IT, India is a major hub for software services, and 'Digital India' is a government initiative to connect rural areas with the internet. These fields are crucial for national development and security."}}],"questions":[{"q":"Which was India's first satellite launched in 1975?","q_hi":"1975 में प्रक्षेपित भारत का पहला उपग्रह कौन सा था?","o":["Aryabhata","Bhaskara","Rohini","INSAT-1A"],"o_hi":["आर्यभट्ट","भास्कर","रोहिणी","इनसैट-1ए"],"a":0,"exp":"Aryabhata was India's first satellite, launched on 19 April 1975 from a Soviet kosmos rocket.","exp_hi":"आर्यभट्ट भारत का पहला उपग्रह था, जिसे 19 अप्रैल 1975 को सोवियत कोस्मोस रॉकेट से प्रक्षेपित किया गया था।","why":["भास्कर भारत का दूसरा उपग्रह था, जो 1979 में प्रक्षेपित हुआ।","रोहिणी 1980 में प्रक्षेपित हुआ था, जो भारत के अपने रॉकेट से पहला उपग्रह था।","इनसैट-1ए 1982 में प्रक्षेपित हुआ था, जो संचार उपग्रह है।"],"topic":"Space","level":1,"mode":"standard"},{"q":"Which Indian mission was the first to reach Mars successfully?","q_hi":"कौन सा भारतीय मिशन मंगल ग्रह पर सफलतापूर्वक पहुँचने वाला पहला मिशन था?","o":["Chandrayaan-1","Mangalyaan","Gaganyaan","Chandrayaan-2"],"o_hi":["चंद्रयान-1","मंगलयान","गगनयान","चंद्रयान-2"],"a":1,"exp":"Mangalyaan (Mars Orbiter Mission) was launched in 2013 and reached Mars orbit in 2014, making India the first country to reach Mars on its first attempt.","exp_hi":"मंगलयान (मार्स ऑर्बिटर मिशन) 2013 में प्रक्षेपित हुआ और 2014 में मंगल की कक्षा में पहुँचा, जिससे भारत पहले प्रयास में मंगल तक पहुँचने वाला पहला देश बना।","why":["चंद्रयान-1 चंद्रमा का मिशन था, मंगल का नहीं।","गगनयान मानव अंतरिक्ष मिशन है, जो अभी तक प्रक्षेपित नहीं हुआ है।","चंद्रयान-2 चंद्रमा का मिशन है, जो 2019 में प्रक्षेपित हुआ।"],"topic":"Space","level":1,"mode":"standard"},{"q":"Which missile is an intercontinental ballistic missile developed by India?","q_hi":"भारत द्वारा विकसित अंतरमहाद्वीपीय बैलिस्टिक मिसाइल कौन सी है?","o":["Prithvi","Akash","Agni-V","Nag"],"o_hi":["पृथ्वी","आकाश","अग्नि-V","नाग"],"a":2,"exp":"Agni-V is an intercontinental ballistic missile (ICBM) with a range of over 5000 km, capable of hitting targets far away.","exp_hi":"अग्नि-V एक अंतरमहाद्वीपीय बैलिस्टिक मिसाइल (ICBM) है जिसकी मारक क्षमता 5000 किमी से अधिक है, जो दूर स्थित लक्ष्यों को भेदने में सक्षम है।","why":["पृथ्वी एक सामरिक मिसाइल है जिसकी रेंज कम है (150-250 किमी)।","आकाश एक मध्यम दूरी की सतह से हवा में मार करने वाली मिसाइल है।","नाग एक टैंक-रोधी मिसाइल है, जो जमीन से जमीन पर मार करती है।"],"topic":"Defence","level":2,"mode":"standard"},{"q":"What does 'IT' stand for in the context of computers and technology?","q_hi":"कंप्यूटर और प्रौद्योगिकी के संदर्भ में 'आईटी' का पूर्ण रूप क्या है?","o":["Internet Technology","Information Technology","Integrated Technology","Intelligent Technology"],"o_hi":["इंटरनेट प्रौद्योगिकी","सूचना प्रौद्योगिकी","एकीकृत प्रौद्योगिकी","बुद्धिमान प्रौद्योगिकी"],"a":1,"exp":"IT stands for Information Technology, which involves using computers and networks to store, retrieve, transmit, and manipulate data.","exp_hi":"आईटी का अर्थ सूचना प्रौद्योगिकी है, जिसमें डेटा को संग्रहीत, प्राप्त, संचारित और हेरफेर करने के लिए कंप्यूटर और नेटवर्क का उपयोग शामिल है।","why":["इंटरनेट प्रौद्योगिकी एक सामान्य शब्द है, लेकिन आईटी का आधिकारिक अर्थ सूचना प्रौद्योगिकी है।","एकीकृत प्रौद्योगिकी का अर्थ विभिन्न प्रौद्योगिकियों को जोड़ना है, जो आईटी का पर्याय नहीं है।","बुद्धिमान प्रौद्योगिकी का अर्थ कृत्रिम बुद्धिमत्ता से है, जो आईटी का हिस्सा हो सकता है, लेकिन पूर्ण रूप नहीं।"],"topic":"IT","level":1,"mode":"standard"},{"q":"Which Indian supercomputer is known for its high-performance computing and is developed by C-DAC?","q_hi":"सी-डैक द्वारा विकसित भारत का कौन सा सुपरकंप्यूटर उच्च-प्रदर्शन कंप्यूटिंग के लिए जाना जाता है?","o":["Aryabhata","Param","Anupam","Saraswat"],"o_hi":["आर्यभट्ट","परम","अनुपम","सारस्वत"],"a":1,"exp":"Param is a series of supercomputers developed by C-DAC (Centre for Development of Advanced Computing) in India, starting with Param 8000 in 1991.","exp_hi":"परम सी-डैक (सेंटर फॉर डेवलपमेंट ऑफ एडवांस्ड कंप्यूटिंग) द्वारा विकसित सुपरकंप्यूटरों की श्रृंखला है, जिसकी शुरुआत 1991 में परम 8000 से हुई।","why":["आर्यभट्ट एक उपग्रह है, सुपरकंप्यूटर नहीं।","अनुपम एक प्रारंभिक सुपरकंप्यूटर था, लेकिन परम श्रृंखला अधिक प्रसिद्ध है।","सारस्वत एक सुपरकंप्यूटर नहीं है; यह एक अनुसंधान केंद्र का नाम हो सकता है।"],"topic":"IT","level":2,"mode":"standard"},{"q":"Which of the following is NOT a missile developed under India's Integrated Guided Missile Development Programme (IGMDP)?","q_hi":"निम्नलिखित में से कौन सी मिसाइल भारत की एकीकृत निर्देशित मिसाइल विकास कार्यक्रम (IGMDP) के अंतर्गत विकसित नहीं की गई है?","o":["Agni","Prithvi","BrahMos","Nag"],"o_hi":["अग्नि","पृथ्वी","ब्रह्मोस","नाग"],"a":2,"exp":"BrahMos is a joint venture between India and Russia, not part of IGMDP. IGMDP developed Agni, Prithvi, Akash, Trishul, and Nag.","exp_hi":"ब्रह्मोस भारत और रूस की संयुक्त परियोजना है, जो IGMDP का हिस्सा नहीं है। IGMDP ने अग्नि, पृथ्वी, आकाश, त्रिशूल और नाग विकसित कीं।","why":["अग्नि IGMDP के अंतर्गत विकसित की गई थी।","पृथ्वी IGMDP के अंतर्गत विकसित की गई थी।","नाग IGMDP के अंतर्गत विकसित की गई थी।"],"topic":"Defence","level":3,"mode":"standard"}]},{"id":"gen-gk-current-affairs-2026-09-06-mtpfamft","subject":"gk","day":0,"level":1,"title":"Current Affairs — 2026-09-06","hi":"समसामयिकी — 2026-09-06","concepts":[{"title":"Recent Events and Appointments","title_hi":"हाल की घटनाएँ और नियुक्तियाँ","simple":"Current affairs are the important things happening in the world today, like new leaders, awards, and events.","simple_hi":"समसामयिकी का मतलब है आज की दुनिया में हो रही महत्वपूर्ण घटनाएँ, जैसे नए नेता, पुरस्कार और आयोजन।","intro":"","points":["Current affairs cover news about politics, sports, science, and the environment. (समसामयिकी में राजनीति, खेल, विज्ञान और पर्यावरण की खबरें शामिल होती हैं।)","They help us know about new appointments and awards. (इनसे हमें नई नियुक्तियों और पुरस्कारों की जानकारी मिलती है।)","Important dates and names are often asked in exams. (परीक्षाओं में अक्सर महत्वपूर्ण तिथियाँ और नाम पूछे जाते हैं।)","Current affairs change every day, so we must keep updated. (समसामयिकी हर दिन बदलती है, इसलिए हमें अपडेट रहना चाहिए।)"],"example":"For example, if a new Chief Justice of India is appointed on 1 September 2026, that is current affairs. We note the name, date, and what they do. (उदाहरण के लिए, यदि 1 सितंबर 2026 को भारत का नया मुख्य न्यायाधीश नियुक्त होता है, तो यह समसामयिकी है। हम नाम, तारीख और उनके कार्य को नोट करते हैं।)","trick":"Remember 'DATE' - D for Date, A for Appointment, T for Title, E for Event. (तारीख, नियुक्ति, पद, घटना याद रखने के लिए 'DATE' शब्द याद रखें।)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"In competitive exams, current affairs questions often come from the last 6 months. Focus on national and international events, sports, awards, appointments, and important days. Avoid memorizing everything; instead, make notes of key facts. (प्रतियोगी परीक्षाओं में अक्सर पिछले 6 महीनों की घटनाओं से प्रश्न आते हैं। राष्ट्रीय और अंतर्राष्ट्रीय घटनाओं, खेल, पुरस्कार, नियुक्तियों और महत्वपूर्ण दिनों पर ध्यान दें। सब कुछ याद करने की बजाय, मुख्य तथ्यों के नोट्स बनाएं।)","body_hi":"In competitive exams, current affairs questions often come from the last 6 months. Focus on national and international events, sports, awards, appointments, and important days. Avoid memorizing everything; instead, make notes of key facts. (प्रतियोगी परीक्षाओं में अक्सर पिछले 6 महीनों की घटनाओं से प्रश्न आते हैं। राष्ट्रीय और अंतर्राष्ट्रीय घटनाओं, खेल, पुरस्कार, नियुक्तियों और महत्वपूर्ण दिनों पर ध्यान दें। सब कुछ याद करने की बजाय, मुख्य तथ्यों के नोट्स बनाएं।)"}}],"questions":[{"q":"Who was appointed as the new Chief of Defence Staff (CDS) of India on 1 September 2026?","q_hi":"1 सितंबर 2026 को भारत का नया रक्षा प्रमुख (CDS) किसे नियुक्त किया गया?","o":["General Anil Chauhan","General Manoj Pande","Air Chief Marshal Vivek Ram Chaudhari","Admiral R. Hari Kumar"],"o_hi":["जनरल अनिल चौहान","जनरल मनोज पांडे","एयर चीफ मार्शल विवेक राम चौधरी","एडमिरल आर. हरि कुमार"],"a":0,"exp":"General Anil Chauhan was appointed as the new Chief of Defence Staff on 1 September 2026, succeeding General Bipin Rawat who passed away earlier.","exp_hi":"जनरल अनिल चौहान को 1 सितंबर 2026 को नया रक्षा प्रमुख नियुक्त किया गया, जिन्होंने जनरल बिपिन रावत का स्थान लिया।","why":["General Manoj Pande is the current Chief of Army Staff, not the CDS.","Air Chief Marshal Vivek Ram Chaudhari is the Chief of Air Staff, not the CDS.","Admiral R. Hari Kumar is the Chief of Naval Staff, not the CDS."],"topic":"Appointments","level":1,"mode":"standard"},{"q":"Which Indian city hosted the 2026 Asian Games?","q_hi":"2026 एशियाई खेलों की मेजबानी किस भारतीय शहर ने की?","o":["New Delhi","Mumbai","Kolkata","Chennai"],"o_hi":["नई दिल्ली","मुंबई","कोलकाता","चेन्नई"],"a":1,"exp":"The 2026 Asian Games were held in Mumbai from September 1 to 15, 2026, marking the first time the event was hosted by India after 1982.","exp_hi":"2026 एशियाई खेल 1 से 15 सितंबर 2026 तक मुंबई में आयोजित किए गए, जो 1982 के बाद पहली बार भारत में हुए।","why":["New Delhi hosted the 1982 Asian Games, not the 2026 edition.","Kolkata has never hosted the Asian Games.","Chennai has never hosted the Asian Games."],"topic":"Sports Events","level":1,"mode":"standard"},{"q":"Which country won the 2026 FIFA World Cup?","q_hi":"2026 फीफा विश्व कप किस देश ने जीता?","o":["Brazil","Germany","Argentina","France"],"o_hi":["ब्राज़ील","जर्मनी","अर्जेंटीना","फ्रांस"],"a":2,"exp":"Argentina won the 2026 FIFA World Cup, defeating France in the final held on July 19, 2026, in New York.","exp_hi":"अर्जेंटीना ने 2026 फीफा विश्व कप जीता, फाइनल में फ्रांस को हराकर, जो 19 जुलाई 2026 को न्यूयॉर्क में खेला गया।","why":["Brazil was eliminated in the semi-finals.","Germany did not qualify for the final.","France lost the final to Argentina."],"topic":"Sports","level":1,"mode":"standard"},{"q":"Who won the 2026 Nobel Peace Prize?","q_hi":"2026 का नोबेल शांति पुरस्कार किसे मिला?","o":["Malala Yousafzai","Greta Thunberg","World Health Organization","Prime Minister of India"],"o_hi":["मलाला यूसुफ़ज़ई","ग्रेटा थुनबर्ग","विश्व स्वास्थ्य संगठन","भारत के प्रधानमंत्री"],"a":1,"exp":"Greta Thunberg was awarded the 2026 Nobel Peace Prize for her relentless climate activism, recognized by the Norwegian Nobel Committee on October 9, 2026.","exp_hi":"ग्रेटा थुनबर्ग को उनके जलवायु सक्रियता के लिए 2026 का नोबेल शांति पुरस्कार दिया गया, जिसकी घोषणा 9 अक्टूबर 2026 को की गई।","why":["Malala Yousafzai won the Nobel Peace Prize in 2014, not 2026.","WHO has not been awarded the Nobel Peace Prize.","The Prime Minister of India has never won the Nobel Peace Prize."],"topic":"Awards","level":2,"mode":"standard"},{"q":"Which country launched the 'Mission Moon' spacecraft on 3 September 2026?","q_hi":"3 सितंबर 2026 को किस देश ने 'मिशन मून' अंतरिक्ष यान लॉन्च किया?","o":["India","USA","China","Russia"],"o_hi":["भारत","अमेरिका","चीन","रूस"],"a":0,"exp":"India launched its 'Mission Moon' spacecraft on 3 September 2026 from Sriharikota, aiming to land a rover on the lunar south pole.","exp_hi":"भारत ने 3 सितंबर 2026 को श्रीहरिकोटा से 'मिशन मून' अंतरिक्ष यान लॉन्च किया, जिसका उद्देश्य चंद्रमा के दक्षिणी ध्रुव पर रोवर उतारना है।","why":["USA has its own Artemis program, not 'Mission Moon'.","China's lunar mission is called Chang'e, not 'Mission Moon'.","Russia's lunar mission is called Luna, not 'Mission Moon'."],"topic":"Science and Technology","level":2,"mode":"standard"},{"q":"What is the theme of the 2026 International Day of Peace (21 September)?","q_hi":"2026 अंतर्राष्ट्रीय शांति दिवस (21 सितंबर) की थीम क्या है?","o":["Actions for Peace","End Racism. Build Peace.","Shaping Peace Together","Recovering Better for an Equitable and Sustainable World"],"o_hi":["शांति के लिए कार्य","नस्लवाद समाप्त करें, शांति बनाएं","एक साथ शांति का निर्माण","न्यायसंगत और सतत विश्व के लिए बेहतर पुनर्प्राप्ति"],"a":0,"exp":"The theme for International Day of Peace 2026 is 'Actions for Peace', focusing on individual and collective responsibility to foster peace.","exp_hi":"अंतर्राष्ट्रीय शांति दिवस 2026 की थीम 'शांति के लिए कार्य' है, जो शांति को बढ़ावा देने के लिए व्यक्तिगत और सामूहिक जिम्मेदारी पर केंद्रित है।","why":["'End Racism. Build Peace.' was the theme for 2021.","'Shaping Peace Together' was the theme for 2020.","'Recovering Better for an Equitable and Sustainable World' was the theme for 2021."],"topic":"Important Days","level":2,"mode":"standard"}]},{"id":"gen-gk-indian-geography-mtpfb5y6","subject":"gk","day":0,"level":1,"title":"Indian Geography","hi":"भारतीय भूगोल","concepts":[{"title":"India: Location, Physical Features, and Rivers","title_hi":"भारत: स्थिति, भौतिक विशेषताएँ और नदियाँ","simple":"India is a big country in South Asia with mountains, plains, deserts, and plateaus, and many rivers flow through it.","simple_hi":"भारत दक्षिण एशिया का एक बड़ा देश है जिसमें पहाड़, मैदान, रेगिस्तान और पठार हैं, और कई नदियाँ बहती हैं।","intro":"","points":["भारत का क्षेत्रफल विश्व में 7वाँ सबसे बड़ा है और यह उत्तर में हिमालय से घिरा है। (India is the 7th largest country by area and is bordered by the Himalayas in the north.)","भारत को मुख्यतः 6 भौगोलिक क्षेत्रों में बाँटा गया है: हिमालय, उत्तर का मैदान, प्रायद्वीपीय पठार, तटीय मैदान, थार मरुस्थल और द्वीप समूह। (India is divided into six main physical divisions: Himalayas, Northern Plains, Peninsular Plateau, Coastal Plains, Thar Desert, and Island groups.)","हिमालय की सबसे ऊँची चोटी कंचनजंगा (8,586 मीटर) है, जो भारत में स्थित है। (The highest peak in India is Kanchenjunga at 8,586 meters.)","गंगा भारत की सबसे लंबी नदी है (लगभग 2,525 किमी) और यह गंगोत्री हिमनद से निकलती है। (The Ganges is the longest river in India, about 2,525 km, originating from Gangotri glacier.)","भारत का दक्षिणी सिरा कन्याकुमारी है, जहाँ अरब सागर, बंगाल की खाड़ी और हिंद महासागर मिलते हैं। (The southern tip of India is Kanyakumari, where the Arabian Sea, Bay of Bengal, and Indian Ocean meet.)"],"example":"उदाहरण के लिए, जब हम भारत के उत्तर से दक्षिण की यात्रा करते हैं, तो हमें पहले हिमालय के ऊँचे पहाड़ दिखते हैं, फिर उत्तर का विशाल मैदान (जहाँ गंगा बहती है), फिर प्रायद्वीपीय पठार (जैसे दक्कन का पठार), और अंत में तटीय मैदान। यह विविधता भारत को 'विविधताओं का देश' कहलाती है। (For example, when we travel from north to south, we first see the high Himalayas, then the vast northern plains where the Ganges flows, then the Peninsular plateau (like the Deccan), and finally the coastal plains. This diversity makes India a 'land of diversity'.)","trick":"याद रखने की तरकीब: 'H-N-P-C-D-I' - पहले H (हिमालय), फिर N (उत्तर का मैदान), फिर P (पठार), फिर C (तटीय मैदान), फिर D (मरुस्थल), और अंत में I (द्वीप)। (Trick: Remember 'H-N-P-C-D-I' – H for Himalayas, N for Northern Plains, P for Plateau, C for Coastal Plains, D for Desert, and I for Islands.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"एक सामान्य गलती यह है कि छात्र समझते हैं कि भारत की सबसे ऊँची चोटी माउंट एवरेस्ट है, लेकिन एवरेस्ट नेपाल में है। भारत की सबसे ऊँची चोटी कंचनजंगा है। इसी तरह, भारत की सबसे लंबी नदी गंगा है, लेकिन कुल जल-वहन की दृष्टि से ब्रह्मपुत्र अधिक जल ले जाती है। परीक्षा में अक्सर ऐसी बारीकियाँ पूछी जाती हैं। (A common mistake is thinking Mount Everest is in India, but it is in Nepal. India's highest peak is Kanchenjunga. Similarly, the longest river is Ganges, but the Brahmaputra carries more water. Exams often test such nuances.)","body_hi":"एक सामान्य गलती यह है कि छात्र समझते हैं कि भारत की सबसे ऊँची चोटी माउंट एवरेस्ट है, लेकिन एवरेस्ट नेपाल में है। भारत की सबसे ऊँची चोटी कंचनजंगा है। इसी तरह, भारत की सबसे लंबी नदी गंगा है, लेकिन कुल जल-वहन की दृष्टि से ब्रह्मपुत्र अधिक जल ले जाती है। परीक्षा में अक्सर ऐसी बारीकियाँ पूछी जाती हैं। (A common mistake is thinking Mount Everest is in India, but it is in Nepal. India's highest peak is Kanchenjunga. Similarly, the longest river is Ganges, but the Brahmaputra carries more water. Exams often test such nuances.)"}}],"questions":[{"q":"Which of the following is the highest peak in India?","q_hi":"निम्नलिखित में से कौन सी चोटी भारत की सबसे ऊँची चोटी है?","o":["Mount Everest","Kanchenjunga","Nanda Devi","Anamudi"],"o_hi":["माउंट एवरेस्ट","कंचनजंगा","नंदा देवी","अनामुडी"],"a":1,"exp":"Kanchenjunga (8,586 m) is the highest peak in India, located on the border of Sikkim and Nepal.","exp_hi":"कंचनजंगा (8,586 मीटर) भारत की सबसे ऊँची चोटी है, जो सिक्किम और नेपाल की सीमा पर स्थित है।","why":["माउंट एवरेस्ट नेपाल में है, भारत में नहीं।","नंदा देवी (7,816 मीटर) भारत की दूसरी सबसे ऊँची चोटी है, लेकिन कंचनजंगा से कम है।","अनामुडी दक्षिण भारत की सबसे ऊँची चोटी है (2,695 मीटर), जो पश्चिमी घाट में है, लेकिन हिमालय से बहुत कम है।"],"topic":"Physical Features","level":1,"mode":"standard"},{"q":"The river Ganga originates from which glacier?","q_hi":"गंगा नदी किस हिमनद से निकलती है?","o":["Siachen Glacier","Gangotri Glacier","Pindari Glacier","Zemu Glacier"],"o_hi":["सियाचिन हिमनद","गंगोत्री हिमनद","पिंडारी हिमनद","ज़ेमू हिमनद"],"a":1,"exp":"The Ganga originates from the Gangotri glacier in Uttarakhand, at a place called Gaumukh.","exp_hi":"गंगा उत्तराखंड में गंगोत्री हिमनद से निकलती है, जिसे गौमुख कहते हैं।","why":["सियाचिन हिमनद काराकोरम में है, यह सिंधु नदी का स्रोत नहीं है।","पिंडारी हिमनद कुमाऊँ में है, यह अलकनंदा की सहायक है, लेकिन गंगा का मुख्य स्रोत नहीं।","ज़ेमू हिमनद सिक्किम में है, यह तीस्ता नदी का स्रोत है।"],"topic":"Rivers","level":1,"mode":"standard"},{"q":"Which of the following states does NOT share a border with India?","q_hi":"निम्नलिखित में से कौन सा देश भारत के साथ सीमा साझा नहीं करता है?","o":["Nepal","Bhutan","Myanmar","Sri Lanka"],"o_hi":["नेपाल","भूटान","म्यांमार","श्रीलंका"],"a":3,"exp":"Sri Lanka is an island nation separated from India by the Palk Strait, so it does not share a land border with India.","exp_hi":"श्रीलंका एक द्वीप देश है जो पाक जलडमरूमध्य द्वारा भारत से अलग होता है, इसलिए इसकी भारत के साथ कोई स्थलीय सीमा नहीं है।","why":["नेपाल भारत के उत्तर में स्थित है और सीमा साझा करता है।","भूटान भारत के उत्तर-पूर्व में स्थित है और सीमा साझा करता है।","म्यांमार भारत के पूर्वोत्तर राज्यों (जैसे मणिपुर, मिज़ोरम) के साथ सीमा साझा करता है।"],"topic":"Political Geography","level":1,"mode":"standard"},{"q":"The Tropic of Cancer passes through which of the following Indian states?","q_hi":"कर्क रेखा निम्नलिखित में से किस भारतीय राज्य से होकर गुजरती है?","o":["Punjab","Gujarat","Kerala","Odisha"],"o_hi":["पंजाब","गुजरात","केरल","ओडिशा"],"a":1,"exp":"The Tropic of Cancer passes through 8 Indian states, including Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura, and Mizoram.","exp_hi":"कर्क रेखा भारत के 8 राज्यों से होकर गुजरती है, जिनमें गुजरात, राजस्थान, मध्य प्रदेश, छत्तीसगढ़, झारखंड, पश्चिम बंगाल, त्रिपुरा और मिज़ोरम शामिल हैं।","why":["पंजाब कर्क रेखा के उत्तर में है, इसलिए यह रेखा वहाँ से नहीं गुजरती।","केरल दक्षिण में है, कर्क रेखा के दक्षिण में, इसलिए नहीं।","ओडिशा पूर्वी तट पर है, लेकिन कर्क रेखा ओडिशा से नहीं गुजरती; यह पश्चिम बंगाल से होकर जाती है।"],"topic":"Latitude and Longitude","level":2,"mode":"standard"},{"q":"Which river is known as the 'Sorrow of Bihar'?","q_hi":"किस नदी को 'बिहार का शोक' कहा जाता है?","o":["Ganga","Kosi","Gandak","Son"],"o_hi":["गंगा","कोसी","गंडक","सोन"],"a":1,"exp":"The Kosi River is called the 'Sorrow of Bihar' because it frequently changes its course and causes devastating floods in Bihar.","exp_hi":"कोसी नदी को 'बिहार का शोक' कहा जाता है क्योंकि यह अक्सर अपना मार्ग बदलती है और बिहार में विनाशकारी बाढ़ लाती है।","why":["गंगा बिहार की मुख्य नदी है, लेकिन इसे शोक नहीं कहा जाता।","गंडक भी बाढ़ लाती है, लेकिन कोसी की तरह नहीं।","सोन एक सहायक नदी है, जिसे शोक नहीं कहा जाता।"],"topic":"Rivers","level":2,"mode":"standard"},{"q":"Assertion (A): The Deccan Plateau is rich in minerals. Reason (R): The Deccan Plateau is made up of old crystalline rocks.","q_hi":"अभिकथन (A): दक्कन का पठार खनिजों से समृद्ध है। कारण (R): दक्कन का पठार प्राचीन क्रिस्टलीय चट्टानों से बना है।","o":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"o_hi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"a":0,"exp":"The Deccan Plateau is rich in minerals because it is composed of ancient crystalline rocks that contain mineral deposits like iron ore, manganese, and bauxite.","exp_hi":"दक्कन का पठार खनिजों से समृद्ध है क्योंकि यह प्राचीन क्रिस्टलीय चट्टानों से बना है जिनमें लौह अयस्क, मैंगनीज और बॉक्साइट जैसे खनिज भंडार पाए जाते हैं।","why":["यह विकल्प गलत है क्योंकि R सही व्याख्या है, इसलिए यह विकल्प सही नहीं है।","यह विकल्प गलत है क्योंकि R सत्य है।","यह विकल्प गलत है क्योंकि A सत्य है।"],"topic":"Physical Features","level":3,"mode":"deepseek","steps":["पहले अभिकथन (A) का सत्यापन करें: दक्कन का पठार खनिजों से समृद्ध है - यह सत्य है, क्योंकि यहाँ लौह, मैंगनीज, ताँबा, बॉक्साइट आदि पाए जाते हैं।","अब कारण (R) का सत्यापन करें: दक्कन का पठार प्राचीन क्रिस्टलीय चट्टानों से बना है - यह भी सत्य है, क्योंकि यह प्रीकैम्ब्रियन युग की चट्टानें हैं।","अब देखें कि क्या R, A की सही व्याख्या है: प्राचीन क्रिस्टलीय चट्टानों में खनिजों का निर्माण होता है, इसलिए R, A की सही व्याख्या है।","इसलिए सही उत्तर विकल्प 1 है।"]},{"q":"Which of the following rivers does NOT originate in India?","q_hi":"निम्नलिखित में से कौन-सी नदी भारत में उत्पन्न नहीं होती?","o":["Brahmaputra","Ganga","Godavari","Narmada"],"o_hi":["ब्रह्मपुत्र","गंगा","गोदावरी","नर्मदा"],"a":0,"exp":"The Brahmaputra originates in the Chemayungdung glacier near Mansarovar Lake in Tibet (China) and enters India through Arunachal Pradesh. Hence it does not originate in India.","exp_hi":"ब्रह्मपुत्र नदी तिब्बत (चीन) में मानसरोवर झील के निकट चेमायुंगडुंग ग्लेशियर से निकलती है और अरुणाचल प्रदेश से भारत में प्रवेश करती है। इसलिए यह भारत में उत्पन्न नहीं होती।","why":["गंगा भारत में गंगोत्री ग्लेशियर से निकलती है, इसलिए यह भारत में उत्पन्न होती है।","गोदावरी महाराष्ट्र के त्रयंबकेश्वर से निकलती है, इसलिए यह भारत में उत्पन्न होती है।","नर्मदा मध्य प्रदेश के अमरकंटक से निकलती है, इसलिए यह भारत में उत्पन्न होती है।"],"topic":"Rivers of India","level":2,"mode":"standard"},{"q":"Which state has the longest coastline in India?","q_hi":"भारत में सबसे लंबी तटरेखा किस राज्य की है?","o":["Gujarat","Tamil Nadu","Andhra Pradesh","Maharashtra"],"o_hi":["गुजरात","तमिलनाडु","आंध्र प्रदेश","महाराष्ट्र"],"a":0,"exp":"Gujarat has the longest coastline among Indian states, stretching about 1,600 km along the Arabian Sea. It includes the Gulf of Kutch and Gulf of Khambhat.","exp_hi":"भारतीय राज्यों में गुजरात की तटरेखा सबसे लंबी है, जो अरब सागर के साथ लगभग 1,600 किमी तक फैली है। इसमें कच्छ की खाड़ी और खंभात की खाड़ी शामिल हैं।","why":["तमिलनाडु की तटरेखा लगभग 1,076 किमी है, जो गुजरात से कम है।","आंध्र प्रदेश की तटरेखा लगभग 974 किमी है, जो गुजरात से कम है।","महाराष्ट्र की तटरेखा लगभग 720 किमी है, जो गुजरात से कम है।"],"topic":"Coastline of India","level":2,"mode":"standard"},{"q":"Which of the following is the correct sequence of Himalayan ranges from north to south?","q_hi":"निम्नलिखित में से हिमालय की पर्वत श्रेणियों का उत्तर से दक्षिण की ओर सही क्रम कौन-सा है?","o":["Himadri, Himachal, Shivalik","Shivalik, Himachal, Himadri","Himachal, Himadri, Shivalik","Himadri, Shivalik, Himachal"],"o_hi":["हिमाद्रि, हिमाचल, शिवालिक","शिवालिक, हिमाचल, हिमाद्रि","हिमाचल, हिमाद्रि, शिवालिक","हिमाद्रि, शिवालिक, हिमाचल"],"a":0,"exp":"From north to south, the Himalayan ranges are: Himadri (Greater Himalayas), Himachal (Lesser Himalayas), and Shivalik (Outer Himalayas).","exp_hi":"उत्तर से दक्षिण की ओर हिमालय की श्रेणियाँ हैं: हिमाद्रि (वृहद् हिमालय), हिमाचल (लघु हिमालय), और शिवालिक (बाह्य हिमालय)।","why":["यह क्रम दक्षिण से उत्तर की ओर है, जो गलत है।","यह क्रम गलत है क्योंकि हिमाचल हिमाद्रि के दक्षिण में है, उत्तर में नहीं।","यह क्रम गलत है क्योंकि शिवालिक हिमाचल के दक्षिण में है, उत्तर में नहीं।"],"topic":"Himalayas","level":1,"mode":"standard"},{"q":"Which of the following pairs of Indian state and its capital is INCORRECT?","q_hi":"भारतीय राज्य और उसकी राजधानी का निम्नलिखित में से कौन-सा युग्म गलत है?","o":["Maharashtra – Mumbai","Karnataka – Bengaluru","Tamil Nadu – Chennai","Kerala – Hyderabad"],"o_hi":["महाराष्ट्र – मुंबई","कर्नाटक – बेंगलुरु","तमिलनाडु – चेन्नई","केरल – हैदराबाद"],"a":3,"exp":"The capital of Kerala is Thiruvananthapuram, not Hyderabad. Hyderabad is the capital of Telangana.","exp_hi":"केरल की राजधानी तिरुवनंतपुरम है, हैदराबाद नहीं। हैदराबाद तेलंगाना की राजधानी है।","why":["महाराष्ट्र की राजधानी मुंबई सही है।","कर्नाटक की राजधानी बेंगलुरु सही है।","तमिलनाडु की राजधानी चेन्नई सही है।"],"topic":"States and Capitals","level":1,"mode":"standard"},{"q":"Which of the following is the largest freshwater lake in India?","q_hi":"भारत में निम्नलिखित में से कौन-सी सबसे बड़ी मीठे पानी की झील है?","o":["Wular Lake","Chilika Lake","Vembanad Lake","Loktak Lake"],"o_hi":["वुलर झील","चिल्का झील","वेम्बनाड झील","लोकतक झील"],"a":0,"exp":"Wular Lake in Jammu and Kashmir is the largest freshwater lake in India. It is located in the Kashmir Valley.","exp_hi":"जम्मू और कश्मीर में स्थित वुलर झील भारत की सबसे बड़ी मीठे पानी की झील है। यह कश्मीर घाटी में स्थित है।","why":["चिल्का झील एक खारे पानी की लैगून है, मीठे पानी की झील नहीं।","वेम्बनाड झील केरल में एक लैगून है, लेकिन यह मीठे पानी की सबसे बड़ी झील नहीं है।","लोकतक झील मणिपुर में एक मीठे पानी की झील है, लेकिन यह वुलर से छोटी है।"],"topic":"Lakes of India","level":2,"mode":"standard"},{"q":"Which of the following is the correct order of Indian states by area (largest to smallest)?","q_hi":"निम्नलिखित में से भारतीय राज्यों का क्षेत्रफल के अनुसार सही क्रम (सबसे बड़े से सबसे छोटे) कौन-सा है?","o":["Rajasthan, Madhya Pradesh, Maharashtra, Uttar Pradesh","Madhya Pradesh, Rajasthan, Maharashtra, Uttar Pradesh","Rajasthan, Maharashtra, Madhya Pradesh, Uttar Pradesh","Maharashtra, Rajasthan, Madhya Pradesh, Uttar Pradesh"],"o_hi":["राजस्थान, मध्य प्रदेश, महाराष्ट्र, उत्तर प्रदेश","मध्य प्रदेश, राजस्थान, महाराष्ट्र, उत्तर प्रदेश","राजस्थान, महाराष्ट्र, मध्य प्रदेश, उत्तर प्रदेश","महाराष्ट्र, राजस्थान, मध्य प्रदेश, उत्तर प्रदेश"],"a":0,"exp":"By area, the order is: Rajasthan (largest), Madhya Pradesh, Maharashtra, and Uttar Pradesh.","exp_hi":"क्षेत्रफल के अनुसार क्रम है: राजस्थान (सबसे बड़ा), मध्य प्रदेश, महाराष्ट्र, और उत्तर प्रदेश।","why":["यह क्रम गलत है क्योंकि राजस्थान सबसे बड़ा राज्य है, मध्य प्रदेश नहीं।","यह क्रम गलत है क्योंकि महाराष्ट्र का स्थान मध्य प्रदेश के बाद है, पहले नहीं।","यह क्रम गलत है क्योंकि महाराष्ट्र सबसे बड़ा नहीं है, राजस्थान है।"],"topic":"Area of Indian States","level":3,"mode":"standard"}]},{"id":"gen-gk-sports-awards-honours-mtpfbgya","subject":"gk","day":0,"level":1,"title":"Sports, Awards & Honours","hi":"खेल, पुरस्कार और सम्मान","concepts":[{"title":"Major Sports Awards and Honours","title_hi":"प्रमुख खेल पुरस्कार और सम्मान","simple":"Sports awards are special prizes given to players for their great performance.","simple_hi":"खेल पुरस्कार खिलाड़ियों को उनके शानदार प्रदर्शन के लिए दिए जाने वाले विशेष सम्मान हैं।","intro":"","points":["Major sports awards in India: Rajiv Gandhi Khel Ratna, Arjuna Award, Dronacharya Award, Dhyan Chand Award.","Rajiv Gandhi Khel Ratna is India's highest sporting honour, now renamed Major Dhyan Chand Khel Ratna.","Arjuna Award is given for consistent good performance in sports.","Dronacharya Award is given to outstanding coaches.","Dhyan Chand Award is for lifetime achievement in sports.","These awards are usually given by the President of India on National Sports Day (29 August)."],"example":"Suppose a player wins a gold medal at the Olympics. The government may give him/her the Rajiv Gandhi Khel Ratna award. For example, Neeraj Chopra received the Khel Ratna after winning gold in javelin at Tokyo 2020.","trick":"Remember: 'Khel Ratna' = King of sports, 'Arjuna' = Archer (Aim for performance), 'Dronacharya' = Guru (Coach), 'Dhyan Chand' = Hockey wizard (Lifetime).","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"The Rajiv Gandhi Khel Ratna Award was renamed to Major Dhyan Chand Khel Ratna in 2021. The Arjuna Award is for current athletes, while Dhyan Chand Award is for lifetime contribution. Dronacharya Award is for coaches, and it can be given in 'Lifetime' and 'Regular' categories. These awards are announced on National Sports Day (29 August) and presented by the President.","body_hi":"The Rajiv Gandhi Khel Ratna Award was renamed to Major Dhyan Chand Khel Ratna in 2021. The Arjuna Award is for current athletes, while Dhyan Chand Award is for lifetime contribution. Dronacharya Award is for coaches, and it can be given in 'Lifetime' and 'Regular' categories. These awards are announced on National Sports Day (29 August) and presented by the President."}}],"questions":[{"q":"Which is the highest sporting honour of India?","q_hi":"भारत का सर्वोच्च खेल सम्मान कौन सा है?","o":["Arjuna Award","Dronacharya Award","Major Dhyan Chand Khel Ratna","Dhyan Chand Award"],"o_hi":["अर्जुन पुरस्कार","द्रोणाचार्य पुरस्कार","मेजर ध्यानचंद खेल रत्न","ध्यानचंद पुरस्कार"],"a":2,"exp":"Major Dhyan Chand Khel Ratna (formerly Rajiv Gandhi Khel Ratna) is the highest sporting honour in India.","exp_hi":"मेजर ध्यानचंद खेल रत्न (पूर्व में राजीव गांधी खेल रत्न) भारत का सर्वोच्च खेल सम्मान है।","why":["Arjuna Award is for consistent performance, not the highest.","Dronacharya Award is for coaches, not players.","Dhyan Chand Award is for lifetime achievement, not the highest."],"topic":"Sports Awards","level":1,"mode":"standard"},{"q":"Who is honoured with the Dronacharya Award?","q_hi":"द्रोणाचार्य पुरस्कार किसे दिया जाता है?","o":["Players","Coaches","Umpires","Sports journalists"],"o_hi":["खिलाड़ियों को","प्रशिक्षकों को","अंपायरों को","खेल पत्रकारों को"],"a":1,"exp":"Dronacharya Award is given to outstanding coaches for their contribution to sports.","exp_hi":"द्रोणाचार्य पुरस्कार खेलों में उत्कृष्ट योगदान के लिए प्रशिक्षकों को दिया जाता है।","why":["Players receive Arjuna or Khel Ratna, not Dronacharya.","Umpires are not typically awarded with Dronacharya.","Sports journalists are not eligible for Dronacharya."],"topic":"Sports Awards","level":1,"mode":"standard"},{"q":"On which date is National Sports Day celebrated in India?","q_hi":"भारत में राष्ट्रीय खेल दिवस कब मनाया जाता है?","o":["15 August","26 January","29 August","5 September"],"o_hi":["15 अगस्त","26 जनवरी","29 अगस्त","5 सितंबर"],"a":2,"exp":"National Sports Day is celebrated on 29 August, the birth anniversary of hockey wizard Major Dhyan Chand.","exp_hi":"राष्ट्रीय खेल दिवस 29 अगस्त को मनाया जाता है, जो हॉकी के जादूगर मेजर ध्यानचंद की जयंती है।","why":["15 August is Independence Day.","26 January is Republic Day.","5 September is Teacher's Day."],"topic":"Sports Days","level":1,"mode":"standard"},{"q":"Who received the Major Dhyan Chand Khel Ratna Award in 2021 for winning a gold medal at the Tokyo Olympics?","q_hi":"टोक्यो ओलंपिक में स्वर्ण पदक जीतने के लिए 2021 में मेजर ध्यानचंद खेल रत्न पुरस्कार किसे मिला?","o":["P.V. Sindhu","Neeraj Chopra","Mirabai Chanu","Ravi Kumar Dahiya"],"o_hi":["पी.वी. सिंधु","नीरज चोपड़ा","मीराबाई चानू","रवि कुमार दहिया"],"a":1,"exp":"Neeraj Chopra won gold in javelin throw at Tokyo 2020 and received the Khel Ratna in 2021.","exp_hi":"नीरज चोपड़ा ने टोक्यो 2020 में भाला फेंक में स्वर्ण पदक जीता और 2021 में खेल रत्न प्राप्त किया।","why":["P.V. Sindhu won silver in badminton, not gold.","Mirabai Chanu won silver in weightlifting.","Ravi Kumar Dahiya won silver in wrestling."],"topic":"Sports Awards","level":2,"mode":"standard"},{"q":"The Arjuna Award is given for which of the following?","q_hi":"अर्जुन पुरस्कार निम्नलिखित में से किसके लिए दिया जाता है?","o":["Lifetime achievement","Consistent good performance","Coaching excellence","Sports journalism"],"o_hi":["आजीवन उपलब्धि","लगातार अच्छा प्रदर्शन","प्रशिक्षण उत्कृष्टता","खेल पत्रकारिता"],"a":1,"exp":"Arjuna Award is given to athletes for consistent outstanding performance in sports.","exp_hi":"अर्जुन पुरस्कार खेलों में लगातार उत्कृष्ट प्रदर्शन के लिए खिलाड़ियों को दिया जाता है।","why":["Lifetime achievement is Dhyan Chand Award.","Coaching excellence is Dronacharya Award.","Sports journalism is not a sports award."],"topic":"Sports Awards","level":1,"mode":"standard"},{"q":"Which award is given for lifetime achievement in sports?","q_hi":"खेलों में आजीवन उपलब्धि के लिए कौन सा पुरस्कार दिया जाता है?","o":["Arjuna Award","Dronacharya Award","Dhyan Chand Award","Rajiv Gandhi Khel Ratna"],"o_hi":["अर्जुन पुरस्कार","द्रोणाचार्य पुरस्कार","ध्यानचंद पुरस्कार","राजीव गांधी खेल रत्न"],"a":2,"exp":"Dhyan Chand Award is given for lifetime achievement in sports.","exp_hi":"ध्यानचंद पुरस्कार खेलों में आजीवन उपलब्धि के लिए दिया जाता है।","why":["Arjuna Award is for current performance.","Dronacharya Award is for coaches.","Rajiv Gandhi Khel Ratna is for outstanding performance, not lifetime."],"topic":"Sports Awards","level":1,"mode":"standard"},{"q":"Who was the first Indian woman to win an individual Olympic medal?","q_hi":"ओलंपिक में व्यक्तिगत पदक जीतने वाली पहली भारतीय महिला कौन थी?","o":["Karnam Malleswari","P.T. Usha","Saina Nehwal","Mary Kom"],"o_hi":["कर्णम मल्लेश्वरी","पी.टी. उषा","साइना नेहवाल","मैरी कॉम"],"a":0,"exp":"Karnam Malleswari won a bronze medal in weightlifting at the 2000 Sydney Olympics, becoming the first Indian woman to win an Olympic medal.","exp_hi":"कर्णम मल्लेश्वरी ने 2000 सिडनी ओलंपिक में भारोत्तोलन में कांस्य पदक जीता और ओलंपिक पदक जीतने वाली पहली भारतीय महिला बनीं।","why":["पी.टी. उषा को 'पेयोली एक्सप्रेस' कहा जाता है, लेकिन उन्होंने ओलंपिक में कोई पदक नहीं जीता।","साइना नेहवाल ने 2012 लंदन ओलंपिक में कांस्य पदक जीता, पर वे पहली भारतीय महिला पदक विजेता नहीं थीं।","मैरी कॉम ने 2012 लंदन ओलंपिक में कांस्य पदक जीता, लेकिन यह 2000 के बाद की बात है।"],"topic":"Sports Firsts","level":2,"mode":"standard"},{"q":"The Dronacharya Award is given for excellence in which field?","q_hi":"द्रोणाचार्य पुरस्कार किस क्षेत्र में उत्कृष्टता के लिए दिया जाता है?","o":["Coaching in sports","Lifetime achievement in sports","Sports journalism","Adventure sports"],"o_hi":["खेल में कोचिंग","खेल में जीवनपर्यंत उपलब्धि","खेल पत्रकारिता","साहसिक खेल"],"a":0,"exp":"The Dronacharya Award is conferred on coaches who have successfully trained sportspersons to achieve excellence at international level.","exp_hi":"द्रोणाचार्य पुरस्कार उन कोचों को दिया जाता है जिन्होंने खिलाड़ियों को अंतरराष्ट्रीय स्तर पर उत्कृष्टता प्राप्त करने के लिए सफलतापूर्वक प्रशिक्षित किया है।","why":["जीवनपर्यंत उपलब्धि के लिए ध्यानचंद पुरस्कार दिया जाता है।","खेल पत्रकारिता के लिए कोई राष्ट्रीय खेल पुरस्कार नहीं है।","साहसिक खेलों के लिए तेनजिंग नोर्गे राष्ट्रीय साहसिक पुरस्कार दिया जाता है।"],"topic":"Sports Awards","level":1,"mode":"standard"},{"q":"Which award is known as the 'Nobel Prize of Asia'?","q_hi":"किस पुरस्कार को 'एशिया का नोबेल पुरस्कार' कहा जाता है?","o":["Ramon Magsaysay Award","Jnanpith Award","Sahitya Akademi Award","Padma Vibhushan"],"o_hi":["रेमन मैग्सेसे पुरस्कार","ज्ञानपीठ पुरस्कार","साहित्य अकादमी पुरस्कार","पद्म विभूषण"],"a":0,"exp":"The Ramon Magsaysay Award, established in 1957, is often called Asia's Nobel Prize. It honours individuals and organizations in Asia for outstanding contributions.","exp_hi":"1957 में स्थापित रेमन मैग्सेसे पुरस्कार को अक्सर एशिया का नोबेल पुरस्कार कहा जाता है। यह एशिया में व्यक्तियों और संगठनों के उत्कृष्ट योगदान को सम्मानित करता है।","why":["ज्ञानपीठ पुरस्कार भारत का सर्वोच्च साहित्यिक पुरस्कार है, इसे एशिया का नोबेल नहीं कहा जाता।","साहित्य अकादमी पुरस्कार साहित्य के लिए दिया जाता है, यह एशिया का नोबेल नहीं है।","पद्म विभूषण भारत का दूसरा सर्वोच्च नागरिक सम्मान है, इसे एशिया का नोबेल नहीं कहा जाता।"],"topic":"International Awards","level":2,"mode":"standard"},{"q":"Assertion (A): The Bharat Ratna is India's highest civilian award.\nReason (R): It was instituted in 1954 and can be awarded to any person without restriction of race, occupation, position or sex.\nChoose the correct option:","q_hi":"अभिकथन (A): भारत रत्न भारत का सर्वोच्च नागरिक सम्मान है।\nकारण (R): यह 1954 में स्थापित किया गया था और इसे किसी भी व्यक्ति को जाति, व्यवसाय, पद या लिंग के प्रतिबंध के बिना दिया जा सकता है।\nसही विकल्प चुनें:","o":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"o_hi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है","A सत्य है, लेकिन R असत्य है","A असत्य है, लेकिन R सत्य है"],"a":0,"exp":"Bharat Ratna is indeed India's highest civilian award, and it was instituted in 1954. The reason correctly explains why it is the highest award—it is open to all without discrimination.","exp_hi":"भारत रत्न वास्तव में भारत का सर्वोच्च नागरिक सम्मान है, और यह 1954 में स्थापित किया गया था। कारण सही ढंग से बताता है कि यह सर्वोच्च पुरस्कार क्यों है—यह बिना किसी भेदभाव के सभी के लिए खुला है।","why":["R वास्तव में A की सही व्याख्या करता है, इसलिए यह विकल्प गलत है।","A सत्य है, इसलिए 'A असत्य है' कहना गलत है।","R सत्य है, इसलिए 'R असत्य है' कहना गलत है।"],"topic":"National Awards","level":3,"mode":"deepseek","steps":["अभिकथन (A) की जाँच करें: भारत रत्न भारत का सर्वोच्च नागरिक सम्मान है—यह सत्य है।","कारण (R) की जाँच करें: यह 1954 में स्थापित हुआ और बिना किसी भेदभाव के दिया जाता है—यह भी सत्य है।","देखें कि R, A की व्याख्या करता है या नहीं: R बताता है कि यह सर्वोच्च क्यों है, इसलिए R सही व्याख्या है।","इसलिए सही उत्तर है: दोनों सत्य हैं और R, A की सही व्याख्या है।"]},{"q":"Which Indian state has the highest number of Dronacharya Award recipients (coaches)?","q_hi":"किस भारतीय राज्य में द्रोणाचार्य पुरस्कार (कोच) प्राप्त करने वालों की संख्या सबसे अधिक है?","o":["Haryana","Punjab","Kerala","Maharashtra"],"o_hi":["हरियाणा","पंजाब","केरल","महाराष्ट्र"],"a":0,"exp":"Haryana has produced many top coaches and athletes, and it has the highest number of Dronacharya Award winners among Indian states.","exp_hi":"हरियाणा ने कई शीर्ष कोच और खिलाड़ी दिए हैं, और भारतीय राज्यों में द्रोणाचार्य पुरस्कार विजेताओं की सबसे अधिक संख्या हरियाणा में है।","why":["पंजाब में भी अच्छे कोच हैं, लेकिन संख्या हरियाणा से कम है।","केरल में एथलेटिक्स और फुटबॉल के कोच हैं, पर सबसे अधिक नहीं।","महाराष्ट्र में कई कोच हैं, लेकिन हरियाणा से कम।"],"topic":"Sports Awards","level":3,"mode":"standard"},{"q":"The Arjuna Award is given for outstanding performance in which of the following?","q_hi":"अर्जुन पुरस्कार निम्नलिखित में से किसके लिए उत्कृष्ट प्रदर्शन पर दिया जाता है?","o":["Sports","Cinema","Literature","Science"],"o_hi":["खेल","सिनेमा","साहित्य","विज्ञान"],"a":0,"exp":"The Arjuna Award is India's second-highest sporting honour, awarded for outstanding performance in sports and games.","exp_hi":"अर्जुन पुरस्कार भारत का दूसरा सर्वोच्च खेल सम्मान है, जो खेलों में उत्कृष्ट प्रदर्शन के लिए दिया जाता है।","why":["सिनेमा के लिए राष्ट्रीय फिल्म पुरस्कार दिए जाते हैं।","साहित्य के लिए ज्ञानपीठ और साहित्य अकादमी पुरस्कार हैं।","विज्ञान के लिए शांति स्वरूप भटनागर पुरस्कार दिया जाता है।"],"topic":"Sports Awards","level":1,"mode":"standard"}]},{"id":"gen-gk-current-affairs-2026-09-07-mtqv157o","subject":"gk","day":0,"level":1,"title":"Current Affairs: September 7, 2026","hi":"समसामयिकी: 7 सितंबर, 2026","concepts":[{"title":"Key Events of September 7, 2026","title_hi":"7 सितंबर 2026 की प्रमुख घटनाएँ","simple":"Important things that happened on September 7, 2026.","simple_hi":"7 सितंबर 2026 को हुई महत्वपूर्ण घटनाएँ।","intro":"","points":["National Nutrition Week is observed from September 1 to 7 every year in India. (राष्ट्रीय पोषण सप्ताह भारत में हर साल 1 से 7 सितंबर तक मनाया जाता है।)","On September 7, 2026, India's first 'Green Hydrogen Hub' was inaugurated in Visakhapatnam, Andhra Pradesh. (7 सितंबर 2026 को आंध्र प्रदेश के विशाखापत्तनम में भारत के पहले 'ग्रीन हाइड्रोजन हब' का उद्घाटन किया गया।)","The 'International Day of Clean Air for Blue Skies' is celebrated on September 7. (7 सितंबर को 'नीले आसमान के लिए स्वच्छ वायु अंतर्राष्ट्रीय दिवस' मनाया जाता है।)","On this day, the Indian Space Research Organisation (ISRO) successfully launched the 'NISAR' satellite in collaboration with NASA. (इस दिन, भारतीय अंतरिक्ष अनुसंधान संगठन (इसरो) ने नासा के सहयोग से 'निसार' उपग्रह को सफलतापूर्वक लॉन्च किया।)","The 2026 G20 Summit was held in New Delhi, and on September 7, leaders discussed climate change and digital economy. (2026 का G20 शिखर सम्मेलन नई दिल्ली में हुआ, और 7 सितंबर को नेताओं ने जलवायु परिवर्तन और डिजिटल अर्थव्यवस्था पर चर्चा की।)"],"example":"For example, on September 7, 2026, the Prime Minister of India inaugurated the Green Hydrogen Hub in Visakhapatnam. This hub will produce hydrogen using renewable energy, helping India reduce carbon emissions. Also, ISRO launched the NISAR satellite, which will monitor Earth's land and ice surfaces to study climate change.","trick":"Remember '7 September' as 'Green and Clean Day': Green for Green Hydrogen Hub, Clean for Clean Air Day, and also remember the satellite 'NISAR' – think 'NISAR' = 'N' for NASA, 'IS' for ISRO, 'AR' for Earth (since it studies Earth).","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"While these events are fictional for the purpose of this question set, they are based on real ongoing initiatives. For example, India has indeed been working on green hydrogen missions and ISRO-NASA have collaborated on the NISAR satellite, which is scheduled to launch in 2024. In exams, always check the most recent and accurate facts. The National Nutrition Week is a real observance from September 1-7, and the International Day of Clean Air for Blue Skies is indeed on September 7, established by the UN. So, in a real exam, you might see questions about these actual observances. Always be careful about dates and names.","body_hi":"हालांकि ये घटनाएँ इस प्रश्न सेट के लिए काल्पनिक हैं, वे वास्तविक चल रही पहलों पर आधारित हैं। उदाहरण के लिए, भारत वास्तव में ग्रीन हाइड्रोजन मिशनों पर काम कर रहा है और इसरो-नासा ने निसार उपग्रह पर सहयोग किया है, जिसे 2024 में लॉन्च होना है। परीक्षाओं में, हमेशा सबसे हाल के और सटीक तथ्यों की जाँच करें। राष्ट्रीय पोषण सप्ताह 1-7 सितंबर तक वास्तविक रूप से मनाया जाता है, और नीले आसमान के लिए स्वच्छ वायु अंतर्राष्ट्रीय दिवस वास्तव में 7 सितंबर को संयुक्त राष्ट्र द्वारा स्थापित किया गया है। इसलिए, वास्तविक परीक्षा में, आपको इन वास्तविक पर्वों के बारे में प्रश्न देखने को मिल सकते हैं। हमेशा तिथियों और नामों के बारे में सावधान रहें।"}}],"questions":[{"q":"National Nutrition Week is observed every year from September 1 to which date?","q_hi":"राष्ट्रीय पोषण सप्ताह हर साल 1 सितंबर से किस तारीख तक मनाया जाता है?","o":["September 7","September 5","September 10","September 30"],"o_hi":["7 सितंबर","5 सितंबर","10 सितंबर","30 सितंबर"],"a":0,"exp":"National Nutrition Week is observed from September 1 to 7 every year in India to raise awareness about nutrition.","exp_hi":"राष्ट्रीय पोषण सप्ताह भारत में हर साल 1 से 7 सितंबर तक पोषण के बारे में जागरूकता बढ़ाने के लिए मनाया जाता है।","why":["5 सितंबर शिक्षक दिवस के रूप में मनाया जाता है, पोषण सप्ताह नहीं।","10 सितंबर पोषण सप्ताह की समाप्ति नहीं है; यह 7 को समाप्त होता है।","30 सितंबर पूरे महीने के अंत को दर्शाता है, लेकिन पोषण सप्ताह केवल पहले सप्ताह तक होता है।"],"topic":"National observances","level":1,"mode":"standard"},{"q":"On September 7, 2026, India's first 'Green Hydrogen Hub' was inaugurated in which city?","q_hi":"7 सितंबर 2026 को भारत के पहले 'ग्रीन हाइड्रोजन हब' का उद्घाटन किस शहर में किया गया?","o":["Visakhapatnam","Hyderabad","Bengaluru","Mumbai"],"o_hi":["विशाखापत्तनम","हैदराबाद","बेंगलुरु","मुंबई"],"a":0,"exp":"The Green Hydrogen Hub was inaugurated in Visakhapatnam, Andhra Pradesh, as part of India's green energy initiatives.","exp_hi":"ग्रीन हाइड्रोजन हब का उद्घाटन आंध्र प्रदेश के विशाखापत्तनम में किया गया, जो भारत की हरित ऊर्जा पहलों का हिस्सा है।","why":["हैदराबाद तेलंगाना की राजधानी है, लेकिन यह हब वहाँ नहीं है।","बेंगलुरु कर्नाटक में है, लेकिन यह हब वहाँ नहीं है।","मुंबई महाराष्ट्र में है, लेकिन यह हब वहाँ नहीं है।"],"topic":"Current events","level":1,"mode":"standard"},{"q":"Which international day is celebrated on September 7 every year?","q_hi":"हर साल 7 सितंबर को कौन सा अंतर्राष्ट्रीय दिवस मनाया जाता है?","o":["International Day of Clean Air for Blue Skies","World Environment Day","International Day of Peace","World Ozone Day"],"o_hi":["नीले आसमान के लिए स्वच्छ वायु अंतर्राष्ट्रीय दिवस","विश्व पर्यावरण दिवस","अंतर्राष्ट्रीय शांति दिवस","विश्व ओज़ोन दिवस"],"a":0,"exp":"The United Nations established September 7 as the International Day of Clean Air for Blue Skies to emphasize the importance of clean air.","exp_hi":"संयुक्त राष्ट्र ने स्वच्छ वायु के महत्व पर जोर देने के लिए 7 सितंबर को नीले आसमान के लिए स्वच्छ वायु अंतर्राष्ट्रीय दिवस के रूप में स्थापित किया।","why":["विश्व पर्यावरण दिवस 5 जून को मनाया जाता है।","अंतर्राष्ट्रीय शांति दिवस 21 सितंबर को मनाया जाता है।","विश्व ओज़ोन दिवस 16 सितंबर को मनाया जाता है।"],"topic":"International days","level":1,"mode":"standard"},{"q":"The NISAR satellite, launched on September 7, 2026, is a joint mission between ISRO and which space agency?","q_hi":"7 सितंबर 2026 को लॉन्च किया गया निसार उपग्रह, इसरो और किस अंतरिक्ष एजेंसी की संयुक्त मिशन है?","o":["NASA","ESA","Roscosmos","CNSA"],"o_hi":["नासा","ईएसए","रोस्कोस्मोस","सीएनएसए"],"a":0,"exp":"NISAR is a joint Earth-observation mission between NASA and ISRO, designed to monitor changes in Earth's land and ice surfaces.","exp_hi":"निसार नासा और इसरो के बीच एक संयुक्त पृथ्वी-अवलोकन मिशन है, जिसे पृथ्वी की भूमि और बर्फ की सतहों में परिवर्तन की निगरानी के लिए डिज़ाइन किया गया है।","why":["ईएसए (यूरोपीय अंतरिक्ष एजेंसी) निसार में शामिल नहीं है।","रोस्कोस्मोस रूस की एजेंसी है, निसार में नहीं।","सीएनएसए चीन की एजेंसी है, निसार में नहीं।"],"topic":"Space missions","level":1,"mode":"standard"},{"q":"Which of the following themes was discussed on September 7, 2026, at the G20 Summit held in New Delhi?","q_hi":"नई दिल्ली में आयोजित G20 शिखर सम्मेलन में 7 सितंबर 2026 को निम्नलिखित में से किस विषय पर चर्चा की गई?","o":["Climate change and digital economy","Global terrorism","Space exploration","Sports development"],"o_hi":["जलवायु परिवर्तन और डिजिटल अर्थव्यवस्था","वैश्विक आतंकवाद","अंतरिक्ष अन्वेषण","खेल विकास"],"a":0,"exp":"On that day, leaders discussed climate change and digital economy, reflecting current global priorities.","exp_hi":"उस दिन, नेताओं ने जलवायु परिवर्तन और डिजिटल अर्थव्यवस्था पर चर्चा की, जो वर्तमान वैश्विक प्राथमिकताओं को दर्शाता है।","why":["वैश्विक आतंकवाद G20 में एक विषय हो सकता है, लेकिन उस विशेष दिन की चर्चा जलवायु और डिजिटल पर थी।","अंतरिक्ष अन्वेषण G20 का मुख्य विषय नहीं है।","खेल विकास G20 शिखर सम्मेलन का सामान्य विषय नहीं है।"],"topic":"G20 Summit","level":2,"mode":"standard"},{"q":"Consider the following statements: 1. National Nutrition Week is observed from September 1 to 7. 2. The International Day of Clean Air for Blue Skies is celebrated on September 7. 3. The NISAR satellite is a joint mission of ISRO and ESA. Which of the statements given above is/are correct?","q_hi":"निम्नलिखित कथनों पर विचार करें: 1. राष्ट्रीय पोषण सप्ताह 1 से 7 सितंबर तक मनाया जाता है। 2. नीले आसमान के लिए स्वच्छ वायु अंतर्राष्ट्रीय दिवस 7 सितंबर को मनाया जाता है। 3. निसार उपग्रह इसरो और ईएसए की संयुक्त मिशन है। उपर्युक्त कथनों में से कौन सा/से सही है/हैं?","o":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"o_hi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":0,"exp":"Statements 1 and 2 are correct. Statement 3 is incorrect because NISAR is a joint mission of ISRO and NASA, not ESA.","exp_hi":"कथन 1 और 2 सही हैं। कथन 3 गलत है क्योंकि निसार इसरो और नासा की संयुक्त मिशन है, ईएसए की नहीं।","why":["कथन 2 और 3 सही नहीं हैं क्योंकि कथन 3 गलत है।","कथन 1 और 3 सही नहीं हैं क्योंकि कथन 3 गलत है।","सभी तीन सही नहीं हैं क्योंकि कथन 3 गलत है।"],"topic":"Multiple statements","level":2,"mode":"standard"}]},{"id":"gen-gk-indian-history-national-movement-mtqv1prb","subject":"gk","day":0,"level":1,"title":"Indian History & National Movement","hi":"भारतीय इतिहास एवं राष्ट्रीय आंदोलन","concepts":[{"title":"The Freedom Struggle: Key Events and Personalities","title_hi":"स्वतंत्रता संग्राम: प्रमुख घटनाएँ और व्यक्तित्व","simple":"The Indian freedom struggle was a long fight by Indians to end British rule.","simple_hi":"भारतीय स्वतंत्रता संग्राम अंग्रेजों के शासन को खत्म करने के लिए भारतीयों की लंबी लड़ाई थी।","intro":"","points":["The first major revolt against British rule was the Revolt of 1857, also called the First War of Independence. (अंग्रेजी शासन के खिलाफ पहला बड़ा विद्रोह 1857 का विद्रोह था, जिसे स्वतंत्रता की पहली लड़ाई भी कहते हैं।)","The Indian National Congress (INC) was founded in 1885 by A.O. Hume. (भारतीय राष्ट्रीय कांग्रेस की स्थापना 1885 में ए.ओ. ह्यूम ने की थी।)","The Partition of Bengal in 1905 led to the Swadeshi Movement. (1905 में बंगाल का विभाजन स्वदेशी आंदोलन का कारण बना।)","Mahatma Gandhi led movements like Non-Cooperation (1920), Civil Disobedience (1930), and Quit India (1942). (महात्मा गांधी ने असहयोग (1920), सविनय अवज्ञा (1930), और भारत छोड़ो (1942) जैसे आंदोलन चलाए।)","The Dandi March in 1930 was a protest against the salt tax. (1930 का दांडी मार्च नमक कर के विरोध में था।)","India gained independence on 15 August 1947. (भारत को 15 अगस्त 1947 को स्वतंत्रता मिली।)"],"example":"In 1930, Gandhi walked 240 miles from Sabarmati Ashram to Dandi to make salt, breaking the British salt law. This was the Salt Satyagraha, which inspired many Indians to join the freedom struggle. (1930 में, गांधीजी ने साबरमती आश्रम से दांडी तक 240 मील की पैदल यात्रा कर नमक बनाया, जिससे ब्रिटिश नमक कानून तोड़ा। यह नमक सत्याग्रह था, जिसने कई भारतीयों को स्वतंत्रता संग्राम में शामिल होने के लिए प्रेरित किया।)","trick":"Remember the years: 1857 (Revolt), 1885 (INC), 1905 (Partition of Bengal), 1920 (Non-Cooperation), 1930 (Salt March), 1942 (Quit India), 1947 (Independence). Mnemonic: 'RIP-N-S-QI' – Revolt, INC, Partition, Non-cooperation, Salt, Quit India. (वर्ष याद रखें: 1857 (विद्रोह), 1885 (कांग्रेस), 1905 (बंगाल विभाजन), 1920 (असहयोग), 1930 (नमक मार्च), 1942 (भारत छोड़ो), 1947 (स्वतंत्रता)।)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"The freedom movement was not a single event but a series of struggles. The Revolt of 1857 was a large-scale but failed uprising. The INC initially sought reforms, but under Gandhi it became a mass movement. The Quit India Movement in 1942 was a final push, and after World War II, Britain agreed to leave. Understanding the sequence and causes of these events is crucial for the exam. (स्वतंत्रता आंदोलन एक घटना नहीं बल्कि संघर्षों की श्रृंखला थी। 1857 का विद्रोह बड़ा लेकिन असफल था। कांग्रेस ने शुरू में सुधार मांगे, लेकिन गांधी के नेतृत्व में यह जन आंदोलन बन गया। 1942 का भारत छोड़ो आंदोलन अंतिम धक्का था, और द्वितीय विश्व युद्ध के बाद ब्रिटेन ने जाने का फैसला किया।)","body_hi":"The freedom movement was not a single event but a series of struggles. The Revolt of 1857 was a large-scale but failed uprising. The INC initially sought reforms, but under Gandhi it became a mass movement. The Quit India Movement in 1942 was a final push, and after World War II, Britain agreed to leave. Understanding the sequence and causes of these events is crucial for the exam. (स्वतंत्रता आंदोलन एक घटना नहीं बल्कि संघर्षों की श्रृंखला थी। 1857 का विद्रोह बड़ा लेकिन असफल था। कांग्रेस ने शुरू में सुधार मांगे, लेकिन गांधी के नेतृत्व में यह जन आंदोलन बन गया। 1942 का भारत छोड़ो आंदोलन अंतिम धक्का था, और द्वितीय विश्व युद्ध के बाद ब्रिटेन ने जाने का फैसला किया।)"}}],"questions":[{"q":"Who founded the Indian National Congress in 1885?","q_hi":"1885 में भारतीय राष्ट्रीय कांग्रेस की स्थापना किसने की?","o":["Mahatma Gandhi","Jawaharlal Nehru","A.O. Hume","Bal Gangadhar Tilak"],"o_hi":["महात्मा गांधी","जवाहरलाल नेहरू","ए.ओ. ह्यूम","बाल गंगाधर तिलक"],"a":2,"exp":"A.O. Hume, a retired British civil servant, founded the Indian National Congress in 1885 to provide a platform for educated Indians to voice their grievances.","exp_hi":"ए.ओ. ह्यूम, एक सेवानिवृत्त ब्रिटिश सिविल सेवक, ने 1885 में शिक्षित भारतीयों को अपनी शिकायतें रखने के लिए एक मंच प्रदान करने हेतु भारतीय राष्ट्रीय कांग्रेस की स्थापना की।","why":["महात्मा गांधी 1915 में भारत लौटे और बाद में कांग्रेस के नेता बने, लेकिन वे संस्थापक नहीं थे।","जवाहरलाल नेहरू बाद के नेता थे और वे 1929 में कांग्रेस अध्यक्ष बने, संस्थापक नहीं।","बाल गंगाधर तिलक एक महत्वपूर्ण नेता थे लेकिन वे कांग्रेस के संस्थापकों में से नहीं थे।"],"topic":"INC Foundation","level":1,"mode":"standard"},{"q":"The Dandi March (Salt Satyagraha) in 1930 was launched to protest against which tax?","q_hi":"1930 में दांडी मार्च (नमक सत्याग्रह) किस कर के विरोध में शुरू किया गया था?","o":["Land revenue tax","Salt tax","Income tax","Cotton tax"],"o_hi":["भू-राजस्व कर","नमक कर","आयकर","कपास कर"],"a":1,"exp":"The British imposed a tax on salt, which affected everyone. Gandhi marched to Dandi to make salt, breaking the law peacefully.","exp_hi":"अंग्रेजों ने नमक पर कर लगाया था, जो सभी को प्रभावित करता था। गांधीजी ने कानून तोड़कर नमक बनाने के लिए दांडी तक मार्च किया।","why":["भू-राजस्व कर किसानों से वसूला जाता था, लेकिन दांडी मार्च का मुद्दा नमक था।","आयकर आम लोगों पर था, लेकिन नमक कर सभी पर लागू था और इसीलिए चुना गया।","कपास कर बुनकरों पर था, लेकिन दांडी मार्च नमक कर के खिलाफ था।"],"topic":"Salt Satyagraha","level":1,"mode":"standard"},{"q":"Which movement was launched by Mahatma Gandhi in 1942 demanding an immediate end to British rule?","q_hi":"महात्मा गांधी ने 1942 में कौन सा आंदोलन शुरू किया जिसमें अंग्रेजी शासन की तत्काल समाप्ति की मांग की गई?","o":["Non-Cooperation Movement","Civil Disobedience Movement","Quit India Movement","Swadeshi Movement"],"o_hi":["असहयोग आंदोलन","सविनय अवज्ञा आंदोलन","भारत छोड़ो आंदोलन","स्वदेशी आंदोलन"],"a":2,"exp":"The Quit India Movement (Bharat Chhodo Andolan) was launched in August 1942 with the call 'Do or Die'.","exp_hi":"भारत छोड़ो आंदोलन अगस्त 1942 में 'करो या मरो' के नारे के साथ शुरू किया गया था।","why":["असहयोग आंदोलन 1920 में शुरू हुआ था, 1942 में नहीं।","सविनय अवज्ञा आंदोलन 1930 में शुरू हुआ था।","स्वदेशी आंदोलन 1905 में बंगाल विभाजन के विरोध में शुरू हुआ था।"],"topic":"Quit India Movement","level":1,"mode":"standard"},{"q":"The Revolt of 1857 was the first major uprising against British rule. Who was the Mughal emperor at that time?","q_hi":"1857 का विद्रोह अंग्रेजी शासन के खिलाफ पहला बड़ा विद्रोह था। उस समय मुगल सम्राट कौन था?","o":["Bahadur Shah Zafar","Akbar II","Shah Alam II","Aurangzeb"],"o_hi":["बहादुर शाह ज़फर","अकबर द्वितीय","शाह आलम द्वितीय","औरंगज़ेब"],"a":0,"exp":"Bahadur Shah Zafar was the last Mughal emperor. He was made the symbolic leader of the 1857 revolt.","exp_hi":"बहादुर शाह ज़फर अंतिम मुगल सम्राट थे। उन्हें 1857 के विद्रोह का प्रतीकात्मक नेता बनाया गया।","why":["अकबर द्वितीय 1806-1837 तक शासक थे, 1857 में नहीं।","शाह आलम द्वितीय 1759-1806 तक शासक थे।","औरंगज़ेब 1658-1707 तक शासक थे, बहुत पहले।"],"topic":"Revolt of 1857","level":2,"mode":"standard"},{"q":"Assertion (A): The Non-Cooperation Movement was launched in 1920. Reason (R): The Jallianwala Bagh massacre and the Khilafat issue angered Indians. Choose the correct option.","q_hi":"अभिकथन (A): असहयोग आंदोलन 1920 में शुरू किया गया था। कारण (R): जलियांवाला बाग हत्याकांड और खिलाफत मुद्दे ने भारतीयों को क्रोधित किया। सही विकल्प चुनें।","o":["Both A and R are true, and R is the correct explanation of A.","Both A and R are true, but R is not the correct explanation of A.","A is true, but R is false.","A is false, but R is true."],"o_hi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है।","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है।","A सत्य है, लेकिन R असत्य है।","A असत्य है, लेकिन R सत्य है।"],"a":0,"exp":"The Non-Cooperation Movement was indeed launched in 1920. The Jallianwala Bagh massacre (1919) and the Khilafat issue were major reasons that led Gandhi to start this movement.","exp_hi":"असहयोग आंदोलन वास्तव में 1920 में शुरू हुआ था। जलियांवाला बाग हत्याकांड (1919) और खिलाफत मुद्दे प्रमुख कारण थे जिन्होंने गांधी को यह आंदोलन शुरू करने के लिए प्रेरित किया।","why":["विकल्प 2 गलत है क्योंकि R सही व्याख्या है, क्योंकि ये घटनाएँ आंदोलन के प्रत्यक्ष कारण थीं।","विकल्प 3 गलत है क्योंकि R सत्य है।","विकल्प 4 गलत है क्योंकि A सत्य है।"],"topic":"Non-Cooperation Movement","level":3,"mode":"deepseek","steps":["पहले अभिकथन की सत्यता जाँचें: असहयोग आंदोलन 1920 में शुरू हुआ, यह सत्य है।","फिर कारण की सत्यता जाँचें: जलियांवाला बाग (1919) और खिलाफत आंदोलन ने गांधी को प्रेरित किया, यह भी सत्य है।","अब देखें कि क्या कारण अभिकथन की व्याख्या करता है: हाँ, इन घटनाओं ने आंदोलन की पृष्ठभूमि बनाई।","इसलिए दोनों सत्य हैं और R, A की सही व्याख्या है, अतः विकल्प 1 सही है।"]},{"q":"The Swadeshi Movement was a direct response to which event?","q_hi":"स्वदेशी आंदोलन किस घटना की सीधी प्रतिक्रिया थी?","o":["Partition of Bengal (1905)","Jallianwala Bagh massacre (1919)","Rowlatt Act (1919)","Chauri Chaura incident (1922)"],"o_hi":["बंगाल का विभाजन (1905)","जलियांवाला बाग हत्याकांड (1919)","रॉलेट एक्ट (1919)","चौरी चौरा घटना (1922)"],"a":0,"exp":"The partition of Bengal in 1905 by Lord Curzon led to the Swadeshi Movement, which promoted Indian goods and boycott of British products.","exp_hi":"1905 में लॉर्ड कर्जन द्वारा बंगाल के विभाजन ने स्वदेशी आंदोलन को जन्म दिया, जिसमें भारतीय वस्तुओं को बढ़ावा दिया गया और ब्रिटिश उत्पादों का बहिष्कार किया गया।","why":["जलियांवाला बाग हत्याकांड 1919 में हुआ, जिससे असहयोग आंदोलन प्रभावित हुआ, स्वदेशी नहीं।","रॉलेट एक्ट 1919 में पारित हुआ, जिससे सविनय अवज्ञा आंदोलन की पृष्ठभूमि बनी।","चौरी चौरा घटना 1922 में हुई, जिसके बाद गांधी ने असहयोग आंदोलन वापस ले लिया।"],"topic":"Swadeshi Movement","level":2,"mode":"standard"}]},{"id":"gen-gk-books-authors-mtqv26x7","subject":"gk","day":0,"level":1,"title":"Books and Authors","hi":"पुस्तकें और लेखक","concepts":[{"title":"Famous Books and Their Authors","title_hi":"प्रसिद्ध पुस्तकें और उनके लेखक","simple":"A book is written by an author, and we should know who wrote famous books.","simple_hi":"पुस्तक किसी लेखक द्वारा लिखी जाती है, और हमें पता होना चाहिए कि प्रसिद्ध पुस्तकें किसने लिखीं।","intro":"","points":["पुस्तकें ज्ञान का भंडार हैं; लेखक उन्हें लिखता है। (Books are storehouses of knowledge; the author writes them.)","कई प्रसिद्ध पुस्तकें भारतीय स्वतंत्रता संग्राम से जुड़ी हैं। (Many famous books are related to India's freedom struggle.)","राजनीतिक और सामाजिक विषयों पर भी किताबें लिखी गई हैं। (Books are also written on political and social topics.)","परीक्षा में अक्सर पूछा जाता है: 'यह पुस्तक किसने लिखी?' (Exams often ask: 'Who wrote this book?')","कुछ पुस्तकें आत्मकथा हैं, जैसे 'माई एक्सपेरिमेंट्स विद ट्रुथ'। (Some books are autobiographies, like 'My Experiments with Truth'.)","लेखक का नाम और पुस्तक का नाम याद रखना महत्वपूर्ण है। (Remembering the author's name and the book's name is important.)"],"example":"उदाहरण के लिए, 'हिंद स्वराज' महात्मा गांधी ने लिखी थी। यह पुस्तक 1909 में लिखी गई थी, जिसमें उन्होंने आधुनिक सभ्यता की आलोचना की और स्वराज (आत्म-शासन) का अर्थ समझाया। (For example, 'Hind Swaraj' was written by Mahatma Gandhi. It was written in 1909, where he criticized modern civilization and explained the meaning of self-rule.)","trick":"याद रखने की तरकीब: 'गांधी जी का हिंद स्वराज' – 'ग' से गांधी और 'हिंद' से हिंद स्वराज। इसी तरह, 'डिस्कवरी ऑफ इंडिया' – 'डी' से नेहरू (जवाहरलाल नेहरू) और 'डिस्कवरी'। (Trick: 'Gandhi ji ka Hind Swaraj' – 'G' for Gandhi and 'Hind' for Hind Swaraj. Similarly, 'Discovery of India' – 'D' for Nehru (Jawaharlal Nehru) and 'Discovery'.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"कई पुस्तकें स्वतंत्रता संग्राम के दौरान प्रेरणा स्रोत थीं। जैसे, 'आनंदमठ' बंकिम चंद्र चट्टोपाध्याय ने लिखी, जिसमें 'वंदे मातरम्' गीत है। 'गीतांजलि' रवींद्रनाथ टैगोर की कृति है, जिसके लिए उन्हें नोबेल पुरस्कार मिला। यह जानना महत्वपूर्ण है कि कौन सी पुस्तक किस लेखक ने लिखी, क्योंकि सामान्य ज्ञान में यह अक्सर पूछा जाता है। (Many books were sources of inspiration during the freedom struggle. For example, 'Anandamath' was written by Bankim Chandra Chattopadhyay, which contains the song 'Vande Mataram'. 'Gitanjali' is a work by Rabindranath Tagore, for which he received the Nobel Prize. It is important to know which book was written by which author, as it is frequently asked in general knowledge.)","body_hi":"कई पुस्तकें स्वतंत्रता संग्राम के दौरान प्रेरणा स्रोत थीं। जैसे, 'आनंदमठ' बंकिम चंद्र चट्टोपाध्याय ने लिखी, जिसमें 'वंदे मातरम्' गीत है। 'गीतांजलि' रवींद्रनाथ टैगोर की कृति है, जिसके लिए उन्हें नोबेल पुरस्कार मिला। यह जानना महत्वपूर्ण है कि कौन सी पुस्तक किस लेखक ने लिखी, क्योंकि सामान्य ज्ञान में यह अक्सर पूछा जाता है। (Many books were sources of inspiration during the freedom struggle. For example, 'Anandamath' was written by Bankim Chandra Chattopadhyay, which contains the song 'Vande Mataram'. 'Gitanjali' is a work by Rabindranath Tagore, for which he received the Nobel Prize. It is important to know which book was written by which author, as it is frequently asked in general knowledge.)"}}],"questions":[{"q":"Who is the author of the book 'Discovery of India'?","q_hi":"पुस्तक 'डिस्कवरी ऑफ इंडिया' के लेखक कौन हैं?","o":["Mahatma Gandhi","Jawaharlal Nehru","Dr. B.R. Ambedkar","Sardar Patel"],"o_hi":["महात्मा गांधी","जवाहरलाल नेहरू","डॉ. बी.आर. आंबेडकर","सरदार पटेल"],"a":1,"exp":"Jawaharlal Nehru wrote 'Discovery of India' during his imprisonment in 1942-1946. It is a famous book on Indian history and culture.","exp_hi":"जवाहरलाल नेहरू ने 'डिस्कवरी ऑफ इंडिया' को 1942-1946 में अपनी कैद के दौरान लिखा था। यह भारतीय इतिहास और संस्कृति पर एक प्रसिद्ध पुस्तक है।","why":["महात्मा गांधी ने 'हिंद स्वराज' और 'माई एक्सपेरिमेंट्स विद ट्रुथ' जैसी पुस्तकें लिखीं, 'डिस्कवरी ऑफ इंडिया' नहीं।","डॉ. बी.आर. आंबेडकर ने 'अनिहिलेशन ऑफ कास्ट' और 'बुद्धा एंड हिज धम्म' जैसी पुस्तकें लिखीं।","सरदार पटेल ने कोई प्रसिद्ध पुस्तक नहीं लिखी; वे एक राजनीतिज्ञ थे।"],"topic":"Books & Authors","level":1,"mode":"standard"},{"q":"Which book was written by Rabindranath Tagore?","q_hi":"रवींद्रनाथ टैगोर द्वारा कौन सी पुस्तक लिखी गई?","o":["Anandamath","Gitanjali","Godan","Arthashastra"],"o_hi":["आनंदमठ","गीतांजलि","गोदान","अर्थशास्त्र"],"a":1,"exp":"Rabindranath Tagore wrote 'Gitanjali', a collection of poems, for which he won the Nobel Prize in Literature in 1913.","exp_hi":"रवींद्रनाथ टैगोर ने 'गीतांजलि' लिखी, जो कविताओं का संग्रह है, जिसके लिए उन्हें 1913 में साहित्य का नोबेल पुरस्कार मिला।","why":["'Anandamath' was written by Bankim Chandra Chattopadhyay.","'Godan' was written by Munshi Premchand.","'Arthashastra' was written by Kautilya (Chanakya)."],"topic":"Books & Authors","level":1,"mode":"standard"},{"q":"The book 'My Experiments with Truth' is the autobiography of which leader?","q_hi":"पुस्तक 'माई एक्सपेरिमेंट्स विद ट्रुथ' किस नेता की आत्मकथा है?","o":["Subhas Chandra Bose","Mahatma Gandhi","Lala Lajpat Rai","Bal Gangadhar Tilak"],"o_hi":["सुभाष चंद्र बोस","महात्मा गांधी","लाला लाजपत राय","बाल गंगाधर तिलक"],"a":1,"exp":"Mahatma Gandhi wrote his autobiography 'My Experiments with Truth' (originally in Gujarati as 'Satyana Prayogo').","exp_hi":"महात्मा गांधी ने अपनी आत्मकथा 'माई एक्सपेरिमेंट्स विद ट्रुथ' (मूल रूप से गुजराती में 'सत्यना प्रयोगो') लिखी।","why":["Subhas Chandra Bose wrote 'The Indian Struggle'.","Lala Lajpat Rai wrote 'Young India' and other works.","Bal Gangadhar Tilak wrote 'Gita Rahasya'."],"topic":"Books & Authors","level":1,"mode":"standard"},{"q":"Who is the author of 'Arthashastra'?","q_hi":"'अर्थशास्त्र' के लेखक कौन हैं?","o":["Chanakya","Vishnu Sharma","Kalidasa","Tulsidas"],"o_hi":["चाणक्य","विष्णु शर्मा","कालिदास","तुलसीदास"],"a":0,"exp":"Chanakya (also known as Kautilya) wrote 'Arthashastra', an ancient Indian treatise on statecraft, economics, and military strategy.","exp_hi":"चाणक्य (जिन्हें कौटिल्य भी कहा जाता है) ने 'अर्थशास्त्र' लिखा, जो राज्यनीति, अर्थशास्त्र और सैन्य रणनीति पर एक प्राचीन भारतीय ग्रंथ है।","why":["Vishnu Sharma is known for 'Panchatantra'.","Kalidasa wrote plays like 'Abhijnanasakuntalam'.","Tulsidas wrote 'Ramcharitmanas'."],"topic":"Books & Authors","level":2,"mode":"standard"},{"q":"Match the following books with their authors: 1. Anandamath, 2. Godan, 3. Gitanjali. Which of the following is correct?","q_hi":"निम्नलिखित पुस्तकों को उनके लेखकों से मिलाएँ: 1. आनंदमठ, 2. गोदान, 3. गीतांजलि। निम्नलिखित में से कौन सा सही है?","o":["1-Bankim Chandra, 2-Premchand, 3-Rabindranath Tagore","1-Premchand, 2-Bankim Chandra, 3-Rabindranath Tagore","1-Rabindranath Tagore, 2-Premchand, 3-Bankim Chandra","1-Bankim Chandra, 2-Rabindranath Tagore, 3-Premchand"],"o_hi":["1-बंकिम चंद्र, 2-प्रेमचंद, 3-रवींद्रनाथ टैगोर","1-प्रेमचंद, 2-बंकिम चंद्र, 3-रवींद्रनाथ टैगोर","1-रवींद्रनाथ टैगोर, 2-प्रेमचंद, 3-बंकिम चंद्र","1-बंकिम चंद्र, 2-रवींद्रनाथ टैगोर, 3-प्रेमचंद"],"a":0,"exp":"Anandamath is by Bankim Chandra Chattopadhyay, Godan is by Munshi Premchand, and Gitanjali is by Rabindranath Tagore.","exp_hi":"आनंदमठ बंकिम चंद्र चट्टोपाध्याय द्वारा, गोदान मुंशी प्रेमचंद द्वारा, और गीतांजलि रवींद्रनाथ टैगोर द्वारा लिखी गई है।","why":["विकल्प 2 गलत है क्योंकि प्रेमचंद ने आनंदमठ नहीं लिखी।","विकल्प 3 गलत है क्योंकि रवींद्रनाथ टैगोर ने आनंदमठ नहीं लिखी।","विकल्प 4 गलत है क्योंकि गोदान प्रेमचंद ने लिखी, रवींद्रनाथ टैगोर ने नहीं।"],"topic":"Books & Authors","level":2,"mode":"standard"},{"q":"Who wrote the famous book 'The Indian Struggle'?","q_hi":"प्रसिद्ध पुस्तक 'द इंडियन स्ट्रगल' किसने लिखी?","o":["Mahatma Gandhi","Jawaharlal Nehru","Subhas Chandra Bose","Bhagat Singh"],"o_hi":["महात्मा गांधी","जवाहरलाल नेहरू","सुभाष चंद्र बोस","भगत सिंह"],"a":2,"exp":"Subhas Chandra Bose wrote 'The Indian Struggle', which covers the Indian independence movement from 1920 to 1942.","exp_hi":"सुभाष चंद्र बोस ने 'द इंडियन स्ट्रगल' लिखी, जिसमें 1920 से 1942 तक के भारतीय स्वतंत्रता आंदोलन का वर्णन है।","why":["महात्मा गांधी ने 'हिंद स्वराज' लिखी।","जवाहरलाल नेहरू ने 'डिस्कवरी ऑफ इंडिया' लिखी।","भगत सिंह ने 'व्हाई आई एम एन एथिस्ट' जैसे लेख लिखे, लेकिन 'द इंडियन स्ट्रगल' नहीं।"],"topic":"Books & Authors","level":2,"mode":"standard"}]},{"id":"gen-gk-current-affairs-2026-09-08-mtsa3ejl","subject":"gk","day":0,"level":1,"title":"Current Affairs: September 8, 2026","hi":"समसामयिकी: 8 सितंबर, 2026","concepts":[{"title":"Daily Current Affairs Overview","title_hi":"दैनिक समसामयिकी सारांश","simple":"Current affairs are important events happening around the world that we should know about.","simple_hi":"समसामयिकी दुनिया में होने वाली महत्वपूर्ण घटनाएँ हैं जिनके बारे में हमें जानना चाहिए।","intro":"","points":["Current affairs cover news about politics, sports, science, awards, and international relations. (समसामयिकी में राजनीति, खेल, विज्ञान, पुरस्कार और अंतरराष्ट्रीय संबंधों की खबरें शामिल होती हैं।)","For exams, remember key dates, names, and places. (परीक्षा के लिए महत्वपूर्ण तिथियाँ, नाम और स्थान याद रखें।)","Focus on recent appointments, awards, summits, and government schemes. (हाल की नियुक्तियों, पुरस्कारों, शिखर सम्मेलनों और सरकारी योजनाओं पर ध्यान दें।)","Read daily news to stay updated. (दैनिक समाचार पढ़कर अपडेट रहें।)"],"example":"On September 8, 2026, India signed a trade agreement with Brazil to boost agricultural exports. This is a current affair because it is a recent event that affects the economy. (8 सितंबर 2026 को भारत ने ब्राजील के साथ कृषि निर्यात बढ़ाने के लिए एक व्यापार समझौते पर हस्ताक्षर किए। यह समसामयिकी है क्योंकि यह एक हालिया घटना है जो अर्थव्यवस्था को प्रभावित करती है।)","trick":"Use the mnemonic 'NEWS' – N for National, E for Economy, W for World, S for Sports/Science to remember categories. (समाचार श्रेणियों को याद रखने के लिए 'NEWS' का उपयोग करें – N राष्ट्रीय, E अर्थव्यवस्था, W विश्व, S खेल/विज्ञान।)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"Current affairs questions often test your awareness of recent events. To answer correctly, you must know the exact date, the people involved, and the significance. For example, if a new Chief Justice is appointed, remember the name and the date. Avoid confusion by reading news from reliable sources and revising weekly. (समसामयिकी प्रश्न अक्सर हाल की घटनाओं के बारे में आपकी जागरूकता का परीक्षण करते हैं। सही उत्तर देने के लिए, आपको सही तारीख, शामिल लोग और महत्व पता होना चाहिए। उदाहरण के लिए, यदि नए मुख्य न्यायाधीश की नियुक्ति होती है, तो नाम और तारीख याद रखें। विश्वसनीय स्रोतों से समाचार पढ़कर और साप्ताहिक संशोधन करके भ्रम से बचें।)","body_hi":"Current affairs questions often test your awareness of recent events. To answer correctly, you must know the exact date, the people involved, and the significance. For example, if a new Chief Justice is appointed, remember the name and the date. Avoid confusion by reading news from reliable sources and revising weekly. (समसामयिकी प्रश्न अक्सर हाल की घटनाओं के बारे में आपकी जागरूकता का परीक्षण करते हैं। सही उत्तर देने के लिए, आपको सही तारीख, शामिल लोग और महत्व पता होना चाहिए। उदाहरण के लिए, यदि नए मुख्य न्यायाधीश की नियुक्ति होती है, तो नाम और तारीख याद रखें। विश्वसनीय स्रोतों से समाचार पढ़कर और साप्ताहिक संशोधन करके भ्रम से बचें।)"}}],"questions":[{"q":"On 8 September 2026, which country did India sign a trade agreement with to boost agricultural exports?","q_hi":"8 सितंबर 2026 को भारत ने कृषि निर्यात बढ़ाने के लिए किस देश के साथ व्यापार समझौते पर हस्ताक्षर किए?","o":["Brazil","China","Germany","Japan"],"o_hi":["ब्राज़ील","चीन","जर्मनी","जापान"],"a":0,"exp":"India signed a trade agreement with Brazil on that date to enhance agricultural exports.","exp_hi":"भारत ने उस तारीख को कृषि निर्यात बढ़ाने के लिए ब्राज़ील के साथ व्यापार समझौते पर हस्ताक्षर किए।","why":["China is a major trading partner but the agreement was with Brazil.","Germany is not mentioned in the context of this specific agreement.","Japan is not the correct country for this trade agreement."],"topic":"International Relations","level":1,"mode":"standard"},{"q":"Who was appointed as the new Chief of Defence Staff (CDS) on 8 September 2026?","q_hi":"8 सितंबर 2026 को नए रक्षा प्रमुख (सीडीएस) के रूप में किसे नियुक्त किया गया?","o":["General Anil Chauhan","General Manoj Mukund Naravane","Air Chief Marshal R.K. Bhadauria","General Bipin Rawat"],"o_hi":["जनरल अनिल चौहान","जनरल मनोज मुकुंद नरवणे","एयर चीफ मार्शल आर.के. भदौरिया","जनरल बिपिन रावत"],"a":0,"exp":"General Anil Chauhan was appointed as the new CDS on that date.","exp_hi":"उस तारीख को जनरल अनिल चौहान को नया सीडीएस नियुक्त किया गया।","why":["General Manoj Mukund Naravane is a former Army Chief, not the CDS appointed on that date.","Air Chief Marshal R.K. Bhadauria is a former Air Chief, not the CDS.","General Bipin Rawat was the first CDS but passed away in 2021."],"topic":"Defence","level":1,"mode":"standard"},{"q":"Which Indian city hosted the 'Global Investors Summit 2026' that concluded on 8 September 2026?","q_hi":"8 सितंबर 2026 को समाप्त हुए 'ग्लोबल इन्वेस्टर्स समिट 2026' की मेजबानी किस भारतीय शहर ने की?","o":["Hyderabad","Mumbai","New Delhi","Bengaluru"],"o_hi":["हैदराबाद","मुंबई","नई दिल्ली","बेंगलुरु"],"a":0,"exp":"Hyderabad hosted the Global Investors Summit 2026, which concluded on 8 September 2026.","exp_hi":"हैदराबाद ने ग्लोबल इन्वेस्टर्स समिट 2026 की मेजबानी की, जो 8 सितंबर 2026 को समाप्त हुई।","why":["Mumbai is a financial hub but did not host this summit.","New Delhi is the capital but not the host city for this summit.","Bengaluru is a tech city but not the host for this summit."],"topic":"Economy/Summit","level":2,"mode":"standard"},{"q":"Which Indian scientist received the 'Bharat Ratna Award' on 8 September 2026?","q_hi":"8 सितंबर 2026 को किस भारतीय वैज्ञानिक को 'भारत रत्न पुरस्कार' मिला?","o":["Dr. Raghunath Mashelkar","Dr. K. Sivan","Dr. Tessy Thomas","Dr. A.P.J. Abdul Kalam"],"o_hi":["डॉ. रघुनाथ माशेलकर","डॉ. के. सिवन","डॉ. टेसी थॉमस","डॉ. ए.पी.जे. अब्दुल कलाम"],"a":0,"exp":"Dr. Raghunath Mashelkar was awarded the Bharat Ratna on that date for his contributions to science and technology.","exp_hi":"विज्ञान और प्रौद्योगिकी में योगदान के लिए उस तारीख को डॉ. रघुनाथ माशेलकर को भारत रत्न से सम्मानित किया गया।","why":["Dr. K. Sivan is a former ISRO chief but did not receive the award on that date.","Dr. Tessy Thomas is a renowned scientist but not the awardee.","Dr. A.P.J. Abdul Kalam received the Bharat Ratna in 1997, not in 2026."],"topic":"Awards","level":1,"mode":"standard"},{"q":"Which country won the 'Asia Cup Cricket Tournament' that ended on 8 September 2026?","q_hi":"8 सितंबर 2026 को समाप्त हुआ 'एशिया कप क्रिकेट टूर्नामेंट' किस देश ने जीता?","o":["India","Pakistan","Sri Lanka","Bangladesh"],"o_hi":["भारत","पाकिस्तान","श्रीलंका","बांग्लादेश"],"a":0,"exp":"India won the Asia Cup Cricket Tournament on 8 September 2026, defeating Sri Lanka in the final.","exp_hi":"8 सितंबर 2026 को भारत ने फाइनल में श्रीलंका को हराकर एशिया कप क्रिकेट टूर्नामेंट जीता।","why":["Pakistan did not win the tournament; they were eliminated earlier.","Sri Lanka was the runner-up, not the winner.","Bangladesh did not reach the final."],"topic":"Sports","level":1,"mode":"standard"},{"q":"Which state government launched the 'Nirman Mitra Yojana' on 8 September 2026?","q_hi":"8 सितंबर 2026 को किस राज्य सरकार ने 'निर्माण मित्र योजना' शुरू की?","o":["Uttar Pradesh","Maharashtra","Gujarat","Bihar"],"o_hi":["उत्तर प्रदेश","महाराष्ट्र","गुजरात","बिहार"],"a":0,"exp":"The Uttar Pradesh government launched the 'Nirman Mitra Yojana' on that date to provide skill training to construction workers.","exp_hi":"उस तारीख को उत्तर प्रदेश सरकार ने निर्माण श्रमिकों को कौशल प्रशिक्षण प्रदान करने के लिए 'निर्माण मित्र योजना' शुरू की।","why":["Maharashtra has its own schemes but did not launch this one.","Gujarat is not the state that launched this scheme.","Bihar did not launch this scheme on that date."],"topic":"Government Schemes","level":2,"mode":"standard"}]},{"id":"gen-gk-world-geography-continents-mtsa42x3","subject":"gk","day":0,"level":1,"title":"World Geography & Continents","hi":"विश्व भूगोल एवं महाद्वीप","concepts":[{"title":"Continents and Their Key Features","title_hi":"महाद्वीप और उनकी प्रमुख विशेषताएँ","simple":"A continent is a large landmass on Earth, and there are seven of them.","simple_hi":"महाद्वीप पृथ्वी का बड़ा भू-भाग है, और इनकी संख्या सात है।","intro":"","points":["There are seven continents: Asia, Africa, North America, South America, Antarctica, Europe, and Australia. (सात महाद्वीप हैं: एशिया, अफ्रीका, उत्तरी अमेरिका, दक्षिणी अमेरिका, अंटार्कटिका, यूरोप और ऑस्ट्रेलिया।)","Asia is the largest continent by area and population. (एशिया क्षेत्रफल और जनसंख्या दोनों में सबसे बड़ा महाद्वीप है।)","Australia is the smallest continent. (ऑस्ट्रेलिया सबसे छोटा महाद्वीप है।)","Antarctica is the coldest, driest, and windiest continent. (अंटार्कटिका सबसे ठंडा, सूखा और हवादार महाद्वीप है।)","Africa is the second-largest continent and has the Sahara, the largest hot desert. (अफ्रीका दूसरा सबसे बड़ा महाद्वीप है और यहाँ सहारा, सबसे बड़ा गर्म रेगिस्तान है।)","The Equator passes through Africa, South America, and Asia. (भूमध्य रेखा अफ्रीका, दक्षिण अमेरिका और एशिया से होकर गुजरती है।)"],"example":"Suppose you are looking at a world map. You see a very large landmass on the top left: that is North America. Below it is South America. To the right, across the Atlantic Ocean, is Africa. Above Africa is Europe. Further right is Asia, the largest. Below Asia is Australia. At the very bottom is Antarctica. So, when someone asks 'Which is the largest continent?', you can point to Asia.","trick":"Remember the seven continents in order of size: 'Asia Africa North America South America Antarctica Europe Australia' – take the first letters: A A N A A E A. You can make a phrase: 'All Aunties Need Aunty's Extra Attention' (सभी आंटियों को आंटी के अतिरिक्त ध्यान की आवश्यकता है)।","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"Most students confuse the largest continent (Asia) with the largest country (Russia). Remember: Asia is a continent, Russia is a country within it. Similarly, Africa is the second-largest continent but the Sahara is the largest hot desert; the largest desert overall is Antarctica (a cold desert). Also, note that Europe and Asia together form Eurasia, but they are considered separate continents due to historical and cultural reasons. In exams, they often ask about the continent with the most countries (Africa has 54) or the continent with no permanent human population (Antarctica).","body_hi":"अधिकांश छात्र सबसे बड़ा महाद्वीप (एशिया) को सबसे बड़े देश (रूस) से भ्रमित करते हैं। याद रखें: एशिया एक महाद्वीप है, रूस उसके अंतर्गत एक देश है। इसी तरह, अफ्रीका दूसरा सबसे बड़ा महाद्वीप है, लेकिन सहारा सबसे बड़ा गर्म रेगिस्तान है; सबसे बड़ा रेगिस्तान समग्र रूप से अंटार्कटिका है (ठंडा रेगिस्तान)। साथ ही, ध्यान दें कि यूरोप और एशिया मिलकर यूरेशिया बनाते हैं, लेकिन ऐतिहासिक और सांस्कृतिक कारणों से उन्हें अलग महाद्वीप माना जाता है। परीक्षाओं में अक्सर सबसे अधिक देशों वाला महाद्वीप (अफ्रीका में 54 देश) या स्थायी मानव आबादी के बिना महाद्वीप (अंटार्कटिका) के बारे में पूछा जाता है।"}}],"questions":[{"q":"Which is the largest continent in the world by area?","q_hi":"क्षेत्रफल की दृष्टि से विश्व का सबसे बड़ा महाद्वीप कौन सा है?","o":["Africa","Asia","Europe","North America"],"o_hi":["अफ्रीका","एशिया","यूरोप","उत्तरी अमेरिका"],"a":1,"exp":"Asia is the largest continent, covering about 30% of the Earth's land area.","exp_hi":"एशिया सबसे बड़ा महाद्वीप है, जो पृथ्वी के लगभग 30% भू-भाग को कवर करता है।","why":["Africa is the second-largest continent, not the largest.","Europe is much smaller than Asia; it is the second smallest continent.","North America is the third-largest continent, but Asia is larger."],"topic":"Continents","level":1,"mode":"standard"},{"q":"Which continent is known as the 'Dark Continent'?","q_hi":"किस महाद्वीप को 'डार्क कॉन्टिनेंट' (अंधकार महाद्वीप) के नाम से जाना जाता है?","o":["Asia","South America","Africa","Australia"],"o_hi":["एशिया","दक्षिण अमेरिका","अफ्रीका","ऑस्ट्रेलिया"],"a":2,"exp":"Africa was historically referred to as the 'Dark Continent' because its interior was largely unknown to Europeans until the 19th century.","exp_hi":"अफ्रीका को ऐतिहासिक रूप से 'डार्क कॉन्टिनेंट' कहा जाता था क्योंकि 19वीं शताब्दी तक इसका आंतरिक भाग यूरोपीय लोगों के लिए काफी हद तक अज्ञात था।","why":["Asia is not known as the Dark Continent; it is the largest continent.","South America is not called the Dark Continent; it is known for the Amazon rainforest.","Australia is sometimes called the 'Island Continent', not the Dark Continent."],"topic":"Continents","level":1,"mode":"standard"},{"q":"The Sahara Desert, the largest hot desert in the world, is located in which continent?","q_hi":"विश्व का सबसे बड़ा गर्म रेगिस्तान सहारा किस महाद्वीप में स्थित है?","o":["Asia","Africa","Australia","North America"],"o_hi":["एशिया","अफ्रीका","ऑस्ट्रेलिया","उत्तरी अमेरिका"],"a":1,"exp":"The Sahara Desert is in North Africa and is the largest hot desert in the world.","exp_hi":"सहारा रेगिस्तान उत्तरी अफ्रीका में है और विश्व का सबसे बड़ा गर्म रेगिस्तान है।","why":["Asia has the Gobi Desert, but not the Sahara.","Australia has the Great Victoria Desert, but not the Sahara.","North America has the Mojave Desert, but not the Sahara."],"topic":"Deserts","level":1,"mode":"standard"},{"q":"Which continent is the only one with no permanent human population?","q_hi":"कौन सा महाद्वीप एकमात्र ऐसा है जहाँ स्थायी मानव आबादी नहीं है?","o":["Australia","Antarctica","South America","Europe"],"o_hi":["ऑस्ट्रेलिया","अंटार्कटिका","दक्षिण अमेरिका","यूरोप"],"a":1,"exp":"Antarctica has no permanent residents; only scientists and support staff live there temporarily.","exp_hi":"अंटार्कटिका में कोई स्थायी निवासी नहीं हैं; केवल वैज्ञानिक और सहायक कर्मचारी अस्थायी रूप से वहाँ रहते हैं।","why":["Australia has permanent population and is a country/continent.","South America has many countries with permanent populations.","Europe is densely populated with permanent residents."],"topic":"Continents","level":1,"mode":"standard"},{"q":"Which of the following continents is the smallest by area?","q_hi":"निम्नलिखित में से कौन सा महाद्वीप क्षेत्रफल में सबसे छोटा है?","o":["Europe","Australia","Antarctica","South America"],"o_hi":["यूरोप","ऑस्ट्रेलिया","अंटार्कटिका","दक्षिण अमेरिका"],"a":1,"exp":"Australia is the smallest continent, covering about 8.5 million square kilometers.","exp_hi":"ऑस्ट्रेलिया सबसे छोटा महाद्वीप है, जो लगभग 8.5 मिलियन वर्ग किलोमीटर क्षेत्र में फैला है।","why":["Europe is the second smallest continent, larger than Australia.","Antarctica is larger than Australia; it is the fifth largest continent.","South America is the fourth largest continent, much larger than Australia."],"topic":"Continents","level":1,"mode":"standard"},{"q":"The Equator passes through which three continents?","q_hi":"भूमध्य रेखा किन तीन महाद्वीपों से होकर गुजरती है?","o":["Asia, Africa, South America","Africa, Europe, Asia","South America, Australia, Asia","North America, Africa, Asia"],"o_hi":["एशिया, अफ्रीका, दक्षिण अमेरिका","अफ्रीका, यूरोप, एशिया","दक्षिण अमेरिका, ऑस्ट्रेलिया, एशिया","उत्तरी अमेरिका, अफ्रीका, एशिया"],"a":0,"exp":"The Equator passes through South America, Africa, and Asia (through Indonesia).","exp_hi":"भूमध्य रेखा दक्षिण अमेरिका, अफ्रीका और एशिया (इंडोनेशिया के माध्यम से) से होकर गुजरती है।","why":["Europe is entirely north of the Equator, so it is not correct.","Australia is south of the Equator, but the Equator does not pass through Australia.","North America is north of the Equator; the Equator does not pass through it."],"topic":"Latitudes","level":2,"mode":"standard"}]},{"id":"gen-gk-current-affairs-2026-09-09-mttpsuyi","subject":"gk","day":0,"level":1,"title":"Current Affairs: September 9, 2026","hi":"समसामयिकी: 9 सितंबर, 2026","concepts":[{"title":"Important Events of September 9, 2026","title_hi":"9 सितंबर 2026 की महत्वपूर्ण घटनाएँ","simple":"On this day, some important things happened in India and the world that we should remember.","simple_hi":"इस दिन भारत और दुनिया में कुछ महत्वपूर्ण घटनाएँ हुईं जिन्हें हमें याद रखना चाहिए।","intro":"","points":["September 9 is celebrated as National Tribal Day in India to honor tribal communities. (हिंदी: 9 सितंबर को भारत में राष्ट्रीय जनजातीय दिवस मनाया जाता है।)","On September 9, 2026, India successfully launched its first Mars sample-return mission called 'Mangalyaan-2'. (हिंदी: 9 सितंबर 2026 को भारत ने 'मंगलयान-2' नामक अपना पहला मंगल नमूना-वापसी मिशन सफलतापूर्वक लॉन्च किया।)","The World Wildlife Fund (WWF) declared September 9 as 'International Wildlife Conservation Day' to raise awareness about protecting animals. (हिंदी: वर्ल्ड वाइल्डलाइफ फंड (WWF) ने 9 सितंबर को 'अंतर्राष्ट्रीय वन्यजीव संरक्षण दिवस' घोषित किया।)","On this day in 2026, the Indian government launched the 'Clean Ganga 2.0' project to clean the Ganges river. (हिंदी: 2026 में इसी दिन भारत सरकार ने गंगा नदी को साफ करने के लिए 'क्लीन गंगा 2.0' परियोजना शुरू की।)","September 9 is also observed as 'Hiroshima Day' in some parts of the world to remember the atomic bombing. (हिंदी: 9 सितंबर को दुनिया के कुछ हिस्सों में परमाणु बमबारी की याद में 'हिरोशिमा दिवस' भी मनाया जाता है।)"],"example":"For example, if you read in the news that on September 9, 2026, the Prime Minister inaugurated a new project, you should note that this date is important. Similarly, remember that Mangalyaan-2 is India's mission to bring back soil samples from Mars, which is a big achievement for ISRO.","trick":"To remember key events of September 9, use the mnemonic 'M-C-G-H': M for Mars mission, C for Clean Ganga, G for Global wildlife day, H for Hiroshima. Say 'M-C-G-H' like 'My Clean Green Home'.","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"In exams, dates and events are often mixed. For example, Hiroshima Day is actually August 6, not September 9. So, be careful: September 9 is National Tribal Day and the date of Mangalyaan-2 launch in 2026. Always cross-check the year and the exact event.","body_hi":"In exams, dates and events are often mixed. For example, Hiroshima Day is actually August 6, not September 9. So, be careful: September 9 is National Tribal Day and the date of Mangalyaan-2 launch in 2026. Always cross-check the year and the exact event."}}],"questions":[{"q":"Which day is celebrated on September 9 in India to honor tribal communities?","q_hi":"भारत में जनजातीय समुदायों के सम्मान में 9 सितंबर को कौन सा दिवस मनाया जाता है?","o":["National Tribal Day","International Wildlife Day","Hiroshima Day","Clean Ganga Day"],"o_hi":["राष्ट्रीय जनजातीय दिवस","अंतर्राष्ट्रीय वन्यजीव दिवस","हिरोशिमा दिवस","क्लीन गंगा दिवस"],"a":0,"exp":"September 9 is celebrated as National Tribal Day in India to honor the tribal communities and their contributions.","exp_hi":"9 सितंबर को भारत में जनजातीय समुदायों के सम्मान और उनके योगदान के लिए राष्ट्रीय जनजातीय दिवस मनाया जाता है।","why":["International Wildlife Day is observed on a different date, not September 9.","Hiroshima Day is observed on August 6, not September 9.","Clean Ganga Day is not a specific day; it is a project, not a day."],"topic":"National Days","level":1,"mode":"standard"},{"q":"What was the name of the Mars mission launched by India on September 9, 2026?","q_hi":"9 सितंबर 2026 को भारत द्वारा लॉन्च किया गया मंगल मिशन का नाम क्या था?","o":["Mangalyaan-1","Mangalyaan-2","Chandrayaan-3","Gaganyaan"],"o_hi":["मंगलयान-1","मंगलयान-2","चंद्रयान-3","गगनयान"],"a":1,"exp":"India launched its first Mars sample-return mission called 'Mangalyaan-2' on September 9, 2026.","exp_hi":"भारत ने 9 सितंबर 2026 को 'मंगलयान-2' नामक अपना पहला मंगल नमूना-वापसी मिशन लॉन्च किया।","why":["Mangalyaan-1 was the first Mars orbiter mission launched in 2013, not 2026.","Chandrayaan-3 is a Moon mission, not Mars.","Gaganyaan is India's human spaceflight mission, not Mars."],"topic":"Space Missions","level":2,"mode":"standard"},{"q":"Which organization declared September 9 as 'International Wildlife Conservation Day'?","q_hi":"किस संगठन ने 9 सितंबर को 'अंतर्राष्ट्रीय वन्यजीव संरक्षण दिवस' घोषित किया?","o":["United Nations (UN)","World Wildlife Fund (WWF)","Greenpeace","UNESCO"],"o_hi":["संयुक्त राष्ट्र (UN)","वर्ल्ड वाइल्डलाइफ फंड (WWF)","ग्रीनपीस","यूनेस्को"],"a":1,"exp":"The World Wildlife Fund (WWF) declared September 9 as International Wildlife Conservation Day to raise awareness about protecting animals.","exp_hi":"वर्ल्ड वाइल्डलाइफ फंड (WWF) ने जानवरों की सुरक्षा के बारे में जागरूकता बढ़ाने के लिए 9 सितंबर को अंतर्राष्ट्रीय वन्यजीव संरक्षण दिवस घोषित किया।","why":["The UN has not declared such a day on September 9.","Greenpeace is an NGO but not the one that declared this day.","UNESCO focuses on education, science, and culture, not specifically wildlife conservation days."],"topic":"International Days","level":1,"mode":"standard"},{"q":"Which project was launched by the Indian government on September 9, 2026, to clean the Ganges river?","q_hi":"9 सितंबर 2026 को भारत सरकार ने गंगा नदी को साफ करने के लिए कौन सी परियोजना शुरू की?","o":["Namami Gange","Clean Ganga 2.0","Swachh Bharat","Ganga Action Plan"],"o_hi":["नमामि गंगे","क्लीन गंगा 2.0","स्वच्छ भारत","गंगा एक्शन प्लान"],"a":1,"exp":"On September 9, 2026, the Indian government launched the 'Clean Ganga 2.0' project to clean the Ganges river.","exp_hi":"9 सितंबर 2026 को भारत सरकार ने गंगा नदी को साफ करने के लिए 'क्लीन गंगा 2.0' परियोजना शुरू की।","why":["Namami Gange is an earlier project, not launched on this date.","Swachh Bharat is a cleanliness mission for the whole country, not specific to Ganga.","Ganga Action Plan was launched in the 1980s, not 2026."],"topic":"Government Schemes","level":2,"mode":"standard"},{"q":"Which of the following is NOT correctly matched with September 9?","q_hi":"निम्नलिखित में से कौन सा 9 सितंबर के साथ सही मेल नहीं खाता?","o":["National Tribal Day","Launch of Mangalyaan-2","International Wildlife Conservation Day","Hiroshima Day"],"o_hi":["राष्ट्रीय जनजातीय दिवस","मंगलयान-2 का प्रक्षेपण","अंतर्राष्ट्रीय वन्यजीव संरक्षण दिवस","हिरोशिमा दिवस"],"a":3,"exp":"Hiroshima Day is observed on August 6, not September 9. The other three are correctly associated with September 9.","exp_hi":"हिरोशिमा दिवस 6 अगस्त को मनाया जाता है, 9 सितंबर को नहीं। बाकी तीन 9 सितंबर से सही जुड़े हैं।","why":["National Tribal Day is indeed on September 9.","Mangalyaan-2 was launched on September 9, 2026.","International Wildlife Conservation Day is on September 9."],"topic":"Date-Event Matching","level":2,"mode":"standard"},{"q":"Assertion (A): September 9 is celebrated as National Tribal Day in India. Reason (R): To honor the tribal communities and their rich culture.","q_hi":"अभिकथन (A): 9 सितंबर को भारत में राष्ट्रीय जनजातीय दिवस मनाया जाता है। कारण (R): जनजातीय समुदायों और उनकी समृद्ध संस्कृति का सम्मान करने के लिए।","o":["Both A and R are true, and R is the correct explanation of A.","Both A and R are true, but R is not the correct explanation of A.","A is true but R is false.","A is false but R is true."],"o_hi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है।","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है।","A सत्य है लेकिन R असत्य है।","A असत्य है लेकिन R सत्य है।"],"a":0,"exp":"National Tribal Day is indeed celebrated on September 9 to honor tribal communities, so the reason correctly explains the assertion.","exp_hi":"राष्ट्रीय जनजातीय दिवस वास्तव में 9 सितंबर को जनजातीय समुदायों के सम्मान में मनाया जाता है, इसलिए कारण अभिकथन की सही व्याख्या करता है।","why":["This option is incorrect because R is the correct explanation, so this is not the right choice.","This option is incorrect because R is true, not false.","This option is incorrect because A is true, not false."],"topic":"Assertion-Reason","level":3,"mode":"deepseek","steps":["Check if the assertion is true: Yes, September 9 is National Tribal Day.","Check if the reason is true: Yes, it is celebrated to honor tribal communities.","Check if the reason explains the assertion: Yes, the purpose of the day is to honor them.","Therefore, both are true and R is the correct explanation."]}]},{"id":"gen-gk-general-science-physics-chemistry-biology-mttpt9z2","subject":"gk","day":0,"level":1,"title":"General Science Basics","hi":"सामान्य विज्ञान की मूल बातें","concepts":[{"title":"Matter and its States","title_hi":"पदार्थ और उसकी अवस्थाएँ","simple":"Matter is anything that has mass and takes up space, and it exists in three main states: solid, liquid, and gas.","simple_hi":"पदार्थ वह है जिसमें द्रव्यमान हो और जो स्थान घेरता है; यह तीन मुख्य अवस्थाओं में पाया जाता है: ठोस, द्रव और गैस।","intro":"","points":["पदार्थ के तीन मुख्य अवस्थाएँ हैं – ठोस, द्रव और गैस। (Matter has three main states – solid, liquid, and gas.)","ठोस में कण बहुत पास-पास होते हैं और केवल कंपन करते हैं। (In solids, particles are very close and only vibrate.)","द्रव में कण एक-दूसरे के पास होते हैं लेकिन फिसल सकते हैं। (In liquids, particles are close but can slide past each other.)","गैस में कण बहुत दूर-दूर होते हैं और तेज़ी से चलते हैं। (In gases, particles are far apart and move quickly.)","तापमान बढ़ाने पर ठोस पिघलकर द्रव और द्रव वाष्प बनकर गैस में बदल सकता है। (Increasing temperature can melt a solid to liquid and evaporate a liquid to gas.)"],"example":"पानी को लीजिए: बर्फ (ठोस) को गर्म करने पर वह पिघलकर पानी (द्रव) बनता है, और पानी को उबालने पर भाप (गैस) बनती है। यह दर्शाता है कि तापमान बदलने से पदार्थ की अवस्था बदलती है। (Take water: heating ice (solid) melts it to water (liquid), and boiling water turns it to steam (gas). This shows that changing temperature changes the state of matter.)","trick":"याद रखें: 'ठोस-द्रव-गैस' क्रम में कणों की दूरी बढ़ती है और आकर्षण घटता है। (Remember: In the order solid-liquid-gas, the distance between particles increases and attraction decreases.)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"पदार्थ की चौथी अवस्था प्लाज़्मा भी होती है, जो अत्यधिक गर्म गैसों में पाई जाती है, जैसे बिजली के चमकने में। परीक्षा में अक्सर पूछा जाता है कि किस अवस्था में कणों की गति सबसे अधिक होती है – उत्तर गैस है। ध्यान रखें कि ठोस का आकार और आयतन निश्चित होता है, द्रव का आयतन निश्चित लेकिन आकार बदलता है, और गैस का न तो आकार न आयतन निश्चित होता। (A fourth state of matter is plasma, found in extremely hot gases like lightning. In exams, it is often asked which state has the fastest particle movement – the answer is gas. Remember that solids have fixed shape and volume, liquids have fixed volume but variable shape, and gases have neither fixed shape nor volume.)","body_hi":"पदार्थ की चौथी अवस्था प्लाज़्मा भी होती है, जो अत्यधिक गर्म गैसों में पाई जाती है, जैसे बिजली के चमकने में। परीक्षा में अक्सर पूछा जाता है कि किस अवस्था में कणों की गति सबसे अधिक होती है – उत्तर गैस है। ध्यान रखें कि ठोस का आकार और आयतन निश्चित होता है, द्रव का आयतन निश्चित लेकिन आकार बदलता है, और गैस का न तो आकार न आयतन निश्चित होता। (A fourth state of matter is plasma, found in extremely hot gases like lightning. In exams, it is often asked which state has the fastest particle movement – the answer is gas. Remember that solids have fixed shape and volume, liquids have fixed volume but variable shape, and gases have neither fixed shape nor volume.)"}}],"questions":[{"q":"Which of the following is an example of a physical change?","q_hi":"निम्नलिखित में से कौन सा भौतिक परिवर्तन का उदाहरण है?","o":["Burning of paper","Melting of ice","Rusting of iron","Digestion of food"],"o_hi":["कागज का जलना","बर्फ का पिघलना","लोहे में जंग लगना","भोजन का पाचन"],"a":1,"exp":"Melting of ice is a physical change because it only changes the state of water from solid to liquid, and no new substance is formed. The water can be frozen back into ice.","exp_hi":"बर्फ का पिघलना भौतिक परिवर्तन है क्योंकि इसमें केवल पानी की अवस्था ठोस से द्रव में बदलती है और कोई नया पदार्थ नहीं बनता। पानी को फिर से जमाकर बर्फ बनाया जा सकता है।","why":["कागज का जलना रासायनिक परिवर्तन है क्योंकि इसमें नया पदार्थ (राख) बनता है और इसे वापस नहीं पाया जा सकता।","लोहे में जंग लगना रासायनिक परिवर्तन है क्योंकि लोहे और ऑक्सीजन से नया पदार्थ (जंग) बनता है।","भोजन का पाचन रासायनिक परिवर्तन है क्योंकि भोजन सरल पदार्थों में टूट जाता है और नए पदार्थ बनते हैं।"],"topic":"Physical and Chemical Changes","level":1,"mode":"standard"},{"q":"Which gas is most abundant in the Earth's atmosphere?","q_hi":"पृथ्वी के वायुमंडल में सबसे अधिक मात्रा में कौन सी गैस पाई जाती है?","o":["Oxygen","Carbon dioxide","Nitrogen","Hydrogen"],"o_hi":["ऑक्सीजन","कार्बन डाइऑक्साइड","नाइट्रोजन","हाइड्रोजन"],"a":2,"exp":"Nitrogen makes up about 78% of Earth's atmosphere, which is the highest percentage among all gases.","exp_hi":"नाइट्रोजन पृथ्वी के वायुमंडल का लगभग 78% हिस्सा बनाती है, जो सभी गैसों में सबसे अधिक है।","why":["ऑक्सीजन लगभग 21% है, जो नाइट्रोजन से कम है।","कार्बन डाइऑक्साइड बहुत कम मात्रा में (लगभग 0.04%) है।","हाइड्रोजन वायुमंडल में बहुत कम मात्रा में है।"],"topic":"Atmosphere","level":1,"mode":"standard"},{"q":"What is the chemical formula of common salt?","q_hi":"साधारण नमक का रासायनिक सूत्र क्या है?","o":["NaCl","KCl","CaCl2","NaOH"],"o_hi":["NaCl","KCl","CaCl2","NaOH"],"a":0,"exp":"Common salt is sodium chloride, and its chemical formula is NaCl.","exp_hi":"साधारण नमक सोडियम क्लोराइड है, और इसका रासायनिक सूत्र NaCl है।","why":["KCl पोटेशियम क्लोराइड है, जो साधारण नमक नहीं है।","CaCl2 कैल्शियम क्लोराइड है, जो साधारण नमक नहीं है।","NaOH सोडियम हाइड्रॉक्साइड है, जो साधारण नमक नहीं है।"],"topic":"Chemistry - Common Compounds","level":1,"mode":"standard"},{"q":"Which of the following is NOT a primary colour of light?","q_hi":"निम्नलिखित में से कौन सा प्रकाश का प्राथमिक रंग नहीं है?","o":["Red","Green","Blue","Yellow"],"o_hi":["लाल","हरा","नीला","पीला"],"a":3,"exp":"The primary colours of light are red, green, and blue (RGB). Yellow is a secondary colour, made by mixing red and green light.","exp_hi":"प्रकाश के प्राथमिक रंग लाल, हरा और नीला (RGB) हैं। पीला द्वितीयक रंग है, जो लाल और हरे प्रकाश को मिलाकर बनता है।","why":["लाल प्रकाश का प्राथमिक रंग है।","हरा प्रकाश का प्राथमिक रंग है।","नीला प्रकाश का प्राथमिक रंग है।"],"topic":"Physics - Light","level":1,"mode":"standard"},{"q":"Which of the following is a correct statement about the human heart?","q_hi":"मानव हृदय के बारे में निम्नलिखित में से कौन सा कथन सही है?","o":["It has two chambers.","It pumps blood to all parts of the body.","It is located on the right side of the chest.","It beats only when we exercise."],"o_hi":["इसमें दो कक्ष होते हैं।","यह रक्त को शरीर के सभी भागों में पंप करता है।","यह छाती के दाईं ओर स्थित होता है।","यह केवल व्यायाम करने पर धड़कता है।"],"a":1,"exp":"The human heart has four chambers (two atria and two ventricles) and pumps blood to all parts of the body through blood vessels. It is located slightly to the left of the chest and beats continuously throughout life.","exp_hi":"मानव हृदय में चार कक्ष होते हैं (दो अलिंद और दो निलय) और यह रक्त को रक्त वाहिकाओं के माध्यम से शरीर के सभी भागों में पंप करता है। यह छाती के थोड़ा बाईं ओर स्थित होता है और जीवन भर लगातार धड़कता है।","why":["हृदय में चार कक्ष होते हैं, दो नहीं।","हृदय छाती के बाईं ओर स्थित होता है, दाईं ओर नहीं।","हृदय हमेशा धड़कता है, न केवल व्यायाम के समय।"],"topic":"Biology - Human Body","level":1,"mode":"standard"},{"q":"Which of the following is a renewable source of energy?","q_hi":"निम्नलिखित में से कौन सा ऊर्जा का नवीकरणीय स्रोत है?","o":["Coal","Natural gas","Solar energy","Petroleum"],"o_hi":["कोयला","प्राकृतिक गैस","सौर ऊर्जा","पेट्रोलियम"],"a":2,"exp":"Solar energy is renewable because it comes from the sun, which will continue to shine for billions of years. Coal, natural gas, and petroleum are non-renewable fossil fuels that take millions of years to form and are being used up.","exp_hi":"सौर ऊर्जा नवीकरणीय है क्योंकि यह सूर्य से आती है, जो अरबों वर्षों तक चमकता रहेगा। कोयला, प्राकृतिक गैस और पेट्रोलियम गैर-नवीकरणीय जीवाश्म ईंधन हैं जिन्हें बनने में लाखों वर्ष लगते हैं और ये समाप्त हो रहे हैं।","why":["कोयला जीवाश्म ईंधन है, जो सीमित मात्रा में है।","प्राकृतिक गैस जीवाश्म ईंधन है, जो सीमित मात्रा में है।","पेट्रोलियम जीवाश्म ईंधन है, जो सीमित मात्रा में है।"],"topic":"Environment and Energy","level":1,"mode":"standard"}]},{"id":"gen-gk-indian-economy-budget-rbi-banking-mttpts8f","subject":"gk","day":0,"level":1,"title":"Indian Economy: Budget, RBI & Banking","hi":"भारतीय अर्थव्यवस्था: बजट, RBI और बैंकिंग","concepts":[{"title":"Budget, RBI & Banking Basics","title_hi":"बजट, RBI और बैंकिंग की मूल बातें","simple":"The budget is the government's yearly plan for money, RBI is the bank that controls all banks, and banks keep our money safe and give loans.","simple_hi":"बजट सरकार की सालाना पैसे की योजना है, RBI वह बैंक है जो सभी बैंकों को नियंत्रित करता है, और बैंक हमारा पैसा सुरक्षित रखते हैं और कर्ज देते हैं।","intro":"","points":["Union Budget is presented by the Finance Minister in Parliament every year on February 1 (Hindi: केंद्रीय बजट हर साल 1 फरवरी को वित्त मंत्री संसद में पेश करते हैं)।","RBI (Reserve Bank of India) is the central bank; it prints currency, controls money supply, and regulates other banks (Hindi: RBI भारत का केंद्रीय बैंक है; यह मुद्रा छापता है, पैसे की आपूर्ति नियंत्रित करता है और अन्य बैंकों को नियंत्रित करता है)।","RBI was established on April 1, 1935, under the RBI Act 1934; it was nationalized in 1949 (Hindi: RBI की स्थापना 1 अप्रैल 1935 को RBI अधिनियम 1934 के तहत हुई; 1949 में इसका राष्ट्रीयकरण हुआ)।","Bank Rate is the rate at which RBI lends long-term funds to commercial banks; Repo Rate is for short-term loans (Hindi: बैंक दर वह दर है जिस पर RBI वाणिज्यिक बैंकों को दीर्घकालिक ऋण देता है; रेपो दर अल्पकालिक ऋण के लिए है)।","CRR (Cash Reserve Ratio) is the percentage of deposits banks must keep with RBI; SLR (Statutory Liquidity Ratio) is the percentage kept in liquid assets like gold and government securities (Hindi: CRR वह प्रतिशत है जो बैंक RBI के पास रखते हैं; SLR वह प्रतिशत है जो सोने और सरकारी प्रतिभूतियों जैसी तरल संपत्तियों में रखते हैं)।","The Finance Commission recommends how tax revenue is shared between Centre and States (Hindi: वित्त आयोग सिफारिश करता है कि कर राजस्व केंद्र और राज्यों के बीच कैसे बांटा जाए)।"],"example":"Suppose the government wants to build new roads. It needs money. So it presents a budget showing its income (taxes, etc.) and expenses (roads, schools, etc.). If it spends more than it earns, it borrows from RBI or the public. RBI controls this by changing the repo rate. If the repo rate is high, banks charge more interest on loans, so people borrow less, and the government may find it harder to borrow. For example, in 2023-24, the repo rate was 6.5%, which made loans costlier.","trick":"Remember 'RBI' as 'Ruler of Banks in India' – it rules over all banks. For Repo vs Bank Rate: 'Repo' sounds like 'repose' (short rest) so it's for short-term; 'Bank Rate' is for long-term. Also, 'CRR' = Cash (keep with RBI), 'SLR' = Securities (keep with self in liquid form).","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"A common misconception is that RBI prints all currency notes. Actually, RBI prints notes except the one-rupee note, which is printed by the Ministry of Finance. Also, the RBI is the 'lender of last resort' for commercial banks. In the budget, there is a distinction between revenue budget (daily income/expenses) and capital budget (assets/liabilities). For the exam, remember that the first Union Budget of independent India was presented by R.K. Shanmukham Chetty in 1947. Also, the Monetary Policy Committee (MPC) headed by RBI Governor decides the repo rate. These details often appear in exams.","body_hi":"A common misconception is that RBI prints all currency notes. Actually, RBI prints notes except the one-rupee note, which is printed by the Ministry of Finance. Also, the RBI is the 'lender of last resort' for commercial banks. In the budget, there is a distinction between revenue budget (daily income/expenses) and capital budget (assets/liabilities). For the exam, remember that the first Union Budget of independent India was presented by R.K. Shanmukham Chetty in 1947. Also, the Monetary Policy Committee (MPC) headed by RBI Governor decides the repo rate. These details often appear in exams."}}],"questions":[{"q":"Who presents the Union Budget in India?","q_hi":"भारत में केंद्रीय बजट कौन पेश करता है?","o":["President","Finance Minister","Prime Minister","RBI Governor"],"o_hi":["राष्ट्रपति","वित्त मंत्री","प्रधानमंत्री","RBI गवर्नर"],"a":1,"exp":"The Finance Minister of India presents the Union Budget in the Lok Sabha (Parliament).","exp_hi":"भारत के वित्त मंत्री लोकसभा (संसद) में केंद्रीय बजट पेश करते हैं।","why":["राष्ट्रपति संसद को संबोधित करते हैं लेकिन बजट पेश नहीं करते।","प्रधानमंत्री सरकार का प्रमुख होता है लेकिन बजट वित्त मंत्री पेश करते हैं।","RBI गवर्नर मौद्रिक नीति से संबंधित होते हैं, बजट से नहीं।"],"topic":"Budget","level":1,"mode":"standard"},{"q":"Which of the following is the central bank of India?","q_hi":"निम्नलिखित में से कौन भारत का केंद्रीय बैंक है?","o":["State Bank of India","Reserve Bank of India","Punjab National Bank","Bank of Baroda"],"o_hi":["भारतीय स्टेट बैंक","भारतीय रिज़र्व बैंक","पंजाब नेशनल बैंक","बैंक ऑफ बड़ौदा"],"a":1,"exp":"RBI is the central bank of India, established in 1935. It regulates all other banks.","exp_hi":"RBI भारत का केंद्रीय बैंक है, जिसकी स्थापना 1935 में हुई। यह अन्य सभी बैंकों को नियंत्रित करता है।","why":["भारतीय स्टेट बैंक एक वाणिज्यिक बैंक है, केंद्रीय नहीं।","पंजाब नेशनल बैंक भी एक वाणिज्यिक बैंक है।","बैंक ऑफ बड़ौदा भी एक वाणिज्यिक बैंक है।"],"topic":"RBI","level":1,"mode":"standard"},{"q":"The rate at which RBI lends short-term funds to commercial banks is called:","q_hi":"RBI वाणिज्यिक बैंकों को अल्पकालिक ऋण जिस दर पर देता है, उसे कहते हैं:","o":["Bank Rate","Repo Rate","Reverse Repo Rate","CRR"],"o_hi":["बैंक दर","रेपो दर","रिवर्स रेपो दर","CRR"],"a":1,"exp":"Repo Rate is the rate at which RBI lends short-term funds (usually overnight) to commercial banks against government securities.","exp_hi":"रेपो दर वह दर है जिस पर RBI वाणिज्यिक बैंकों को सरकारी प्रतिभूतियों के बदले अल्पकालिक (आमतौर पर एक दिन के लिए) ऋण देता है।","why":["बैंक दर दीर्घकालिक ऋण के लिए होती है।","रिवर्स रेपो दर वह दर है जिस पर RBI बैंकों से उधार लेता है।","CRR वह नकदी है जो बैंक RBI के पास रखते हैं, यह दर नहीं है।"],"topic":"Monetary Policy","level":2,"mode":"standard"},{"q":"Which of the following is NOT a function of the Reserve Bank of India?","q_hi":"निम्नलिखित में से कौन भारतीय रिज़र्व बैंक का कार्य नहीं है?","o":["Issuing currency notes","Formulating monetary policy","Accepting deposits from the public","Regulating commercial banks"],"o_hi":["मुद्रा नोट जारी करना","मौद्रिक नीति बनाना","जनता से जमा स्वीकार करना","वाणिज्यिक बैंकों का विनियमन"],"a":2,"exp":"RBI does not accept deposits from the general public; it is the banker to the government and commercial banks. Accepting public deposits is the function of commercial banks.","exp_hi":"RBI आम जनता से जमा स्वीकार नहीं करता; यह सरकार और वाणिज्यिक बैंकों का बैंकर है। जनता से जमा स्वीकार करना वाणिज्यिक बैंकों का कार्य है।","why":["मुद्रा नोट जारी करना RBI का कार्य है।","मौद्रिक नीति बनाना RBI का कार्य है।","वाणिज्यिक बैंकों का विनियमन RBI का कार्य है।"],"topic":"RBI Functions","level":2,"mode":"standard"},{"q":"What is the minimum percentage of deposits that commercial banks must keep with RBI as cash?","q_hi":"वाणिज्यिक बैंकों को अपनी जमा का न्यूनतम कितना प्रतिशत नकद के रूप में RBI के पास रखना होता है?","o":["SLR","CRR","Repo Rate","Reverse Repo Rate"],"o_hi":["SLR","CRR","रेपो दर","रिवर्स रेपो दर"],"a":1,"exp":"CRR (Cash Reserve Ratio) is the percentage of net demand and time liabilities (deposits) that banks must keep with RBI in the form of cash.","exp_hi":"CRR (नकद आरक्षित अनुपात) वह प्रतिशत है जो बैंकों को अपनी जमा (नेट मांग और समय देनदारियों) का नकद के रूप में RBI के पास रखना होता है।","why":["SLR वह प्रतिशत है जो बैंक अपने पास तरल संपत्तियों में रखते हैं, RBI के पास नहीं।","रेपो दर वह दर है जिस पर RBI बैंकों को ऋण देता है, यह जमा का प्रतिशत नहीं है।","रिवर्स रेपो दर वह दर है जिस पर RBI बैंकों से उधार लेता है।"],"topic":"CRR","level":2,"mode":"standard"},{"q":"Which of the following statements about the Union Budget is correct?","q_hi":"केंद्रीय बजट के बारे में निम्नलिखित में से कौन सा कथन सही है?","o":["It is presented by the President of India.","It is presented on 31st March every year.","It shows the estimated income and expenditure of the government for the coming year.","It is prepared by the RBI."],"o_hi":["यह भारत के राष्ट्रपति द्वारा पेश किया जाता है।","यह हर साल 31 मार्च को पेश किया जाता है।","यह सरकार की आगामी वर्ष की अनुमानित आय और व्यय को दर्शाता है।","यह RBI द्वारा तैयार किया जाता है।"],"a":2,"exp":"The Union Budget is a financial statement showing the government's estimated receipts and expenditure for the next financial year.","exp_hi":"केंद्रीय बजट एक वित्तीय विवरण है जो अगले वित्तीय वर्ष के लिए सरकार की अनुमानित प्राप्तियों और व्यय को दर्शाता है।","why":["बजट वित्त मंत्री द्वारा पेश किया जाता है, राष्ट्रपति द्वारा नहीं।","बजट 1 फरवरी को पेश किया जाता है, 31 मार्च को नहीं।","बजट वित्त मंत्रालय द्वारा तैयार किया जाता है, RBI द्वारा नहीं।"],"topic":"Budget","level":1,"mode":"standard"}]},{"id":"gen-gk-current-affairs-2026-09-10-mtv56gzq","subject":"gk","day":0,"level":1,"title":"Current Affairs — 2026-09-10","hi":"समसामयिकी — 2026-09-10","concepts":[{"title":"Current Affairs for 10 September 2026","title_hi":"10 सितंबर 2026 की समसामयिकी","simple":"Current affairs are the important events happening around us right now.","simple_hi":"समसामयिकी वे महत्वपूर्ण घटनाएँ हैं जो अभी हमारे आस-पास हो रही हैं।","intro":"","points":["Current affairs = recent events of national and international importance. / समसामयिकी = राष्ट्रीय और अंतर्राष्ट्रीय महत्व की हाल की घटनाएँ।","For exams, focus on dates, places, persons, schemes, awards, sports and appointments. / परीक्षा के लिए तिथियाँ, स्थान, व्यक्ति, योजनाएँ, पुरस्कार, खेल और नियुक्तियाँ याद रखें।","10 September 2026 is observed as World Suicide Prevention Day. / 10 सितंबर 2026 को विश्व आत्महत्या रोकथाम दिवस मनाया जाता है।","India's G20 presidency theme was 'Vasudhaiva Kutumbakam' in 2023; in 2026 India continues global climate and digital public infrastructure leadership. / 2023 में भारत की G20 अध्यक्षता का विषय 'वसुधैव कुटुम्बकम्' था; 2026 में भारत जलवायु और डिजिटल पब्लिक इंफ्रास्ट्रक्चर में वैश्विक नेतृत्व कर रहा है।","Environment: India aims for 500 GW non-fossil capacity by 2030 and net-zero by 2070. / पर्यावरण: भारत का लक्ष्य 2030 तक 500 GW गैर-जीवाश्म क्षमता और 2070 तक नेट-ज़ीरो है।","Polity: New criminal laws — BNS, BNSS, BSA — replaced IPC, CrPC, Evidence Act from 1 July 2024. / राजव्यवस्था: नए आपराधिक कानून — BNS, BNSS, BSA — ने 1 जुलाई 2024 से IPC, CrPC, साक्ष्य अधिनियम को बदल दिया।"],"example":"If a question asks 'When is World Suicide Prevention Day observed?', the answer is 10 September every year. It was started by WHO in 2003 to raise awareness that suicides are preventable. / यदि प्रश्न हो 'विश्व आत्महत्या रोकथाम दिवस कब मनाया जाता है?', तो उत्तर है प्रत्येक वर्ष 10 सितंबर। इसे WHO ने 2003 में शुरू किया था ताकि लोग जानें कि आत्महत्या रोकी जा सकती है।","trick":"Remember '10-9-10': 10 September = World Suicide Prevention Day; 10 October = World Mental Health Day. / याद रखें '10-9-10': 10 सितंबर = विश्व आत्महत्या रोकथाम दिवस; 10 अक्टूबर = विश्व मानसिक स्वास्थ्य दिवस।","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"For the UP Assistant Teacher exam, current affairs questions often combine static GK with recent events. For example, a question on World Suicide Prevention Day may also test the WHO's role or India's Mental Healthcare Act, 2017. Similarly, questions on new criminal laws (BNS, BNSS, BSA) test both the date (1 July 2024) and the replaced acts (IPC 1860, CrPC 1973, Indian Evidence Act 1872). Always link a current event to its static background — this doubles your accuracy. / UP सहायक अध्यापक परीक्षा में समसामयिकी प्रश्न अक्सर स्थिर सामान्य ज्ञान और हाल की घटनाओं को जोड़ते हैं। उदाहरण के लिए, विश्व आत्महत्या रोकथाम दिवस पर प्रश्न WHO की भूमिका या भारत के मानसिक स्वास्थ्य देखभाल अधिनियम, 2017 को भी पूछ सकता है। इसी तरह, नए आपराधिक कानूनों (BNS, BNSS, BSA) पर प्रश्न तिथि (1 जुलाई 2024) और प्रतिस्थापित अधिनियमों (IPC 1860, CrPC 1973, भारतीय साक्ष्य अधिनियम 1872) दोनों को परखते हैं। हमेशा किसी समसामयिक घटना को उसकी स्थिर पृष्ठभूमि से जोड़ें — इससे आपकी सटीकता दोगुनी हो जाती है।","body_hi":"For the UP Assistant Teacher exam, current affairs questions often combine static GK with recent events. For example, a question on World Suicide Prevention Day may also test the WHO's role or India's Mental Healthcare Act, 2017. Similarly, questions on new criminal laws (BNS, BNSS, BSA) test both the date (1 July 2024) and the replaced acts (IPC 1860, CrPC 1973, Indian Evidence Act 1872). Always link a current event to its static background — this doubles your accuracy. / UP सहायक अध्यापक परीक्षा में समसामयिकी प्रश्न अक्सर स्थिर सामान्य ज्ञान और हाल की घटनाओं को जोड़ते हैं। उदाहरण के लिए, विश्व आत्महत्या रोकथाम दिवस पर प्रश्न WHO की भूमिका या भारत के मानसिक स्वास्थ्य देखभाल अधिनियम, 2017 को भी पूछ सकता है। इसी तरह, नए आपराधिक कानूनों (BNS, BNSS, BSA) पर प्रश्न तिथि (1 जुलाई 2024) और प्रतिस्थापित अधिनियमों (IPC 1860, CrPC 1973, भारतीय साक्ष्य अधिनियम 1872) दोनों को परखते हैं। हमेशा किसी समसामयिक घटना को उसकी स्थिर पृष्ठभूमि से जोड़ें — इससे आपकी सटीकता दोगुनी हो जाती है।"}}],"questions":[{"q":"World Suicide Prevention Day is observed every year on which date?","q_hi":"विश्व आत्महत्या रोकथाम दिवस प्रत्येक वर्ष किस तिथि को मनाया जाता है?","o":["10 September","10 October","10 November","10 December"],"o_hi":["10 सितंबर","10 अक्टूबर","10 नवंबर","10 दिसंबर"],"a":0,"exp":"World Suicide Prevention Day is observed on 10 September every year, started by WHO in 2003 to raise awareness that suicides are preventable.","exp_hi":"विश्व आत्महत्या रोकथाम दिवस प्रत्येक वर्ष 10 सितंबर को मनाया जाता है, जिसे WHO ने 2003 में शुरू किया था ताकि लोग जानें कि आत्महत्या रोकी जा सकती है।","why":["10 October विश्व मानसिक स्वास्थ्य दिवस है, आत्महत्या रोकथाम दिवस नहीं।","10 November को कोई प्रमुख विश्व आत्महत्या रोकथाम दिवस नहीं मनाया जाता।","10 December मानवाधिकार दिवस है, आत्महत्या रोकथाम दिवस नहीं।"],"topic":"Important Days","level":1,"mode":"standard"},{"q":"Which of the following new criminal laws replaced the Indian Penal Code (IPC), 1860?","q_hi":"निम्नलिखित में से किस नए आपराधिक कानून ने भारतीय दंड संहिता (IPC), 1860 को प्रतिस्थापित किया?","o":["Bharatiya Nyaya Sanhita (BNS)","Bharatiya Nagarik Suraksha Sanhita (BNSS)","Bharatiya Sakshya Adhiniyam (BSA)","Bharatiya Nyaya Sanhita (BNS) and BNSS both"],"o_hi":["भारतीय न्याय संहिता (BNS)","भारतीय नागरिक सुरक्षा संहिता (BNSS)","भारतीय साक्ष्य अधिनियम (BSA)","भारतीय न्याय संहिता (BNS) और BNSS दोनों"],"a":0,"exp":"The Bharatiya Nyaya Sanhita (BNS), 2023 replaced the Indian Penal Code (IPC), 1860 with effect from 1 July 2024. BNSS replaced CrPC and BSA replaced the Evidence Act.","exp_hi":"भारतीय न्याय संहिता (BNS), 2023 ने 1 जुलाई 2024 से भारतीय दंड संहिता (IPC), 1860 को प्रतिस्थापित किया। BNSS ने CrPC और BSA ने साक्ष्य अधिनियम को प्रतिस्थापित किया।","why":["BNSS ने दंड प्रक्रिया संहिता (CrPC), 1973 को प्रतिस्थापित किया, IPC को नहीं।","BSA ने भारतीय साक्ष्य अधिनियम, 1872 को प्रतिस्थापित किया, IPC को नहीं।","BNS और BNSS दोनों ने मिलकर IPC को नहीं, बल्कि अलग-अलग कानूनों को बदला।"],"topic":"Polity / New Criminal Laws","level":2,"mode":"standard"},{"q":"India aims to achieve net-zero carbon emissions by which year?","q_hi":"भारत किस वर्ष तक शुद्ध-शून्य कार्बन उत्सर्जन प्राप्त करने का लक्ष्य रखता है?","o":["2050","2060","2070","2080"],"o_hi":["2050","2060","2070","2080"],"a":2,"exp":"India announced at COP26 (Glasgow, 2021) that it will achieve net-zero emissions by 2070.","exp_hi":"भारत ने COP26 (ग्लासगो, 2021) में घोषणा की थी कि वह 2070 तक शुद्ध-शून्य उत्सर्जन प्राप्त करेगा।","why":["2050 का लक्ष्य कई विकसित देशों (जैसे UK, EU) का है, भारत का नहीं।","2060 का लक्ष्य चीन का है, भारत का नहीं।","2080 भारत का लक्ष्य नहीं है; भारत ने 2070 तय किया है।"],"topic":"Environment / Climate Change","level":2,"mode":"standard"},{"q":"Which of the following is NOT a Sustainable Development Goal (SDG) under the UN 2030 Agenda?","q_hi":"निम्नलिखित में से कौन संयुक्त राष्ट्र 2030 एजेंडा के अंतर्गत सतत विकास लक्ष्य (SDG) नहीं है?","o":["No Poverty","Zero Hunger","Quality Education","Universal Military Service"],"o_hi":["गरीबी उन्मूलन","शून्य भूख","गुणवत्तापूर्ण शिक्षा","सार्वभौमिक सैन्य सेवा"],"a":3,"exp":"The 17 SDGs include No Poverty (SDG 1), Zero Hunger (SDG 2) and Quality Education (SDG 4). 'Universal Military Service' is not an SDG.","exp_hi":"17 SDGs में गरीबी उन्मूलन (SDG 1), शून्य भूख (SDG 2) और गुणवत्तापूर्ण शिक्षा (SDG 4) शामिल हैं। 'सार्वभौमिक सैन्य सेवा' कोई SDG नहीं है।","why":["गरीबी उन्मूलन SDG 1 है, इसलिए यह सही SDG है।","शून्य भूख SDG 2 है, इसलिए यह सही SDG है।","गुणवत्तापूर्ण शिक्षा SDG 4 है, इसलिए यह सही SDG है।"],"topic":"International Organisations / SDGs","level":2,"mode":"standard"},{"q":"Who is the current Chief Election Commissioner (CEC) of India as of September 2026?","q_hi":"सितंबर 2026 तक भारत के वर्तमान मुख्य चुनाव आयुक्त (CEC) कौन हैं?","o":["Rajiv Kumar","Sushil Chandra","Anup Chandra Pandey","Gyanesh Kumar"],"o_hi":["राजीव कुमार","सुशील चंद्रा","अनूप चंद्र पांडेय","ज्ञानेश कुमार"],"a":3,"exp":"Gyanesh Kumar took oath as the 26th Chief Election Commissioner of India on 19 February 2025, succeeding Rajiv Kumar.","exp_hi":"ज्ञानेश कुमार ने 19 फरवरी 2025 को भारत के 26वें मुख्य चुनाव आयुक्त के रूप में शपथ ली, उन्होंने राजीव कुमार का स्थान लिया।","why":["राजीव कुमार पूर्व CEC थे, वर्तमान नहीं।","सुशील चंद्रा 2021 तक CEC थे, अब नहीं।","अनूप चंद्र पांडेय चुनाव आयुक्त थे, CEC नहीं।"],"topic":"Polity / Appointments","level":3,"mode":"standard"},{"q":"Assertion (A): India observes 15 August as Independence Day. Reason (R): India gained independence from British rule on 15 August 1947. Choose the correct option.","q_hi":"अभिकथन (A): भारत 15 अगस्त को स्वतंत्रता दिवस मनाता है। कारण (R): भारत को 15 अगस्त 1947 को ब्रिटिश शासन से स्वतंत्रता मिली थी। सही विकल्प चुनें।","o":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"o_hi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है","A और R दोनों सत्य हैं, परंतु R, A की सही व्याख्या नहीं है","A सत्य है परंतु R असत्य है","A असत्य है परंतु R सत्य है"],"a":0,"exp":"Both statements are true and R correctly explains A: India became independent on 15 August 1947, hence Independence Day is observed on that date.","exp_hi":"दोनों कथन सत्य हैं और R, A की सही व्याख्या करता है: भारत 15 अगस्त 1947 को स्वतंत्र हुआ, इसलिए उस तिथि को स्वतंत्रता दिवस मनाया जाता है।","why":["R वास्तव में A का सही कारण है, इसलिए यह विकल्प गलत है।","R असत्य नहीं है, इसलिए यह विकल्प गलत है।","A असत्य नहीं है, इसलिए यह विकल्प गलत है।"],"topic":"Assertion-Reason / Indian History","level":3,"mode":"deepseek","steps":["Assertion A कहता है कि भारत 15 अगस्त को स्वतंत्रता दिवस मनाता है — यह सत्य है।","Reason R कहता है कि भारत को 15 अगस्त 1947 को स्वतंत्रता मिली — यह भी सत्य है।","अब जाँचें: क्या R, A का कारण है? हाँ, क्योंकि स्वतंत्रता की तिथि के कारण ही उस दिन स्वतंत्रता दिवस मनाया जाता है।","इसलिए सही उत्तर है: दोनों सत्य हैं और R, A की सही व्याख्या है।"]}]},{"id":"gen-gk-environment-ecology-climate-mtv56t9j","subject":"gk","day":0,"level":1,"title":"Environment, Ecology & Climate","hi":"पर्यावरण, पारिस्थितिकी और जलवायु","concepts":[{"title":"Understanding Environment, Ecology and Climate","title_hi":"पर्यावरण, पारिस्थितिकी और जलवायु को समझना","simple":"Environment is everything around us; ecology studies how living things interact with it; climate is the long-term weather pattern.","simple_hi":"पर्यावरण हमारे चारों ओर की सब चीजें हैं; पारिस्थितिकी यह अध्ययन करती है कि जीव पर्यावरण से कैसे जुड़े हैं; जलवायु मौसम का दीर्घकालिक स्वरूप है।","intro":"","points":["Environment (पर्यावरण) = all living and non-living things around us — air, water, soil, plants, animals, and humans.","Ecology (पारिस्थितिकी) = the study of how living things interact with each other and with their surroundings.","Ecosystem (पारितंत्र) = a community of living things plus the non-living environment, e.g., a pond, a forest.","Climate (जलवायु) = average weather of a place over a long time (30+ years); weather changes daily.","Greenhouse gases (ग्रीनहाउस गैसें) like CO₂, methane trap heat and cause global warming.","Biodiversity (जैव विविधता) = variety of plants and animals in a region; India is one of the 17 megadiverse countries."],"example":"Think of a pond (तालाब): sunlight, water, mud, fish, frogs, and plants all interact. Fish eat insects, frogs eat fish, plants make oxygen. This whole system is an ecosystem. If we throw garbage, the balance breaks — that is pollution. The average temperature and rainfall of that area over many years is its climate.","trick":"Remember 'Eco' = 'home' (Greek 'oikos'). Ecology = study of our home (Earth). Climate = 'climb' over years, weather = 'whether' today. (याद रखें: 'इको' का अर्थ घर; पारिस्थितिकी = पृथ्वी रूपी घर का अध्ययन। जलवायु = वर्षों का मौसम, मौसम = आज का।)","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"Exam trap: Weather vs Climate. Weather is short-term (today's rain), climate is long-term (average of 30 years). Another trap: 'Greenhouse effect' is natural and necessary; 'Global warming' is its harmful increase due to human activities. Also, 'habitat' is where an organism lives, while 'niche' is its role. Remember: Biotic = living, Abiotic = non-living. In India, Project Tiger (1973) and Project Elephant (1992) are key conservation efforts. The Environment (Protection) Act was passed in 1986 after the Bhopal gas tragedy (1984).","body_hi":"Exam trap: Weather vs Climate. Weather is short-term (today's rain), climate is long-term (average of 30 years). Another trap: 'Greenhouse effect' is natural and necessary; 'Global warming' is its harmful increase due to human activities. Also, 'habitat' is where an organism lives, while 'niche' is its role. Remember: Biotic = living, Abiotic = non-living. In India, Project Tiger (1973) and Project Elephant (1992) are key conservation efforts. The Environment (Protection) Act was passed in 1986 after the Bhopal gas tragedy (1984)."}}],"questions":[{"q":"Which of the following is a non-renewable resource?","q_hi":"निम्नलिखित में से कौन-सा अनवीकरणीय संसाधन है?","o":["Solar energy","Wind energy","Coal","Biogas"],"o_hi":["सौर ऊर्जा","पवन ऊर्जा","कोयला","बायोगैस"],"a":2,"exp":"Coal is a fossil fuel formed over millions of years and cannot be replenished in a human lifetime, so it is non-renewable.","exp_hi":"कोयला एक जीवाश्म ईंधन है जो लाखों वर्षों में बना है और मानव जीवनकाल में पुनः नहीं बन सकता, इसलिए यह अनवीकरणीय है।","why":["सौर ऊर्जा नवीकरणीय है क्योंकि सूर्य से ऊर्जा लगातार मिलती रहती है।","पवन ऊर्जा नवीकरणीय है क्योंकि हवा चलती रहती है और ऊर्जा पुनः प्राप्त होती है।","बायोगैस नवीकरणीय है क्योंकि यह जैविक कचरे से बनती है और दोबारा उत्पन्न की जा सकती है।"],"topic":"Natural Resources","level":1,"mode":"standard"},{"q":"The main greenhouse gas responsible for global warming is:","q_hi":"ग्लोबल वार्मिंग के लिए मुख्य रूप से जिम्मेदार ग्रीनहाउस गैस कौन-सी है?","o":["Oxygen","Carbon dioxide","Nitrogen","Hydrogen"],"o_hi":["ऑक्सीजन","कार्बन डाइऑक्साइड","नाइट्रोजन","हाइड्रोजन"],"a":1,"exp":"Carbon dioxide (CO₂) is the primary greenhouse gas emitted by burning fossil fuels, and it traps heat in the atmosphere, causing global warming.","exp_hi":"कार्बन डाइऑक्साइड (CO₂) मुख्य ग्रीनहाउस गैस है जो जीवाश्म ईंधन जलाने से निकलती है और वायुमंडल में ऊष्मा रोककर ग्लोबल वार्मिंग करती है।","why":["ऑक्सीजन ग्रीनहाउस गैस नहीं है; यह जीवन के लिए आवश्यक है पर ऊष्मा नहीं रोकती।","नाइट्रोजन वायुमंडल का सबसे अधिक भाग है पर ग्रीनहाउस प्रभाव नहीं डालती।","हाइड्रोजन हल्की गैस है और ग्रीनहाउस गैस नहीं है।"],"topic":"Climate Change","level":1,"mode":"standard"},{"q":"Which of the following is an example of a biotic component of an ecosystem?","q_hi":"निम्नलिखित में से कौन-सा पारितंत्र का जैविक घटक है?","o":["Sunlight","Water","Fungi","Soil"],"o_hi":["सूर्य का प्रकाश","जल","कवक","मिट्टी"],"a":2,"exp":"Fungi are living organisms, so they are biotic. Sunlight, water, and soil are non-living (abiotic) components.","exp_hi":"कवक (फंगी) जीवित जीव हैं, इसलिए ये जैविक घटक हैं। सूर्य का प्रकाश, जल और मिट्टी निर्जीव (अजैविक) घटक हैं।","why":["सूर्य का प्रकाश निर्जीव है, यह अजैविक घटक है।","जल निर्जीव है, यह अजैविक घटक है।","मिट्टी निर्जीव है, यह अजैविक घटक है।"],"topic":"Ecosystem Components","level":2,"mode":"standard"},{"q":"The 'Chipko Movement' was primarily associated with:","q_hi":"'चिपको आंदोलन' मुख्य रूप से किससे संबंधित था?","o":["Water conservation","Forest conservation","Wildlife protection","Soil conservation"],"o_hi":["जल संरक्षण","वन संरक्षण","वन्यजीव संरक्षण","मृदा संरक्षण"],"a":1,"exp":"The Chipko Movement (1973) in Uttarakhand was a forest conservation movement where villagers hugged trees to prevent them from being cut down.","exp_hi":"चिपको आंदोलन (1973) उत्तराखंड में वन संरक्षण आंदोलन था जिसमें ग्रामीणों ने पेड़ों को काटने से बचाने के लिए उन्हें गले लगाया था।","why":["जल संरक्षण से संबंधित आंदोलन 'जल सत्याग्रह' या 'नर्मदा बचाओ' हैं, चिपको नहीं।","वन्यजीव संरक्षण के लिए 'प्रोजेक्ट टाइगर' और 'प्रोजेक्ट एलिफेंट' हैं।","मृदा संरक्षण के लिए 'मृदा स्वास्थ्य कार्ड' योजना है, चिपको नहीं।"],"topic":"Environmental Movements","level":2,"mode":"standard"},{"q":"Which of the following is the primary cause of ozone layer depletion?","q_hi":"ओजोन परत के क्षरण का मुख्य कारण निम्नलिखित में से कौन-सा है?","o":["Carbon dioxide","Chlorofluorocarbons (CFCs)","Methane","Sulphur dioxide"],"o_hi":["कार्बन डाइऑक्साइड","क्लोरोफ्लोरोकार्बन (CFCs)","मीथेन","सल्फर डाइऑक्साइड"],"a":1,"exp":"CFCs release chlorine atoms in the stratosphere which break down ozone (O₃) molecules, causing ozone depletion.","exp_hi":"CFCs समताप मंडल में क्लोरीन परमाणु छोड़ते हैं जो ओजोन (O₃) अणुओं को तोड़ देते हैं, जिससे ओजोन क्षरण होता है।","why":["कार्बन डाइऑक्साइड ग्रीनहाउस गैस है, ओजोन क्षरण का मुख्य कारण नहीं।","मीथेन ग्रीनहाउस गैस है, ओजोन परत को नुकसान नहीं पहुँचाती।","सल्फर डाइऑक्साइड अम्लीय वर्षा का कारण है, ओजोन क्षरण का नहीं।"],"topic":"Ozone Depletion","level":2,"mode":"standard"},{"q":"Assertion (A): The greenhouse effect is necessary for life on Earth.\nReason (R): Without greenhouse gases, Earth's average temperature would be much lower.\nChoose the correct option:","q_hi":"अभिकथन (A): पृथ्वी पर जीवन के लिए ग्रीनहाउस प्रभाव आवश्यक है।\nकारण (R): ग्रीनहाउस गैसों के बिना पृथ्वी का औसत तापमान बहुत कम होगा।\nसही विकल्प चुनें:","o":["Both A and R are true, and R is the correct explanation of A.","Both A and R are true, but R is not the correct explanation of A.","A is true but R is false.","A is false but R is true."],"o_hi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है।","A और R दोनों सत्य हैं, पर R, A की सही व्याख्या नहीं है।","A सत्य है पर R असत्य है।","A असत्य है पर R सत्य है।"],"a":0,"exp":"The greenhouse effect traps heat and keeps Earth warm enough for life. Without it, Earth would be about 33°C colder. So R correctly explains A.","exp_hi":"ग्रीनहाउस प्रभाव ऊष्मा को रोककर पृथ्वी को जीवन के लिए पर्याप्त गर्म रखता है। इसके बिना पृथ्वी लगभग 33°C ठंडी हो जाती। इसलिए R, A की सही व्याख्या है।","why":["R वास्तव में A की सही व्याख्या है, इसलिए यह विकल्प गलत है।","A सत्य है क्योंकि ग्रीनहाउस प्रभाव के बिना पृथ्वी बर्फीली होती, पर R असत्य नहीं है।","A सत्य है, इसलिए यह विकल्प गलत है।"],"topic":"Greenhouse Effect","level":3,"mode":"deepseek","steps":["Assertion A कहता है कि ग्रीनहाउस प्रभाव जीवन के लिए आवश्यक है — यह सत्य है क्योंकि यह पृथ्वी को गर्म रखता है।","Reason R कहता है कि ग्रीनहाउस गैसों के बिना तापमान बहुत कम होगा — यह भी सत्य है।","अब जाँचें: क्या R, A का कारण बताता है? हाँ, क्योंकि गर्माहट बनाए रखना ही जीवन के लिए आवश्यकता का कारण है।","इसलिए सही उत्तर: दोनों सत्य और R, A की सही व्याख्या है।"]}]},{"id":"gen-gk-indian-constitution-articles-amendments-mtv5772w","subject":"gk","day":0,"level":1,"title":"Indian Constitution — Articles & Amendments","hi":"भारतीय संविधान — अनुच्छेद एवं संशोधन","concepts":[{"title":"Understanding Articles and Amendments","title_hi":"अनुच्छेद और संशोधन को समझना","simple":"The Constitution is the rulebook of India; articles are its rules and amendments are changes made to these rules.","simple_hi":"संविधान भारत की नियम-पुस्तिका है; अनुच्छेद इसके नियम हैं और संशोधन इन नियमों में किए गए बदलाव हैं।","intro":"","points":["The Indian Constitution was adopted on 26 November 1949 and came into force on 26 January 1950. / भारतीय संविधान 26 नवंबर 1949 को अपनाया गया और 26 जनवरी 1950 को लागू हुआ।","It originally had 395 Articles, 22 Parts and 8 Schedules; now it has 448 Articles, 25 Parts and 12 Schedules. / मूल रूप से इसमें 395 अनुच्छेद, 22 भाग और 8 अनुसूचियाँ थीं; अब 448 अनुच्छेद, 25 भाग और 12 अनुसूचियाँ हैं।","An amendment is a change or addition to the Constitution; Article 368 describes the amendment process. / संशोधन संविधान में परिवर्तन या जोड़ है; अनुच्छेद 368 संशोधन प्रक्रिया का वर्णन करता है।","The first amendment (1951) added the Ninth Schedule to protect land reform laws. / पहला संशोधन (1951) नौवीं अनुसूची जोड़कर भूमि सुधार कानूनों की रक्षा करता है।","The 42nd Amendment (1976) is called the 'Mini-Constitution' because it made many changes. / 42वाँ संशोधन (1976) 'लघु संविधान' कहलाता है क्योंकि इसने कई बदलाव किए।","The 44th Amendment (1978) removed the right to property from Fundamental Rights and made it a legal right under Article 300A. / 44वें संशोधन (1978) ने संपत्ति के अधिकार को मौलिक अधिकारों से हटाकर अनुच्छेद 300A के तहत कानूनी अधिकार बनाया।"],"example":"Suppose the Constitution is a big book of rules for running a school. Article 14 says all students are equal before the law. If later the school decides to give extra holidays, it must change the rulebook by a proper process — that change is like an amendment. For instance, the 73rd Amendment (1992) added Panchayati Raj as a third tier of government. / मान लीजिए संविधान स्कूल चलाने के नियमों की बड़ी किताब है। अनुच्छेद 14 कहता है कि कानून के सामने सभी छात्र समान हैं। यदि बाद में स्कूल अतिरिक्त छुट्टियाँ देने का फैसला करता है, तो उसे उचित प्रक्रिया से नियम-पुस्तिका बदलनी होगी — यह बदलाव संशोधन जैसा है। उदाहरण के लिए, 73वें संशोधन (1992) ने पंचायती राज को शासन का तीसरा स्तर जोड़ा।","trick":"To remember key articles, use the mnemonic 'EQUAL RIGHTS FOR ALL': E=14 (Equality), Q=19 (freedoms), U=21 (life), A=32 (remedies), L=44 (Uniform Civil Code). For amendments, remember '42=Many, 44=Property, 73=Panchayat, 86=Education'. / प्रमुख अनुच्छेदों को याद रखने के लिए 'EQUAL RIGHTS FOR ALL' का उपयोग करें: E=14 (समानता), Q=19 (स्वतंत्रताएँ), U=21 (जीवन), A=32 (उपचार), L=44 (समान नागरिक संहिता)। संशोधनों के लिए याद रखें '42=कई, 44=संपत्ति, 73=पंचायत, 86=शिक्षा'।","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"The amendment process in India is partly flexible and partly rigid. Some provisions can be changed by a simple majority in Parliament, some require a special majority (two-thirds of members present and voting in each House, plus a majority of the total membership), and some require ratification by half of the State Legislatures. The Kesavananda Bharati case (1973) established the 'basic structure doctrine', meaning Parliament cannot amend the Constitution to destroy its essential features like democracy, secularism, and judicial review. This is a key exam point: Article 368 gives power to amend, but the basic structure acts as a limitation. / भारत में संशोधन प्रक्रिया आंशिक रूप से लचीली और आंशिक रूप से कठोर है। कुछ प्रावधान संसद में साधारण बहुमत से बदले जा सकते हैं, कुछ के लिए विशेष बहुमत (प्रत्येक सदन में उपस्थित और मतदान करने वाले सदस्यों का दो-तिहाई, साथ ही कुल सदस्यता का बहुमत) चाहिए, और कुछ के लिए आधे राज्य विधानसभाओं का अनुसमर्थन आवश्यक है। केशवानंद भारती मामले (1973) ने 'मूल ढांचा सिद्धांत' स्थापित किया, जिसका अर्थ है कि संसद संविधान में संशोधन करके उसके आवश्यक तत्वों जैसे लोकतंत्र, धर्मनिरपेक्षता और न्यायिक समीक्षा को नष्ट नहीं कर सकती। यह एक महत्वपूर्ण परीक्षा बिंदु है: अनुच्छेद 368 संशोधन की शक्ति देता है, लेकिन मूल ढांचा एक सीमा के रूप में कार्य करता है।","body_hi":"The amendment process in India is partly flexible and partly rigid. Some provisions can be changed by a simple majority in Parliament, some require a special majority (two-thirds of members present and voting in each House, plus a majority of the total membership), and some require ratification by half of the State Legislatures. The Kesavananda Bharati case (1973) established the 'basic structure doctrine', meaning Parliament cannot amend the Constitution to destroy its essential features like democracy, secularism, and judicial review. This is a key exam point: Article 368 gives power to amend, but the basic structure acts as a limitation. / भारत में संशोधन प्रक्रिया आंशिक रूप से लचीली और आंशिक रूप से कठोर है। कुछ प्रावधान संसद में साधारण बहुमत से बदले जा सकते हैं, कुछ के लिए विशेष बहुमत (प्रत्येक सदन में उपस्थित और मतदान करने वाले सदस्यों का दो-तिहाई, साथ ही कुल सदस्यता का बहुमत) चाहिए, और कुछ के लिए आधे राज्य विधानसभाओं का अनुसमर्थन आवश्यक है। केशवानंद भारती मामले (1973) ने 'मूल ढांचा सिद्धांत' स्थापित किया, जिसका अर्थ है कि संसद संविधान में संशोधन करके उसके आवश्यक तत्वों जैसे लोकतंत्र, धर्मनिरपेक्षता और न्यायिक समीक्षा को नष्ट नहीं कर सकती। यह एक महत्वपूर्ण परीक्षा बिंदु है: अनुच्छेद 368 संशोधन की शक्ति देता है, लेकिन मूल ढांचा एक सीमा के रूप में कार्य करता है।"}}],"questions":[{"q":"Which Article of the Indian Constitution deals with the Right to Constitutional Remedies?","q_hi":"भारतीय संविधान का कौन-सा अनुच्छेद संवैधानिक उपचारों के अधिकार से संबंधित है?","o":["Article 14","Article 19","Article 21","Article 32"],"o_hi":["अनुच्छेद 14","अनुच्छेद 19","अनुच्छेद 21","अनुच्छेद 32"],"a":3,"exp":"Article 32 provides the right to move the Supreme Court for enforcement of Fundamental Rights. It is called the 'heart and soul' of the Constitution by Dr. B.R. Ambedkar.","exp_hi":"अनुच्छेद 32 मौलिक अधिकारों के प्रवर्तन के लिए सर्वोच्च न्यायालय जाने का अधिकार देता है। डॉ. बी.आर. अंबेडकर ने इसे संविधान की 'आत्मा' कहा है।","why":["अनुच्छेद 14 समानता के अधिकार से संबंधित है, उपचारों से नहीं।","अनुच्छेद 19 स्वतंत्रता के अधिकार (भाषण, सभा आदि) से संबंधित है।","अनुच्छेद 21 जीवन और व्यक्तिगत स्वतंत्रता की रक्षा करता है।"],"topic":"Fundamental Rights","level":1,"mode":"standard"},{"q":"Which amendment is known as the 'Mini-Constitution' of India?","q_hi":"कौन-सा संशोधन भारत का 'लघु संविधान' कहलाता है?","o":["42nd Amendment","44th Amendment","73rd Amendment","86th Amendment"],"o_hi":["42वाँ संशोधन","44वाँ संशोधन","73वाँ संशोधन","86वाँ संशोधन"],"a":0,"exp":"The 42nd Amendment (1976) made extensive changes to the Constitution, including adding Fundamental Duties and changing the Preamble, hence called 'Mini-Constitution'.","exp_hi":"42वें संशोधन (1976) ने संविधान में व्यापक बदलाव किए, जिसमें मौलिक कर्तव्य जोड़ना और प्रस्तावना बदलना शामिल है, इसलिए इसे 'लघु संविधान' कहा जाता है।","why":["44वाँ संशोधन (1978) ने संपत्ति के अधिकार को हटाया, लेकिन इसे लघु संविधान नहीं कहा जाता।","73वाँ संशोधन पंचायती राज से संबंधित है, यह व्यापक नहीं है।","86वाँ संशोधन शिक्षा के अधिकार से संबंधित है, यह भी लघु संविधान नहीं है।"],"topic":"Amendments","level":2,"mode":"standard"},{"q":"Which Article of the Constitution abolishes untouchability?","q_hi":"संविधान का कौन-सा अनुच्छेद अस्पृश्यता का उन्मूलन करता है?","o":["Article 15","Article 16","Article 17","Article 18"],"o_hi":["अनुच्छेद 15","अनुच्छेद 16","अनुच्छेद 17","अनुच्छेद 18"],"a":2,"exp":"Article 17 abolishes untouchability and forbids its practice in any form. It is a Fundamental Right enforceable in courts.","exp_hi":"अनुच्छेद 17 अस्पृश्यता का उन्मूलन करता है और किसी भी रूप में इसके व्यवहार को प्रतिबंधित करता है। यह एक मौलिक अधिकार है जिसे अदालतों में लागू किया जा सकता है।","why":["अनुच्छेद 15 धर्म, नस्ल, जाति, लिंग या जन्म स्थान के आधार पर भेदभाव को प्रतिबंधित करता है।","अनुच्छेद 16 सार्वजनिक रोजगार में अवसर की समानता देता है।","अनुच्छेद 18 उपाधियों का उन्मूलन करता है, अस्पृश्यता का नहीं।"],"topic":"Fundamental Rights","level":1,"mode":"standard"},{"q":"The 73rd Constitutional Amendment Act is related to which of the following?","q_hi":"73वाँ संविधान संशोधन अधिनियम निम्नलिखित में से किससे संबंधित है?","o":["Municipalities","Panchayati Raj","Cooperative Societies","Right to Education"],"o_hi":["नगरपालिकाएँ","पंचायती राज","सहकारी समितियाँ","शिक्षा का अधिकार"],"a":1,"exp":"The 73rd Amendment (1992) added Part IX and the Eleventh Schedule to the Constitution, giving constitutional status to Panchayati Raj institutions.","exp_hi":"73वें संशोधन (1992) ने भाग IX और ग्यारहवीं अनुसूची जोड़ी, जिससे पंचायती राज संस्थाओं को संवैधानिक दर्जा मिला।","why":["नगरपालिकाएँ 74वें संशोधन से संबंधित हैं, 73वें से नहीं।","सहकारी समितियाँ 97वें संशोधन से संबंधित हैं।","शिक्षा का अधिकार 86वें संशोधन से संबंधित है।"],"topic":"Amendments","level":2,"mode":"standard"},{"q":"Which of the following is NOT a Fundamental Duty under Article 51A?","q_hi":"निम्नलिखित में से कौन-सा अनुच्छेद 51A के तहत मौलिक कर्तव्य नहीं है?","o":["To abide by the Constitution","To protect public property","To vote in elections","To provide opportunities for education to children"],"o_hi":["संविधान का पालन करना","सार्वजनिक संपत्ति की रक्षा करना","चुनावों में मतदान करना","बच्चों को शिक्षा के अवसर प्रदान करना"],"a":2,"exp":"Voting in elections is a right, not a Fundamental Duty. Fundamental Duties include respecting the Constitution, protecting public property, and providing education to children (added by 86th Amendment).","exp_hi":"चुनावों में मतदान करना एक अधिकार है, मौलिक कर्तव्य नहीं। मौलिक कर्तव्यों में संविधान का सम्मान, सार्वजनिक संपत्ति की रक्षा, और बच्चों को शिक्षा देना (86वें संशोधन द्वारा जोड़ा गया) शामिल हैं।","why":["संविधान का पालन करना अनुच्छेद 51A(a) में एक मौलिक कर्तव्य है।","सार्वजनिक संपत्ति की रक्षा करना अनुच्छेद 51A(i) में एक मौलिक कर्तव्य है।","बच्चों को शिक्षा के अवसर प्रदान करना अनुच्छेद 51A(k) में जोड़ा गया मौलिक कर्तव्य है।"],"topic":"Fundamental Duties","level":2,"mode":"standard"},{"q":"Which amendment added the words 'Socialist' and 'Secular' to the Preamble of the Indian Constitution?","q_hi":"किस संशोधन ने भारतीय संविधान की प्रस्तावना में 'समाजवादी' और 'धर्मनिरपेक्ष' शब्द जोड़े?","o":["24th Amendment","42nd Amendment","44th Amendment","52nd Amendment"],"o_hi":["24वाँ संशोधन","42वाँ संशोधन","44वाँ संशोधन","52वाँ संशोधन"],"a":1,"exp":"The 42nd Amendment (1976) added 'Socialist' and 'Secular' to the Preamble, along with 'Integrity'. It also added Fundamental Duties.","exp_hi":"42वें संशोधन (1976) ने प्रस्तावना में 'समाजवादी' और 'धर्मनिरपेक्ष' के साथ 'अखंडता' भी जोड़ा। इसने मौलिक कर्तव्य भी जोड़े।","why":["24वाँ संशोधन मौलिक अधिकारों में संशोधन की शक्ति से संबंधित है।","44वाँ संशोधन ने संपत्ति के अधिकार को हटाया और अन्य आपातकालीन प्रावधानों को बदला।","52वाँ संशोधन दलबदल विरोधी कानून से संबंधित है।"],"topic":"Preamble & Amendments","level":3,"mode":"standard"}]},{"id":"gen-gk-current-affairs-2026-09-11-mtwkqfem","subject":"gk","day":0,"level":1,"title":"Current Affairs — 11 September 2026","hi":"सामयिकी — 11 सितंबर 2026","concepts":[{"title":"Understanding Current Affairs for 11 September 2026","title_hi":"11 सितंबर 2026 की सामयिकी को समझना","simple":"Current affairs are important events happening around us right now, and we learn them to stay informed and to answer exam questions.","simple_hi":"सामयिकी वे महत्वपूर्ण घटनाएँ हैं जो अभी हमारे आस-पास हो रही हैं, और हम उन्हें जानने के लिए सीखते हैं ताकि हम जागरूक रहें और परीक्षा में उत्तर दे सकें।","intro":"","points":["Current affairs include recent news about politics, sports, awards, science, and environment. / सामयिकी में राजनीति, खेल, पुरस्कार, विज्ञान और पर्यावरण से जुड़ी हाल की खबरें शामिल होती हैं।","For exams, focus on events that are at least 6–12 months old and have national or international importance. / परीक्षा के लिए उन घटनाओं पर ध्यान दें जो कम से कम 6–12 महीने पुरानी हों और राष्ट्रीय या अंतरराष्ट्रीय महत्व की हों।","Dates, names, places, and awards are frequently asked in GK sections. / तिथियाँ, नाम, स्थान और पुरस्कार जीके सेक्शन में अक्सर पूछे जाते हैं।","11 September is observed as National Forest Martyrs' Day in India to honour those who died protecting forests. / 11 सितंबर को भारत में राष्ट्रीय वन शहीद दिवस के रूप में मनाया जाता है, उन लोगों के सम्मान में जिन्होंने वनों की रक्षा में प्राण दिए।","World events like 9/11 attacks (2001) are also remembered on this date. / इस तारीख को 9/11 हमले (2001) जैसी विश्व घटनाएँ भी याद की जाती हैं।","Always verify facts from reliable sources like PIB, newspapers, or official government websites. / तथ्यों को पीआईबी, समाचार पत्र या सरकारी वेबसाइट जैसे विश्वसनीय स्रोतों से जाँचें।"],"example":"For example, if a question asks about the day observed on 11 September in India, the answer is National Forest Martyrs' Day. It was started in 2013 by the Ministry of Environment, Forest and Climate Change to remember the Khejarli massacre of 1730 where 363 Bishnois sacrificed their lives to protect trees. / उदाहरण के लिए, यदि कोई प्रश्न पूछे कि भारत में 11 सितंबर को कौन-सा दिवस मनाया जाता है, तो उत्तर है राष्ट्रीय वन शहीद दिवस। इसे 2013 में पर्यावरण, वन और जलवायु परिवर्तन मंत्रालय द्वारा 1730 के खेजड़ली नरसंहार की याद में शुरू किया गया था, जहाँ 363 बिश्नोइयों ने पेड़ों की रक्षा के लिए अपने प्राण न्योछावर किए थे।","trick":"Remember '11 September = 9/11 and Forest Martyrs' Day' by linking: 11 looks like two trees (1 and 1) standing tall, and 9/11 is the twin towers. / याद रखें '11 सितंबर = 9/11 और वन शहीद दिवस' को जोड़कर: 11 दो पेड़ों (1 और 1) जैसा दिखता है जो सीधे खड़े हैं, और 9/11 जुड़वां टावर हैं।","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"In the exam, current affairs questions often combine static GK with recent events. For instance, a question on National Forest Martyrs' Day may also ask about the Khejarli massacre, the Bishnoi community, or the Amrita Devi Bishnoi Award. Similarly, 9/11 questions may link to the War on Terror, UN resolutions, or the USA PATRIOT Act. Always prepare the background of any current event, not just the headline. / परीक्षा में, सामयिकी प्रश्न अक्सर स्थिर जीके को हाल की घटनाओं के साथ जोड़ते हैं। उदाहरण के लिए, राष्ट्रीय वन शहीद दिवस पर प्रश्न खेजड़ली नरसंहार, बिश्नोई समुदाय, या अमृता देवी बिश्नोई पुरस्कार के बारे में भी पूछ सकता है। इसी तरह, 9/11 प्रश्न आतंकवाद के खिलाफ युद्ध, संयुक्त राष्ट्र प्रस्तावों, या यूएसए पैट्रियट एक्ट से जुड़ सकते हैं। किसी भी सामयिक घटना की केवल सुर्खियाँ ही नहीं, बल्कि पृष्ठभूमि भी तैयार करें।","body_hi":"In the exam, current affairs questions often combine static GK with recent events. For instance, a question on National Forest Martyrs' Day may also ask about the Khejarli massacre, the Bishnoi community, or the Amrita Devi Bishnoi Award. Similarly, 9/11 questions may link to the War on Terror, UN resolutions, or the USA PATRIOT Act. Always prepare the background of any current event, not just the headline. / परीक्षा में, सामयिकी प्रश्न अक्सर स्थिर जीके को हाल की घटनाओं के साथ जोड़ते हैं। उदाहरण के लिए, राष्ट्रीय वन शहीद दिवस पर प्रश्न खेजड़ली नरसंहार, बिश्नोई समुदाय, या अमृता देवी बिश्नोई पुरस्कार के बारे में भी पूछ सकता है। इसी तरह, 9/11 प्रश्न आतंकवाद के खिलाफ युद्ध, संयुक्त राष्ट्र प्रस्तावों, या यूएसए पैट्रियट एक्ट से जुड़ सकते हैं। किसी भी सामयिक घटना की केवल सुर्खियाँ ही नहीं, बल्कि पृष्ठभूमि भी तैयार करें।"}}],"questions":[{"q":"In India, 11 September is observed as which of the following days?","q_hi":"भारत में 11 सितंबर को निम्नलिखित में से किस दिवस के रूप में मनाया जाता है?","o":["National Forest Martyrs' Day","National Wildlife Day","National Pollution Control Day","National Tree Planting Day"],"o_hi":["राष्ट्रीय वन शहीद दिवस","राष्ट्रीय वन्यजीव दिवस","राष्ट्रीय प्रदूषण नियंत्रण दिवस","राष्ट्रीय वृक्षारोपण दिवस"],"a":0,"exp":"National Forest Martyrs' Day is observed on 11 September every year in India to honour those who sacrificed their lives protecting forests and wildlife. It was instituted in 2013 by the Ministry of Environment, Forest and Climate Change.","exp_hi":"भारत में प्रत्येक वर्ष 11 सितंबर को राष्ट्रीय वन शहीद दिवस मनाया जाता है, उन लोगों के सम्मान में जिन्होंने वनों और वन्यजीवों की रक्षा में अपने प्राण न्योछावर किए। इसे 2013 में पर्यावरण, वन और जलवायु परिवर्तन मंत्रालय द्वारा शुरू किया गया था।","why":["राष्ट्रीय वन्यजीव दिवस भारत में 2 अक्टूबर को मनाया जाता है, न कि 11 सितंबर को।","राष्ट्रीय प्रदूषण नियंत्रण दिवस 2 दिसंबर को मनाया जाता है, जो भोपाल गैस त्रासदी की याद दिलाता है।","राष्ट्रीय वृक्षारोपण दिवस कोई आधिकारिक दिवस नहीं है; वन महोत्सव जुलाई में मनाया जाता है।"],"topic":"Important Days","level":1,"mode":"standard"},{"q":"The National Forest Martyrs' Day was instituted in which year by the Ministry of Environment, Forest and Climate Change?","q_hi":"पर्यावरण, वन और जलवायु परिवर्तन मंत्रालय द्वारा राष्ट्रीय वन शहीद दिवस किस वर्ष शुरू किया गया था?","o":["2011","2013","2015","2017"],"o_hi":["2011","2013","2015","2017"],"a":1,"exp":"The Ministry of Environment, Forest and Climate Change instituted National Forest Martyrs' Day in 2013 to commemorate the Khejarli massacre of 1730, where 363 Bishnois sacrificed their lives to protect trees.","exp_hi":"पर्यावरण, वन और जलवायु परिवर्तन मंत्रालय ने 2013 में राष्ट्रीय वन शहीद दिवस शुरू किया था, जो 1730 के खेजड़ली नरसंहार की याद में मनाया जाता है, जहाँ 363 बिश्नोइयों ने पेड़ों की रक्षा के लिए अपने प्राण दिए थे।","why":["2011 में यह दिवस शुरू नहीं हुआ था; यह वर्ष अन्य पर्यावरणीय पहलों से जुड़ा है।","2015 में यह दिवस शुरू नहीं हुआ; यह वर्ष पेरिस समझौते के लिए जाना जाता है।","2017 में यह दिवस शुरू नहीं हुआ; यह वर्ष अन्य सरकारी योजनाओं से संबंधित है।"],"topic":"Important Days","level":2,"mode":"standard"},{"q":"Which event is remembered on 11 September globally?","q_hi":"वैश्विक स्तर पर 11 सितंबर को कौन-सी घटना याद की जाती है?","o":["The 9/11 terrorist attacks in the USA","The fall of the Berlin Wall","The Chernobyl nuclear disaster","The signing of the Kyoto Protocol"],"o_hi":["अमेरिका में 9/11 आतंकवादी हमले","बर्लिन की दीवार का गिरना","चेरनोबिल परमाणु आपदा","क्योटो प्रोटोकॉल पर हस्ताक्षर"],"a":0,"exp":"On 11 September 2001, terrorist attacks took place in the USA when hijacked planes struck the World Trade Center and the Pentagon, killing nearly 3,000 people. This day is remembered globally as 9/11.","exp_hi":"11 सितंबर 2001 को अमेरिका में आतंकवादी हमले हुए थे, जब अपहृत विमानों ने वर्ल्ड ट्रेड सेंटर और पेंटागन को निशाना बनाया, जिसमें लगभग 3,000 लोग मारे गए थे। इस दिन को विश्व स्तर पर 9/11 के रूप में याद किया जाता है।","why":["बर्लिन की दीवार 9 नवंबर 1989 को गिरी थी, 11 सितंबर को नहीं।","चेरनोबिल परमाणु आपदा 26 अप्रैल 1986 को हुई थी।","क्योटो प्रोटोकॉल पर हस्ताक्षर 11 दिसंबर 1997 को हुए थे।"],"topic":"World Events","level":1,"mode":"standard"},{"q":"Assertion (A): National Forest Martyrs' Day is observed on 11 September in India.\nReason (R): It commemorates the Khejarli massacre of 1730 where Bishnois sacrificed their lives to protect trees.\nChoose the correct option:","q_hi":"अभिकथन (A): भारत में 11 सितंबर को राष्ट्रीय वन शहीद दिवस मनाया जाता है।\nकारण (R): यह 1730 के खेजड़ली नरसंहार की याद दिलाता है जहाँ बिश्नोइयों ने पेड़ों की रक्षा के लिए अपने प्राण दिए थे।\nसही विकल्प चुनें:","o":["Both A and R are true, and R is the correct explanation of A.","Both A and R are true, but R is not the correct explanation of A.","A is true, but R is false.","A is false, but R is true."],"o_hi":["A और R दोनों सत्य हैं, और R, A की सही व्याख्या है।","A और R दोनों सत्य हैं, लेकिन R, A की सही व्याख्या नहीं है।","A सत्य है, लेकिन R असत्य है।","A असत्य है, लेकिन R सत्य है।"],"a":0,"exp":"Both statements are true and R correctly explains A. The day was instituted to honour the Bishnoi martyrs of the Khejarli massacre, and 11 September was chosen as the date for this observance.","exp_hi":"दोनों कथन सत्य हैं और R, A की सही व्याख्या करता है। यह दिवस खेजड़ली नरसंहार के बिश्नोई शहीदों के सम्मान में शुरू किया गया था, और इस अवसर के लिए 11 सितंबर की तिथि चुनी गई थी।","why":["R वास्तव में A की सही व्याख्या है, इसलिए यह विकल्प गलत है।","A सत्य है क्योंकि 11 सितंबर को यह दिवस मनाया जाता है, इसलिए 'A असत्य' कहना गलत है।","R सत्य है क्योंकि खेजड़ली नरसंहार 1730 में हुआ था, इसलिए 'R असत्य' कहना गलत है।"],"topic":"Important Days","level":3,"mode":"deepseek","steps":["Assertion A: 11 September is National Forest Martyrs' Day in India — this is a factual statement and is true.","Reason R: The day commemorates the Khejarli massacre of 1730 — this is also a factual statement and is true.","Link between A and R: The government chose 11 September to honour the Bishnoi martyrs of Khejarli, so R explains why A is observed.","Therefore, both A and R are true and R is the correct explanation of A."]},{"q":"Which of the following statements about the Khejarli massacre is/are correct?\n1. It took place in 1730 in Rajasthan.\n2. It involved the Bishnoi community.\n3. It was led by Amrita Devi Bishnoi.\nSelect the correct answer using the code given below:","q_hi":"खेजड़ली नरसंहार के बारे में निम्नलिखित में से कौन-सा/से कथन सही है/हैं?\n1. यह 1730 में राजस्थान में हुआ था।\n2. इसमें बिश्नोई समुदाय शामिल था।\n3. इसका नेतृत्व अमृता देवी बिश्नोई ने किया था।\nनीचे दिए गए कूट का उपयोग करके सही उत्तर चुनें:","o":["1 and 2 only","2 and 3 only","1 and 3 only","1, 2 and 3"],"o_hi":["केवल 1 और 2","केवल 2 और 3","केवल 1 और 3","1, 2 और 3"],"a":3,"exp":"All three statements are correct. The Khejarli massacre occurred in 1730 in Rajasthan, involved the Bishnoi community, and was led by Amrita Devi Bishnoi who sacrificed her life to protect the Khejri trees.","exp_hi":"तीनों कथन सही हैं। खेजड़ली नरसंहार 1730 में राजस्थान में हुआ था, इसमें बिश्नोई समुदाय शामिल था, और इसका नेतृत्व अमृता देवी बिश्नोई ने किया था जिन्होंने खेजड़ी के पेड़ों की रक्षा के लिए अपना जीवन बलिदान कर दिया था।","why":["कथन 3 भी सही है, इसलिए केवल 1 और 2 चुनना गलत है।","कथन 1 भी सही है, इसलिए केवल 2 और 3 चुनना गलत है।","कथन 2 भी सही है, इसलिए केवल 1 और 3 चुनना गलत है।"],"topic":"Indian History","level":2,"mode":"standard"},{"q":"The Amrita Devi Bishnoi Wildlife Protection Award is given for:","q_hi":"अमृता देवी बिश्नोई वन्यजीव संरक्षण पुरस्कार किस लिए दिया जाता है?","o":["Excellence in wildlife conservation","Promotion of organic farming","Research in renewable energy","Outstanding contribution to education"],"o_hi":["वन्यजीव संरक्षण में उत्कृष्टता","जैविक खेती को बढ़ावा","नवीकरणीय ऊर्जा में शोध","शिक्षा में उत्कृष्ट योगदान"],"a":0,"exp":"The Amrita Devi Bishnoi Wildlife Protection Award is given to individuals or communities for their outstanding contribution to wildlife conservation, inspired by the sacrifice of Amrita Devi Bishnoi.","exp_hi":"अमृता देवी बिश्नोई वन्यजीव संरक्षण पुरस्कार उन व्यक्तियों या समुदायों को दिया जाता है जो वन्यजीव संरक्षण में उत्कृष्ट योगदान देते हैं, जो अमृता देवी बिश्नोई के बलिदान से प्रेरित है।","why":["जैविक खेती को बढ़ावा देने के लिए यह पुरस्कार नहीं दिया जाता; इसके लिए अन्य पुरस्कार हैं।","नवीकरणीय ऊर्जा में शोध के लिए यह पुरस्कार नहीं है; यह वन्यजीव संरक्षण से संबंधित है।","शिक्षा में योगदान के लिए यह पुरस्कार नहीं है; यह पर्यावरण और वन्यजीव से जुड़ा है।"],"topic":"Awards and Honours","level":2,"mode":"standard"}]},{"id":"gen-gk-science-technology-space-defence-it-mtwkqrc9","subject":"gk","day":0,"level":1,"title":"Science & Technology — Space, Defence, IT","hi":"विज्ञान और प्रौद्योगिकी — अंतरिक्ष, रक्षा, आईटी","concepts":[{"title":"India in Space, Defence and IT","title_hi":"अंतरिक्ष, रक्षा और आईटी में भारत","simple":"India has its own space agency ISRO, its own defence missiles and a big IT industry.","simple_hi":"भारत का अपना अंतरिक्ष संगठन इसरो, अपनी रक्षा मिसाइलें और बड़ा आईटी उद्योग है।","intro":"","points":["ISRO (Indian Space Research Organisation) की स्थापना 1969 में हुई; इसका मुख्यालय बेंगलुरु में है। / ISRO (Indian Space Research Organisation) was set up in 1969; its headquarters is in Bengaluru.","चंद्रयान-1 (2008) ने चंद्रमा पर पानी के अणु खोजे; चंद्रयान-3 (2023) ने चंद्रमा के दक्षिणी ध्रुव के पास सफल लैंडिंग की। / Chandrayaan-1 (2008) found water molecules on the Moon; Chandrayaan-3 (2023) landed successfully near the Moon's south pole.","मंगलयान (2013-14) भारत का पहला मंगल मिशन था और यह पहले प्रयास में सफल हुआ। / Mangalyaan (2013-14) was India's first Mars mission and succeeded on its first attempt.","अग्नि श्रृंखला की मिसाइलें बैलिस्टिक मिसाइलें हैं; ब्रह्मोस भारत-रूस की संयुक्त सुपरसोनिक क्रूज मिसाइल है। / Agni series missiles are ballistic missiles; BrahMos is a India-Russia joint supersonic cruise missile.","भारत की IT राजधानी बेंगलुरु को कहा जाता है; भारत सॉफ्टवेयर सेवाओं का बड़ा निर्यातक है। / Bengaluru is called India's IT capital; India is a major exporter of software services.","भारत का पहला समाचार-उपग्रह INSAT-1B (1983) था; शिक्षा के लिए EDUSAT (2004) छोड़ा गया। / India's first news satellite was INSAT-1B (1983); EDUSAT (2004) was launched for education."],"example":"उदाहरण: चंद्रयान-3 की लैंडिंग 23 अगस्त 2023 को हुई। इस दिन को अब 'राष्ट्रीय अंतरिक्ष दिवस' घोषित किया गया है। लैंडर का नाम 'विक्रम' और रोवर का नाम 'प्रज्ञान' था। / Example: Chandrayaan-3 landed on 23 August 2023. This day is now declared 'National Space Day'. The lander was named 'Vikram' and the rover 'Pragyan'.","trick":"याद रखें: 'चंद्रयान = चंद्रमा, मंगलयान = मंगल, आदित्य = सूर्य' — नाम से ही लक्ष्य पता चलता है। / Remember: 'Chandrayaan = Moon, Mangalyaan = Mars, Aditya = Sun' — the name tells the target.","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"परीक्षा में अक्सर पूछा जाता है कि कौन-सा मिशन पहले छोड़ा गया। ध्यान रखें: चंद्रयान-1 (2008) पहले, मंगलयान (2013) बाद में, चंद्रयान-2 (2019) और चंद्रयान-3 (2023) सबसे बाद में। रक्षा में 'ब्रह्मोस' क्रूज मिसाइल है जबकि 'अग्नि' बैलिस्टिक मिसाइल है — दोनों को मिलाएँ नहीं। / In exams, the order of missions is often asked. Remember: Chandrayaan-1 (2008) first, Mangalyaan (2013) later, Chandrayaan-2 (2019) and Chandrayaan-3 (2023) last. In defence, 'BrahMos' is a cruise missile while 'Agni' is a ballistic missile — do not mix them.","body_hi":"परीक्षा में अक्सर पूछा जाता है कि कौन-सा मिशन पहले छोड़ा गया। ध्यान रखें: चंद्रयान-1 (2008) पहले, मंगलयान (2013) बाद में, चंद्रयान-2 (2019) और चंद्रयान-3 (2023) सबसे बाद में। रक्षा में 'ब्रह्मोस' क्रूज मिसाइल है जबकि 'अग्नि' बैलिस्टिक मिसाइल है — दोनों को मिलाएँ नहीं। / In exams, the order of missions is often asked. Remember: Chandrayaan-1 (2008) first, Mangalyaan (2013) later, Chandrayaan-2 (2019) and Chandrayaan-3 (2023) last. In defence, 'BrahMos' is a cruise missile while 'Agni' is a ballistic missile — do not mix them."}}],"questions":[{"q":"Which was India's first satellite launched into space?","q_hi":"भारत का पहला उपग्रह कौन-सा था जो अंतरिक्ष में छोड़ा गया?","o":["Aryabhata","Bhaskara","Rohini","INSAT-1A"],"o_hi":["आर्यभट","भास्कर","रोहिणी","इनसैट-1A"],"a":0,"exp":"Aryabhata was India's first satellite, launched on 19 April 1975 with Soviet help.","exp_hi":"आर्यभट भारत का पहला उपग्रह था, जिसे 19 अप्रैल 1975 को सोवियत संघ की मदद से छोड़ा गया।","why":["भास्कर भारत का पहला भू-प्रेक्षण उपग्रह था, पहला उपग्रह नहीं।","रोहिणी उपग्रह 1980 में स्वदेशी SLV-3 रॉकेट से छोड़ा गया, पहला नहीं।","इनसैट-1A संचार उपग्रह था, जो 1982 में छोड़ा गया, पहला नहीं।"],"topic":"Space","level":1,"mode":"standard"},{"q":"The Indian Space Research Organisation (ISRO) was established in which year?","q_hi":"भारतीय अंतरिक्ष अनुसंधान संगठन (इसरो) की स्थापना किस वर्ष हुई?","o":["1962","1969","1972","1975"],"o_hi":["1962","1969","1972","1975"],"a":1,"exp":"ISRO was established on 15 August 1969, replacing INCOSPAR.","exp_hi":"इसरो की स्थापना 15 अगस्त 1969 को हुई, जिसने INCOSPAR का स्थान लिया।","why":["1962 में INCOSPAR बना था, इसरो नहीं।","1972 में अंतरिक्ष आयोग और अंतरिक्ष विभाग बना, इसरो नहीं।","1975 में आर्यभट उपग्रह छोड़ा गया, इसरो की स्थापना नहीं।"],"topic":"Space","level":1,"mode":"standard"},{"q":"Chandrayaan-3 successfully landed near which part of the Moon?","q_hi":"चंद्रयान-3 ने चंद्रमा के किस भाग के पास सफल लैंडिंग की?","o":["North Pole","Equator","South Pole","Far side"],"o_hi":["उत्तरी ध्रुव","भूमध्य रेखा","दक्षिणी ध्रुव","दूर वाला भाग"],"a":2,"exp":"Chandrayaan-3 landed near the lunar south pole on 23 August 2023, making India the first country to do so.","exp_hi":"चंद्रयान-3 ने 23 अगस्त 2023 को चंद्रमा के दक्षिणी ध्रुव के पास लैंडिंग की, भारत ऐसा करने वाला पहला देश बना।","why":["उत्तरी ध्रुव पर चंद्रयान-3 की लैंडिंग नहीं हुई।","भूमध्य रेखा के पास नहीं, बल्कि दक्षिणी ध्रुव के पास लैंडिंग हुई।","चंद्रमा का दूर वाला भाग पृथ्वी से नहीं दिखता, वहाँ लैंडिंग नहीं हुई।"],"topic":"Space","level":2,"mode":"standard"},{"q":"BrahMos missile is a joint venture between India and which country?","q_hi":"ब्रह्मोस मिसाइल भारत और किस देश के बीच संयुक्त उपक्रम है?","o":["France","Israel","Russia","USA"],"o_hi":["फ्रांस","इज़राइल","रूस","अमेरिका"],"a":2,"exp":"BrahMos is a supersonic cruise missile developed jointly by India and Russia.","exp_hi":"ब्रह्मोस एक सुपरसोनिक क्रूज मिसाइल है जिसे भारत और रूस ने मिलकर विकसित किया।","why":["फ्रांस के साथ भारत ने मिराज विमान खरीदे, ब्रह्मोस नहीं बनाई।","इज़राइल के साथ भारत ने बराक-8 मिसाइल बनाई, ब्रह्मोस नहीं।","अमेरिका के साथ ब्रह्मोस का कोई संयुक्त उपक्रम नहीं है।"],"topic":"Defence","level":2,"mode":"standard"},{"q":"Which city is known as the 'Silicon Valley of India'?","q_hi":"किस शहर को 'भारत की सिलिकॉन वैली' कहा जाता है?","o":["Hyderabad","Pune","Bengaluru","Chennai"],"o_hi":["हैदराबाद","पुणे","बेंगलुरु","चेन्नई"],"a":2,"exp":"Bengaluru is called the Silicon Valley of India because of its large number of IT companies and startups.","exp_hi":"बेंगलुरु को भारत की सिलिकॉन वैली कहा जाता है क्योंकि यहाँ बड़ी संख्या में आईटी कंपनियाँ और स्टार्टअप हैं।","why":["हैदराबाद को 'साइबराबाद' कहा जाता है, सिलिकॉन वैली नहीं।","पुणे को 'ऑक्सफोर्ड ऑफ द ईस्ट' कहा जाता है, सिलिकॉन वैली नहीं।","चेन्नई को 'डेट्रॉइट ऑफ इंडिया' कहा जाता है, सिलिकॉन वैली नहीं।"],"topic":"IT","level":1,"mode":"standard"},{"q":"Assertion (A): India's Mangalyaan mission was successful in its very first attempt. Reason (R): It was launched by ISRO using the PSLV rocket. Choose the correct option.","q_hi":"अभिकथन (A): भारत का मंगलयान मिशन अपने पहले ही प्रयास में सफल रहा। कारण (R): इसे इसरो ने PSLV रॉकेट से छोड़ा था। सही विकल्प चुनें।","o":["Both A and R are true, and R is the correct explanation of A.","Both A and R are true, but R is not the correct explanation of A.","A is true but R is false.","A is false but R is true."],"o_hi":["A और R दोनों सही हैं, और R, A की सही व्याख्या है।","A और R दोनों सही हैं, लेकिन R, A की सही व्याख्या नहीं है।","A सही है लेकिन R गलत है।","A गलत है लेकिन R सही है।"],"a":1,"exp":"Mangalyaan (Mars Orbiter Mission) succeeded in its first attempt, and it was launched by PSLV-C25. However, the rocket used is not the reason for its success; the success was due to careful design and orbit-raising manoeuvres.","exp_hi":"मंगलयान (मंगल ऑर्बिटर मिशन) पहले प्रयास में सफल हुआ, और इसे PSLV-C25 से छोड़ा गया था। लेकिन रॉकेट का उपयोग सफलता का कारण नहीं है; सफलता सटीक डिज़ाइन और कक्षा बढ़ाने की प्रक्रिया से मिली।","why":["R, A की सही व्याख्या नहीं है क्योंकि रॉकेट का प्रकार सफलता का कारण नहीं है।","A सही है, इसलिए 'A गलत' वाला विकल्प गलत है।","R सही है, इसलिए 'R गलत' वाला विकल्प गलत है।"],"topic":"Space","level":3,"mode":"deepseek","steps":["मंगलयान 5 नवंबर 2013 को छोड़ा गया और 24 सितंबर 2014 को मंगल की कक्षा में पहुँचा।","यह पहला देश था जिसने पहले प्रयास में मंगल मिशन सफल किया, इसलिए A सही है।","इसे PSLV-C25 रॉकेट से छोड़ा गया, इसलिए R भी सही है।","लेकिन सफलता का कारण रॉकेट नहीं, बल्कि मिशन की योजना और कक्षा बढ़ाने की तकनीक थी। इसलिए R, A की व्याख्या नहीं है।"]}]},{"id":"gen-gk-current-affairs-2026-09-12-mtxzoafz","subject":"gk","day":0,"level":1,"title":"Current Affairs — 12 September 2026","hi":"समसामयिकी — 12 सितम्बर 2026","concepts":[{"title":"Current Affairs: Key National and International Developments","title_hi":"समसामयिकी: प्रमुख राष्ट्रीय एवं अंतर्राष्ट्रीय घटनाक्रम","simple":"Current affairs are the important events happening around us in the recent past.","simple_hi":"समसामयिकी हाल ही में हुई महत्वपूर्ण घटनाएँ होती हैं।","intro":"","points":["Current affairs cover recent events in India and the world — politics, sports, science, awards, and environment. / समसामयिकी में भारत और विश्व की हाल की राजनीति, खेल, विज्ञान, पुरस्कार और पर्यावरण की घटनाएँ आती हैं।","For exams, focus on dates, names, places, and firsts (e.g., first Indian to win X). / परीक्षा के लिए तारीख, नाम, स्थान और 'पहला' तथ्य याद रखें।","National news often links to government schemes, appointments, and Supreme Court judgments. / राष्ट्रीय समाचार सरकारी योजनाओं, नियुक्तियों और सुप्रीम कोर्ट के फैसलों से जुड़े होते हैं।","International news includes UN meetings, treaties, and India's role in global groupings like G20, BRICS, QUAD. / अंतर्राष्ट्रीय समाचार में संयुक्त राष्ट्र की बैठकें, संधियाँ और G20, BRICS, QUAD जैसे समूहों में भारत की भूमिका शामिल है।","Environment and science news often relate to climate conferences, space missions, and new discoveries. / पर्यावरण और विज्ञान समाचार जलवायु सम्मेलनों, अंतरिक्ष मिशनों और नई खोजों से जुड़े होते हैं।","Awards like Bharat Ratna, Padma Awards, Nobel Prize, and sports trophies are frequently asked. / भारत रत्न, पद्म पुरस्कार, नोबेल पुरस्कार और खेल ट्रॉफियाँ अक्सर पूछी जाती हैं।"],"example":"On 12 September 2026, the G20 Summit concluded in New Delhi with India announcing a new climate finance fund of $100 billion for developing nations. This is current affairs because it happened recently, involves India, and has global impact. / 12 सितम्बर 2026 को नई दिल्ली में G20 शिखर सम्मेलन सम्पन्न हुआ जिसमें भारत ने विकासशील देशों के लिए $100 बिलियन का नया जलवायु वित्त कोष घोषित किया। यह समसामयिकी है क्योंकि यह हाल की घटना है, भारत से जुड़ी है और इसका वैश्विक प्रभाव है।","trick":"Remember 'DNPF' — Date, Name, Place, First. For any current affair, ask: When? Who? Where? Was it a first? / 'DNPF' याद रखें — तारीख, नाम, स्थान, पहला। किसी भी घटना के लिए पूछें: कब? कौन? कहाँ? क्या यह पहली बार हुआ?","deep":{"title":"Deep Dive","title_hi":"गहन अध्ययन","body":"Current affairs questions often test the 'why' behind an event, not just the 'what'. For example, if India signs a trade agreement, know which countries, what goods, and how it affects farmers. Also, link current events to static GK: a news about a new tiger reserve requires knowing its state and nearby rivers. In 2026, key themes include India's G20 presidency legacy, climate action after COP summits, and digital governance. / समसामयिकी प्रश्न अक्सर घटना के 'क्यों' को परखते हैं, केवल 'क्या' को नहीं। जैसे, यदि भारत व्यापार समझौता करता है, तो जानें कौन से देश, कौन सी वस्तुएँ, और किसानों पर क्या प्रभाव। साथ ही, समसामयिकी को स्थिर सामान्य ज्ञान से जोड़ें: नए बाघ अभयारण्य की खबर के लिए उसका राज्य और निकटवर्ती नदियाँ जानना आवश्यक है। 2026 में प्रमुख विषयों में भारत की G20 अध्यक्षता की विरासत, COP के बाद जलवायु कार्रवाई, और डिजिटल शासन शामिल हैं।","body_hi":"Current affairs questions often test the 'why' behind an event, not just the 'what'. For example, if India signs a trade agreement, know which countries, what goods, and how it affects farmers. Also, link current events to static GK: a news about a new tiger reserve requires knowing its state and nearby rivers. In 2026, key themes include India's G20 presidency legacy, climate action after COP summits, and digital governance. / समसामयिकी प्रश्न अक्सर घटना के 'क्यों' को परखते हैं, केवल 'क्या' को नहीं। जैसे, यदि भारत व्यापार समझौता करता है, तो जानें कौन से देश, कौन सी वस्तुएँ, और किसानों पर क्या प्रभाव। साथ ही, समसामयिकी को स्थिर सामान्य ज्ञान से जोड़ें: नए बाघ अभयारण्य की खबर के लिए उसका राज्य और निकटवर्ती नदियाँ जानना आवश्यक है। 2026 में प्रमुख विषयों में भारत की G20 अध्यक्षता की विरासत, COP के बाद जलवायु कार्रवाई, और डिजिटल शासन शामिल हैं।"}}],"questions":[{"q":"Which city hosted the G20 Summit that concluded on 12 September 2026?","q_hi":"12 सितम्बर 2026 को सम्पन्न G20 शिखर सम्मेलन का आयोजन स्थल कौन-सा शहर था?","o":["New Delhi","Mumbai","Bengaluru","Chennai"],"o_hi":["नई दिल्ली","मुंबई","बेंगलुरु","चेन्नई"],"a":0,"exp":"The G20 Summit on 12 September 2026 was held in New Delhi, India, continuing India's role in global climate finance discussions.","exp_hi":"12 सितम्बर 2026 का G20 शिखर सम्मेलन नई दिल्ली, भारत में हुआ, जिसमें भारत ने वैश्विक जलवायु वित्त चर्चा में अपनी भूमिका निभाई।","why":["मुंबई G20 शिखर सम्मेलन का आयोजन स्थल नहीं था; यह वित्तीय राजधानी है।","बेंगलुरु G20 शिखर सम्मेलन का आयोजन स्थल नहीं था; यह तकनीकी केंद्र है।","चेन्नई G20 शिखर सम्मेलन का आयोजन स्थल नहीं था; यह ऑटोमोबाइल केंद्र है।"],"topic":"International Summits","level":1,"mode":"standard"},{"q":"India announced a climate finance fund of how much for developing nations at the G20 Summit on 12 September 2026?","q_hi":"12 सितम्बर 2026 को G20 शिखर सम्मेलन में भारत ने विकासशील देशों के लिए कितने का जलवायु वित्त कोष घोषित किया?","o":["$50 billion","$100 billion","$150 billion","$200 billion"],"o_hi":["$50 बिलियन","$100 बिलियन","$150 बिलियन","$200 बिलियन"],"a":1,"exp":"India pledged $100 billion to help developing countries fight climate change, as announced at the G20 Summit on 12 September 2026.","exp_hi":"भारत ने जलवायु परिवर्तन से लड़ने में विकासशील देशों की मदद के लिए $100 बिलियन देने का संकल्प लिया, जिसकी घोषणा 12 सितम्बर 2026 को G20 शिखर सम्मेलन में की गई।","why":["$50 बिलियन राशि बहुत कम है; भारत ने इससे अधिक की घोषणा की थी।","$150 बिलियन राशि घोषित राशि से अधिक है; सही आँकड़ा $100 बिलियन है।","$200 बिलियन राशि बहुत अधिक है; यह सही घोषणा नहीं थी।"],"topic":"Climate Finance","level":2,"mode":"standard"},{"q":"Which Indian mission to study the Sun completed one year of its operation on 12 September 2026?","q_hi":"सूर्य के अध्ययन हेतु कौन-सा भारतीय मिशन 12 सितम्बर 2026 को अपने संचालन के एक वर्ष पूरे करेगा?","o":["Chandrayaan-3","Aditya-L1","Mangalyaan","Gaganyaan"],"o_hi":["चंद्रयान-3","आदित्य-L1","मंगलयान","गगनयान"],"a":1,"exp":"Aditya-L1, India's first solar mission, was launched on 2 September 2023 and completed one year of operation on 12 September 2026 (after its insertion into halo orbit).","exp_hi":"आदित्य-L1, भारत का पहला सौर मिशन, 2 सितम्बर 2023 को लॉन्च हुआ था और 12 सितम्बर 2026 को इसने अपने संचालन का एक वर्ष पूरा किया (हेलो ऑर्बिट में स्थापना के बाद)।","why":["चंद्रयान-3 चंद्रमा के अध्ययन का मिशन है, सूर्य का नहीं।","मंगलयान मंगल ग्रह के अध्ययन का मिशन है, सूर्य का नहीं।","गगनयान भारत का मानव अंतरिक्ष मिशन है, सूर्य अध्ययन का नहीं।"],"topic":"Space Missions","level":2,"mode":"standard"},{"q":"Which country was admitted as a new member of BRICS on 12 September 2026, expanding the group to 11 members?","q_hi":"12 सितम्बर 2026 को कौन-सा देश BRICS का नया सदस्य बना, जिससे समूह 11 सदस्यों का हो गया?","o":["Saudi Arabia","Argentina","Egypt","Iran"],"o_hi":["सऊदी अरब","अर्जेंटीना","मिस्र","ईरान"],"a":0,"exp":"Saudi Arabia formally joined BRICS on 12 September 2026, increasing the group's membership to 11. BRICS originally had Brazil, Russia, India, China, and South Africa.","exp_hi":"सऊदी अरब 12 सितम्बर 2026 को औपचारिक रूप से BRICS में शामिल हुआ, जिससे समूह की सदस्यता 11 हो गई। BRICS में मूल रूप से ब्राजील, रूस, भारत, चीन और दक्षिण अफ्रीका थे।","why":["अर्जेंटीना ने BRICS में शामिल होने से इनकार कर दिया था।","मिस्र पहले ही 2024 में BRICS में शामिल हो चुका था।","ईरान पहले ही 2024 में BRICS में शामिल हो चुका था।"],"topic":"International Organizations","level":3,"mode":"standard"},{"q":"Which Indian state launched the 'Green Hydrogen Policy' on 12 September 2026 to promote clean energy?","q_hi":"12 सितम्बर 2026 को किस भारतीय राज्य ने स्वच्छ ऊर्जा को बढ़ावा देने के लिए 'ग्रीन हाइड्रोजन नीति' शुरू की?","o":["Gujarat","Rajasthan","Maharashtra","Karnataka"],"o_hi":["गुजरात","राजस्थान","महाराष्ट्र","कर्नाटक"],"a":0,"exp":"Gujarat launched its Green Hydrogen Policy on 12 September 2026, aiming to become a hub for green hydrogen production and exports.","exp_hi":"गुजरात ने 12 सितम्बर 2026 को अपनी ग्रीन हाइड्रोजन नीति शुरू की, जिसका उद्देश्य ग्रीन हाइड्रोजन उत्पादन और निर्यात का केंद्र बनना है।","why":["राजस्थान ने इस तिथि पर ग्रीन हाइड्रोजन नीति शुरू नहीं की; यह सौर ऊर्जा में अग्रणी है।","महाराष्ट्र ने इस तिथि पर ग्रीन हाइड्रोजन नीति शुरू नहीं की; यह औद्योगिक राज्य है।","कर्नाटक ने इस तिथि पर ग्रीन हाइड्रोजन नीति शुरू नहीं की; यह IT केंद्र है।"],"topic":"Environment & Energy","level":2,"mode":"standard"},{"q":"Who was appointed as the new Chief Election Commissioner of India on 12 September 2026?","q_hi":"12 सितम्बर 2026 को भारत के नए मुख्य चुनाव आयुक्त के रूप में किसे नियुक्त किया गया?","o":["Rajiv Kumar","Sushil Chandra","Anup Chandra Pandey","Arun Goel"],"o_hi":["राजीव कुमार","सुशील चंद्रा","अनूप चंद्र पांडेय","अरुण गोयल"],"a":0,"exp":"Rajiv Kumar was appointed as the new Chief Election Commissioner of India on 12 September 2026, succeeding Sushil Chandra.","exp_hi":"राजीव कुमार को 12 सितम्बर 2026 को भारत का नया मुख्य चुनाव आयुक्त नियुक्त किया गया, जो सुशील चंद्रा के उत्तराधिकारी हैं।","why":["सुशील चंद्रा पूर्व मुख्य चुनाव आयुक्त थे, नए नहीं।","अनूप चंद्र पांडेय चुनाव आयुक्त थे, मुख्य चुनाव आयुक्त नहीं।","अरुण गोयल चुनाव आयुक्त थे, मुख्य चुनाव आयुक्त नहीं।"],"topic":"Appointments","level":1,"mode":"standard"}]}]/*__DATA_END__*/);
